-- ========================================================================
-- LegoDB - Volcado MySQL generado desde lego.db (SQLite)
-- Importar con: mysql -u legodb -p legodb < lego_dump.sql
-- ========================================================================

CREATE DATABASE IF NOT EXISTS legodb
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE legodb;

SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS age_range (
    age_id  INT          NOT NULL AUTO_INCREMENT,
    ages    VARCHAR(20)  NOT NULL,
    min_age INT,
    max_age INT,
    PRIMARY KEY (age_id),
    UNIQUE KEY uq_ages (ages)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS difficulty (
    difficulty_id     INT          NOT NULL AUTO_INCREMENT,
    review_difficulty VARCHAR(100) NOT NULL,
    PRIMARY KEY (difficulty_id),
    UNIQUE KEY uq_difficulty (review_difficulty)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS theme (
    theme_id   INT          NOT NULL AUTO_INCREMENT,
    theme_name VARCHAR(200) NOT NULL,
    theme_type ENUM('LICENSED','ORIGINAL') NOT NULL,
    PRIMARY KEY (theme_id),
    UNIQUE KEY uq_theme_name (theme_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS licensed_theme (
    theme_id INT          NOT NULL,
    licensor VARCHAR(200),
    PRIMARY KEY (theme_id),
    FOREIGN KEY (theme_id) REFERENCES theme(theme_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS original_theme (
    theme_id INT NOT NULL,
    PRIMARY KEY (theme_id),
    FOREIGN KEY (theme_id) REFERENCES theme(theme_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS lego_set (
    prod_id        INT          NOT NULL,
    set_name       VARCHAR(300) NOT NULL,
    piece_count    INT,
    prod_desc      TEXT,
    prod_long_desc TEXT,
    age_id         INT          NOT NULL,
    difficulty_id  INT,
    theme_id       INT          NOT NULL,
    PRIMARY KEY (prod_id),
    FOREIGN KEY (age_id)        REFERENCES age_range(age_id),
    FOREIGN KEY (difficulty_id) REFERENCES difficulty(difficulty_id),
    FOREIGN KEY (theme_id)      REFERENCES theme(theme_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS country (
    country_code CHAR(2)      NOT NULL,
    country_name VARCHAR(100) NOT NULL,
    PRIMARY KEY (country_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS price_listing (
    prod_id      INT     NOT NULL,
    country_code CHAR(2) NOT NULL,
    list_price   DOUBLE  NOT NULL,
    PRIMARY KEY (prod_id, country_code),
    FOREIGN KEY (prod_id)      REFERENCES lego_set(prod_id),
    FOREIGN KEY (country_code) REFERENCES country(country_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS review_summary (
    prod_id          INT    NOT NULL,
    num_reviews      INT,
    star_rating      DOUBLE,
    play_star_rating DOUBLE,
    val_star_rating  DOUBLE,
    PRIMARY KEY (prod_id),
    FOREIGN KEY (prod_id) REFERENCES lego_set(prod_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS app_user (
    user_id       INT          NOT NULL AUTO_INCREMENT,
    username      VARCHAR(150) NOT NULL,
    password_hash VARCHAR(256) NOT NULL,
    PRIMARY KEY (user_id),
    UNIQUE KEY uq_username (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS idx_set_theme      ON lego_set(theme_id);
CREATE INDEX IF NOT EXISTS idx_set_age        ON lego_set(age_id);
CREATE INDEX IF NOT EXISTS idx_set_difficulty ON lego_set(difficulty_id);
CREATE INDEX IF NOT EXISTS idx_price_country  ON price_listing(country_code);

