INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (630, 'Brick Separator', 1, 'Everyone needs one!', 'This tool makes it a snap to pull those small plates apart.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (2304, 'Green LEGO® DUPLO® Baseplate', 1, 'Start creations here!', 'Even big imaginations need a place to start--and our baseplates do the job.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (7280, 'Straight & Crossroad Plates', 2, 'Add roads to your LEGO® town!', 'Expand your LEGO® town with this set of straight and crossroad plates. Includes one straight plate and one cross plate.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (7281, 'T-Junction & Curved Road Plates', 2, 'Roads for your LEGO® layout!', 'Add a T-junction and curved roads to your LEGO® town with this set of building plates. Includes one T-junction plate and one curved road plate.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (7499, 'Flexible and Straight Tracks', 24, 'Get killer curves in your tracks!', 'Add flexible train tracks to your locomotive system to connect and move around obstacles and awkward shapes! Extend your rails to make your engines go places they never have before! Includes 8 straight tracks and 16 flexible tracks.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (7895, 'Switching Tracks', 8, 'Switch tracks – build a bigger, more exciting railway track.', 'Switch tracks to help make your track even longer. No electricity – works with IR train sets #7897 and 7898, and can be combined with track sets #4515, 4519 and 4520.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (8293, 'Power Functions Motor Set', 10, 'Motorize your LEGO® Technic creations with the Power Functions Motor Set!', 'Bring your LEGO® Technic models to life with the exciting Power Functions Motor Set. This supplementary power set comes with a medium motor, battery box, switch and a light cable with 2 bright LEDs. Power up your LEGO Technic creations!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (9843, 'Touch Sensor', 1, 'Your robot\'s "fingers!"', 'The Touch Sensor reacts to touch and release, enabling your LEGO® MINDSTORMS® NXT robotic creation to "feel" like never before! It can detect single or multiple button presses, and reports back to the NXT Intelligent Brick (sold separately.)
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10214, 'Tower Bridge', 4295, 'Build London\'s famous Tower Bridge!', 'Stretching over the River Thames since 1894, the famous Tower Bridge of London, England is one of the most recognizable landmarks in the world. Now you can add this timeless classic to your LEGO world buildings collection! Designed with advanced building techniques and rare colors and elements, the Tower Bridge is complete with its iconic paired towers and a drawbridge that really opens. Fun to build and display, it locks together solidly but can be taken apart in sections for easy transport. Includes 4 miniature vehicles; a black London taxi, a traditional red double-decker bus, a yellow truck and a green automobile. Completed model measures 40" (102 cm) long, 17" (45 cm) high and 10" (26 cm) wide.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10220, 'Volkswagen T1 Camper Van', 1334, 'Road trips will never be the same again with the iconic 1962 Volkswagen T1 Camper Van', 'This authentic camper van is a replica of the classic Volkswagen Camper Van from 1962. Every iconic feature is here! On the outside, the terrific detailing includes \'V\' shape three-way color split at the front, rounded roof and window frames, opening \'splittie\' safari windshield, opening doors, iconic pop-up roof with textile curtain surround, roof rack, rear side air intake vents and lots more! The detailing is equally impressive on the inside, from the authentic VW air-cooled flat four cylinder boxer engine, front cabin bench seat, gear stick, angled dashboard and iconic spherical speedometer, to custom LEGO® features like folding rear bench seat, folding dinette table, closet with mirror and even a painting!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10242, 'MINI Cooper', 1077, 'Take this MINI Cooper for a nostalgic drive down memory lane!', 'Take the iconic MINI Cooper for a drive! This beautifully crafted LEGO® brick replica of the classic MINI Cooper Mk VII is full of authentic details, from the classic green and white colour scheme with white wing mirrors and racing stripes, to the opening doors, hood and trunk, sporty fog lights, detailed engine and separate spare tire compartment. You can even remove the roof to access a tan colored interior with patterned seats, veneer-style dashboard, turning steering wheel, and moving gearshift and handbrake. And of course, no MINI Cooper would be complete without a picnic basket and blanket, the perfect accessories for a fun day in the countryside!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10243, 'Parisian Restaurant', 2469, 'Have an unforgettable evening at the amazing Parisian Restaurant!', 'It’s very busy in the Parisian Restaurant! As a scooter zips by, inside the waiter rushes between the tables as the nervous young man gets ready to propose with the ring! It’s just as hectic behind the scenes, with the chef busily preparing the food. This beautifully detailed building is the setting for so many stories and is a great addition to the modular building series. The Parisian Restaurant has a fully-stocked, blue and white tiled kitchen with tableware as well as a cozy apartment with pull-down bed, kitchenette and fireplace. On the top floor is the artist’s room with a studio that includes a cast iron heater, easel, paintbrush and two works of art by the aspiring artist. Outside, stairs lead down to the roof terrace lined with hanging lanterns and flowers where the diners eat alfresco-style. This amazing Parisian Restaurant model even includes a facade with croissants, clams and feather details that recapture the feel of Paris. Includes 5 minifigures: chef, waiter, girl and a romantic couple.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10246, 'Detective’s Office', 2262, 'Discover hidden clues and surprises at the Detective\'s Office!', 'Discover a world of mystery and adventure with the LEGO® Creator Expert Detective’s Office! Step through the open archway and into the barbershop, where seated customers are pampered in the reflection of a large wall mirror, while next door, competitors play pool and darts beneath the comforting whir of a rotating ceiling fan. Venture to the first floor and you’ll find the detective’s office, his desk strewn with clues, a safe containing valuable evidence and a concealed wall compartment. Then visit the adjacent bathroom, featuring a classic pull-chain toilet, before taking the stairway to the well-equipped kitchen, from where you can access the roof terrace, complete with large water tower. This latest addition to the LEGO Modular Building series is packed with unsurpassed detail and hidden surprises. Easy-to-remove roof and ceilings provide access to the delightful interior, while the exterior of the building features a decorative roofline and a beautifully designed façade. Can you solve the smuggling mystery? Includes 6 minifigures with assorted accessories: Detective Ace Brickman, Al the barber, dart player, pool player, police woman and a mysterious lady in red.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10247, 'Ferris Wheel', 2464, 'Experience the wonderful LEGO® Creator Ferris Wheel!', 'LEGO® Creator Expert model has an iconic elegance that evokes feelings of nostalgia, romance and adventure. The carnival has come to town and the ice cream vendor is busy serving a long queue of excited customers as they await their first ride on the magical Ferris Wheel that towers above the fairground. Slowly turn the crank and watch as the Ferris Wheel gracefully lowers the colorful gondolas into position for boarding. Raise the boarding platform with a simple pull of the lever, open the gondola door and help the passengers aboard! Have fun building this elegant model with an authentic charm and magic that will capture your imagination. You can also motorize the Ferris Wheel with the LEGO Power Functions 8883 medium motor and 88000 AAA battery box (not included). Includes 10 minifigures: a ride operator, ice cream vendor, 4 children and 4 adults.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10249, 'Winter Toy Shop', 898, 'Enjoy the holiday season with the Winter Toy Shop!', 'Welcome to the Winter Toy Shop! The holiday season has arrived and the toymaker is busy finishing off his latest creations! Outside, children ski and snowboard, and a freshly built snowman sparkles in the light that shines from the toyshop tower. Help decorate the huge tree that stands at the center of the square, play with the curious kitten on the cozy wooden bench or join in with the carolers beneath the ornate streetlamp. This charming set also features a ladder, trees in various sizes, jack-in-the-box, a toy biplane, helicopter, rocket, train, race car, truck, robot, tugboat, teddy bear and a wrapped gift. Have fun building this enchanting winter wonderland! Includes a snowman and 8 minifigures with assorted accessories: a male caroler, female caroler, a woman, 2 men, 2 boys and a girl.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10251, 'Brick Bank', 2382, 'Make a safe deposit at the Brick Bank!', 'Make a secure deposit at the highly respected Brick Bank, featuring an array of intricate details and hidden surprises. Easy-to-remove building sections provide access to the detailed interior, comprising a bank with an atrium foyer, tiled floor, arched windows, ornate chandelier, lockable vault and a transaction counter with security glass; a laundrette with printed window, tiled floor and 4 washing machines; plus 2 second-floor offices with an array of detailed furniture, fixtures and accessories. The exterior of the building features a detailed sidewalk and an elaborate façade with carving and statue décor, decorative roofline, large arched windows, central balcony, clock and an accessible roof terrace featuring a large skylight. Collect and build an entire town with the LEGO® Creator Expert Modular Building series 10243 Parisian Restaurant and 10246 Detective\'s Office. Includes 5 minifigures: a bank manager, secretary, cashier, Mum and child.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10252, 'Volkswagen Beetle', 1167, 'Head for the beach with the VW Beetle!', 'Celebrate the iconic VW Beetle with this awesome LEGO® Creator Expert reproduction. This detailed model comprises a number of special features and elements that help recreate the distinctive Beetle characteristics, including an azure-blue colour scheme, curved fenders, flat windshield, VW logo, and an authentic 4-cylinder air-cooled engine and fuel tank. The accessible interior features beige-coloured, forward-tilting seats, dashboard and steering wheel, and the roof-mounted surfboard and a cooler box can be removed. This model has been designed to provide a challenging and rewarding building experience with a touch of nostalgia.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10253, 'Big Ben', 4163, 'Build the world’s best-known clock tower!', 'Get up close to Big Ben! The clock was first started on May 31st 1859, and Big Ben’s first chime rang from the 96-meter Elizabeth Tower on July 11th of the same year. This over 23” (60cm) high LEGO® interpretation of the iconic structure is a tribute to its engineering and architecture. It features a detailed facade with statues, shields and windows, and a clock tower with 4 adjustable clock dials and a removable roof allowing access to the belfry, plus buildable exterior elements including a sidewalk, lawn and a tree depicting the building’s location. This model makes a great display piece for the home or office.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10254, 'Winter Holiday Train', 734, 'Climb aboard the magical Winter Holiday Train!', 'Gather the family for some festive LEGO® building fun with this charming model featuring a full circle of track, boarding platform with bench and lamppost, a Power Functions upgradable train engine with brick-built smoke bellowing from its stack, coal tender, flatbed wagon with a rotating holiday tree, toys and gifts, and a red caboose with a detailed interior and table. The train engine also features large and small red-colored locomotive wheels and the train is decorated with green wreathes, string lights and white tree elements. This LEGO® Creator Expert set includes 5 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10255, 'Assembly Square', 4002, 'Celebrate ten years of Modular Building with the Assembly Square!', 'Take a trip to the amazing Assembly Square, developed to celebrate ten years of LEGO® Modular Buildings, featuring a wealth of unsurpassed, intricate details and hidden surprises. Easy-to-remove building sections provide access to the highly detailed interior, comprising a ground level with a bakery, florist’s shop and café, a middle level with a music store, photo studio and dental office, and an upper-level dance studio and apartment with access to a rooftop terrace with barbecue. The exterior of the building features a detailed sidewalk with outdoor café furniture, fountain, streetlamps and a highly elaborate facade with beautifully detailed windows and doors, three buildable shop signs, spired tower and a decorative roofline. Collect and build an entire town with the LEGO Creator Expert Modular Building series 10243 Parisian Restaurant, 10246 Detective’s Office and 10251 Brick Bank. Includes eight minifigures and a baby figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10256, 'Taj Mahal', 5923, 'Discover the architectural wonder of the Taj Mahal!', 'Build and discover the Taj Mahal! The huge ivory-white marble mausoleum, renowned as one of the world’s architectural wonders, was commissioned in 1631 by the Emperor Shah Jahan in memory of his wife, the Empress Mumtaz Mahal. This relaunched 2008 LEGO® Creator Expert interpretation features the structure\'s 4 facades with sweeping arches, balconies and arched windows. The central dome, subsidiary domed chambers and surrounding minarets are topped with decorative finials, and the raised platform is lined with recessed arches. The model is finished with ornate detailing throughout and intricate tilework around the base. With more than 5,900 pieces, this set is designed to deliver a rewarding building experience and makes a great display piece for the home or office.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10257, 'Carousel', 2670, 'Discover the fairground’s star attraction with the Carousel!', 'Experience the majestic Carousel with a wealth of delightful features, including a large textile canopy, ornate reflective rounding boards with blue and gold detailing, reflective center panels, and a 2-tier deck comprising a raised boarding platform with handrail and a main platform with 5 buildable animal rides, including a white swan and 4 moving animals. Turn the crank and see the elephant, tiger, flamingo and frog move up and down as the carousel rotates. This delightful LEGO® Creator Expert model has an iconic elegance that evokes feelings of nostalgia, romance and adventure. Upgrade with LEGO Power Functions for fully motorized operation. Includes 7 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10258, 'London Bus', 1686, 'All aboard the London Bus!', 'Celebrate iconic design with this charming double-decker London Bus, featuring a wealth of authentic details, including a bright-red color scheme, panoramic windshield, specially made standard-tread tires, destination sign, and an open rear boarding deck with a hand pole, ticket bin, fire extinguisher and a half-spiral staircase that leads to the upper sightseeing deck. Functions include an opening hood with engine, detailed driver’s cab with a sliding door, and a removable roof and upper deck for access to the detailed interior with worn look seating and additional authentic details, including a forgotten umbrella, newspaper, empty beverage can and discarded chewing gum. Reversible transit advertising posters are also provided as printed labels with a 1950s or present-day London promotion. This LEGO® Creator Expert model has been designed to provide a challenging and rewarding building experience with a touch of nostalgia and charm.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10259, 'Winter Village Station', 902, 'Head home for the holidays with the Winter Village Station!', 'Head for home with the festive Winter Village Station holiday set, featuring a snowy railroad station with wreath adorned lampposts and clock tower, platform, mailbox, green trees, snowy grade crossing with twin barriers and lights, and a beautiful, festively decorated bus with opening doors and a luggage rack with removable luggage and gift wrapped packages. This LEGO® Creator Expert model also includes a ticket counter with a timetable and a transaction counter window with room for sliding out tickets to travelers, plus a coffee shop with a serving hatch and a detailed interior with an espresso machine, cups, cash register and a menu. Includes 5 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10260, 'Downtown Diner', 2480, 'Discover a place where music is on the menu!', 'Drop in at the LEGO® Creator Expert 10260 Downtown Diner, where you’ll discover a healthy portion of fun and surprises. This impressive model features removable building sections for easy access to the detailed interior, which comprises a ground-level 1950s-style diner with a large curved front window, red bar stools, jukebox, counter and an open-plan kitchen. The mid level has a gym with boxing ring, punching bag and weight training room, while on the upper-level you\'ll find a recording studio, complete with vocal booth, mixing desk and a refreshments cabinet. The facade of the building features pink-and-teal Streamline Moderne styling with a large ‘DINER’ sign. Other external features include arched windows, balconies and a staircase, plus a pink convertible car and a detailed sidewalk, complete with mailbox, parking meter, flowerpots and a streetlamp. This incredible collectible toy has been designed to provide a challenging and rewarding building experience with a touch of nostalgia and charm. Includes 6 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10507, 'My First Train Set', 52, 'Hop aboard My First Train Set for beginning builder fun!', 'Introduce your child to the world of trains and building with the LEGO® DUPLO® My First Train Set. Create the colorful steam train with sound effects, a passenger wagon, station with ticket window, fueling pump and signal. With a lot of DUPLO bricks and track, it\'s the perfect set for budding builders and hours of train-themed creative play. Requires 3 AA (1.5V) batteries (not included). Includes train driver and child DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10508, 'Deluxe Train Set', 134, 'Take the rocks down the track with the Deluxe Train Set!', 'Take LEGO® DUPLO® train building to the next level with the Deluxe Train Set featuring a cool modern train! Jump aboard the locomotive with real sound effects and fill up the wagons with rocks at the quarry. Then unload them with the working crane before fueling up for the next trip! Set features more than 64 inches of track, a bridge with tunnel, truck, DUPLO-brick stone quarry, building with working crane and lots of colorful DUPLO elements and 3 DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10572, 'LEGO® DUPLO® All-in-One-Box-of-Fun', 65, 'Learn to discover, build and count with the All-In-One Box of Fun!', 'The LEGO® DUPLO® All-In-One Box of Fun set has a whole load of DUPLO bricks for fun building and rebuilding for creative play. At its heart is a buildable wagon base with rounded edges and wheels that really turn. This comprehensive set also includes 2 opening window elements, a cute dog and numbered bricks with corresponding decorated bricks to help your child develop their counting skills. There are even extra classic DUPLO bricks for more creative fun. Includes a boy DUPLO figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10590, 'Airport', 29, 'Head off on your holidays with the LEGO® DUPLO® Airport!', 'Get ready for take-off at the LEGO® DUPLO® Airport! Build the luggage check-in and make sure your suitcases are taken to the plane. Drive the refueling truck over to fill up the plane. Then help the pilot take his seat and make sure all the passengers are on board ready to fly away. This set will keep any little pilot entertained as they master early building skills and enjoy playing with the two iconic airport vehicles. Use this set to talk to your child about what happens at the airport beforetheir first trip on a plane! DUPLO bricks are brightly colored and designed especially to be safe for smaller hands. Includes three DUPLO figures: a passenger, pilot and an airport worker.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10592, 'Fire Truck', 26, 'Rush to save the burning building in the LEGO® DUPLO® Fire Truck!', 'Jump onto the LEGO® DUPLO® Fire Truck and save the day! Rush to the burning building and help the firefighter winch himself up in the crane. When he’s high enough to tackle the flames, use the retractable hose to put out the fire. Then climb through the window to make sure the building is all clear. Young children will love creating endless rescue adventures with this easy to build set, designed to encourage early construction skills. Use this set to talk to children about fire safety and the important work of firefighters in our communities. DUPLO bricks are made to be fun and safe for smaller hands. Includes a firefighter LEGO DUPLO figure. Combine with the 10591 Fire Boat and 10593 Fire Station for even more fire rescue adventures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10597, 'Mickey & Minnie Birthday Parade', 24, 'Celebrate your birthday with Mickey and Minnie!', 'All aboard the Mickey Mouse Clubhouse birthday train as Mickey and Minnie throw a parade in your honor! Load up the train with everything you need for the perfect birthday party—a buildable cake, balloons and decorated gift bricks. How old are you today? With decorated age bricks numbered from 1 to 5, Mickey and Minnie can bring birthday fun year after year. Young children will love the endless birthday role-play opportunities and developing their construction skills with the big, bright LEGO® DUPLO® bricks designed especially for budding builders. Includes 2 LEGO DUPLO figures: Mickey Mouse and Minnie Mouse.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10606, 'Doc McStuffins™ Backyard Clinic', 39, 'Help toys feel better in Doc McStuffins™’ Backyard Clinic!', 'The Doc is in! Help Doc McStuffins™ and friends Lambie and Stuffy look after all her toys in the Backyard Clinic! Susie Sunshine is sick and needs Doc to make her feel better. Time for check-up with the medical tools to find out what the problem is. Lambie is on hand to pass a blanket or a bandage if they are needed. The special two-sided decorated brick can be turned around to show Susie sick and then when she is cured. When Doc’s work is done for the day, it’s time to play on the slide with allher friends! This LEGO® DUPLO® brand Doc McStuffins set provides endless role-play opportunities for young children to treat injured toys, while encouraging early construction skills through building and rebuilding the clinic.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10607, 'Spider-Man Web-Bike Workshop', 13, 'Tune up the motorcycle in Spider-Man\'s workshop!', 'Get to work with Marvel’s Spider-Man to make his Web-Bike go even faster! Top up the oil and make some adjustments with the wrench. Then do some motorbike tricks on the ramp. Find the decorated spider-brick in the cupboard and create your own stories before Spider-Man speeds off on his next rescue mission. Includes one LEGO® DUPLO® figure: Spider-Man. Combine with the 10608 Spider-Man Spider Truck Adventure for more road-based action.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10608, 'Spider-Man Spider Truck Adventure', 28, 'Lock up Green Goblin in Spider-Man\'s amazing Spider Truck!', 'Help Marvel’s Spider-Man stop Green Goblin from stealing the money! Use the tracking device and radar in Spider-Man’s amazing Spider Truck to find where he is hiding, then head to the scene to hunt him down. But be careful, as Green Goblin is planning to defend himself by throwing pumpkins! Team up with Spider-Man to capture him and lock him away in the secure jail cell inside the Spider Truck. Then drive him away and get ready for your next adventure. Includes 2 LEGO® DUPLO® figures: Spider-Manand Green Goblin. Combine with the 10607 Spider-Man Web-Bike Workshop for more Spider-Man road-based action.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10615, 'My First Tractor', 12, 'Learn about colors and fruits with this easy-to-build set!', 'Play and learn with LEGO® DUPLO® My First Tractor! Put the chunky pieces together to build the tractor, then stack and unload the colorful fruits in the basket. Teach your child about colors and fruits with the special decorated bricks. Start your stories with this easy-to-build set including large DUPLO bricks that are designed especially to be safe and suitable for little hands. Includes 2 child DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10616, 'My First Playhouse', 25, 'Learn about daily routines with this easy-to-build set!', 'Play and learn at LEGO® DUPLO® My First Playhouse! Combine the chunky pieces to build the playhouse as a perfect introduction to basic construction skills. The special decorated bricks showing key parts of the daily routine provide talking points for you and your toddler so you can teach them about their day. The turnable night/day brick helps set the scene for learning and role play. Start your stories with this easy-to-build set and help the 2 DUPLO figures get up in the morning, eat breakfast, brush their teeth, and have fun on the slide before lying them down in the beds to rest. The brightly colored DUPLO bricks are designed especially to be safe and suitable for little hands. Includes 2 child DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10687, 'Spider-Man™ Hideout', 137, 'Protect the Spider-Man™ Hideout against an aerial assault from Green Goblin!', 'Help Marvel’s Spider-Man™ defend his hideout from the evil Green Goblin! First put together the Easy to Build hideout, then jump into action as Green Goblin pelts it with pumpkin bombs from his air glider. Launch Spider-Man’s helicopter and use the web thrower to stop him. Then bring in the police officer on his motorbike to help out Spider-Man™. Designed for an easy start with the LEGO® brick, LEGO Juniors sets come with easy instructions and quick start elements to get the play started sooner.Includes 3 minifigures: Spider-Man, Green Goblin and a police officer.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10692, 'LEGO® Creative Bricks', 221, 'Get creative with classic LEGO® bricks in 29 different colors!', 'Dig into this selection of LEGO® bricks and let your imagination run away with you! The building possibilities are endless, with classic bricks in 29 different colors and special pieces including doors, windows, wheels, eyes and propellers. And if you don’t know where to start, you can find instructions with some ideas to get you going. This is an ideal set to help budding builders of all ages get creative, and would complement any existing LEGO collection.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10693, 'LEGO® Creative Supplement', 303, 'Get ideas, get creative and get building!', 'Get busy building whatever you imagine with this colorful set of LEGO® bricks in different shapes and sizes! From space rockets and robots to dinosaurs and sharks, this set gives budding builders of all ages the versatility to be really creative and makes a great addition to any existing LEGO collection. There are LEGO bricks in 20 different colors, as well as 2 pairs of eyes to help you walk on the wild side. So let your imagination fly! And if you’re stuck for ideas, the instructions will helpto get you started.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10694, 'LEGO® Creative Supplement Bright', 303, 'Build whatever your heart desires with LEGO® bricks in 20 different bright colors!', 'Follow your imagination with this pile of brightly colored classic LEGO® bricks! From butterflies and flowers to guitars and cakes, this set comes with bricks in 20 different bright colors to help you create whatever you imagine. With 4 pairs of eyes for creating all kinds of creatures, this set also comes with ideas to help you get started. Designed for builders of all ages, it’s a great addition to any existing LEGO collection.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10696, 'LEGO® Medium Creative Brick Box', 484, 'Create your own LEGO® vehicles with LEGO Classic!', 'Designed with builders of all ages in mind, this collection of LEGO® bricks in 35 different colors will encourage open-ended building play, and inspire any imagination. Windows, eyes, and lots and lots of wheels add to the fun and offer endless possibilities for creative construction and vehicle play. A great supplement set to any existing LEGO collection, this set comes in a convenient plastic storage box and includes ideas to get the building started.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10698, 'LEGO® Large Creative Brick Box', 790, 'Create all kinds of buildings with LEGO® bricks, windows and doors!', 'Build up a storm with this big box of classic LEGO® bricks in 33 different colors. With lots of different windows and doors, along with other special pieces to inspire you, you can really run with your imagination. With some ideas to get you started, this set provides the perfect creative toolkit for budding builders of all ages to enjoy some classic LEGO construction. It comes in a convenient plastic storage box and is an ideal supplement to any existing LEGO collection.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10699, 'Sand Baseplate', 1, 'Add another useful piece to your LEGO® collection with this Sand Baseplate!', 'Whether you’re creating a beach, zoo, desert, or something of your own imagination, this sand-colored 32x32-stud baseplate is the perfect starting point for building, displaying, and playing with your LEGO® creations.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10700, 'Green Baseplate', 1, 'Add another useful piece to your LEGO® collection with this Green Baseplate!', 'Whether you’re creating a garden, forest, or something of your own imagination, this green-colored 32x32-stud baseplate is the perfect starting point for building, displaying, and playing with your LEGO® creations.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10701, 'Gray Baseplate', 1, 'Add another useful piece to your LEGO® collection with this Gray Baseplate!', 'Whether you’re creating a street scene, castle, or something of your own imagination, this gray-colored 48x48-stud baseplate is the perfect starting point for building, displaying, and playing with your LEGO® creations.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10703, 'Creative Builder Box', 502, 'Create your ideas with LEGO® Classic bricks!', 'Unleash a world of open-ended creativity and imagination with the LEGO® Classic Creative Builder Box. Imaginative building play is easy with these bright, colorful versatile LEGO bricks, including a wide selection of doors and windows, shapes and special elements for creating all kinds of buildings. This set provides three levels of building complexity and includes an inspirational guide to help your child discover their creative building skills.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10704, 'Creative Box', 900, 'Imagine and create with LEGO® Classic bricks!', 'Unleash a world of open-ended creativity and imagination with the LEGO® Classic Creative Box. Imaginative building play is easy with these bright, colorful and versatile LEGO bricks in 39 colors. There are wheels, doors, windows and eyes and a mix of special elements, plus an inspirational guide with building instructions and ideas that will help your child discover their creative building skills. This set provides three levels of building complexity and makes a great addition to existing LEGO sets.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10706, 'Blue Creativity Box', 78, 'Unleash your imagination with the LEGO® Blue Creativity Box!', 'Unleash a world of open-ended creativity and imagination with the LEGO® Classic Blue Creativity Box, featuring vibrant shades of blue and fun bright colors. Imaginative building play is easy with these versatile LEGO bricks and special pieces, plus an inspirational guide with age-appropriate building instructions and ideas that will help your child discover their creative building skills. This set provides three levels of building complexity, and also makes an excellent starter set for budding LEGO builders.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10707, 'Red Creativity Box', 55, 'Unleash your imagination with the LEGO® Red Creativity Box!', 'Unleash a world of open-ended creativity and imagination with the LEGO® Classic Red Creativity Box, featuring vibrant shades of red and fun bright colors. Imaginative building play is easy with these versatile LEGO bricks, including a mix of special pieces, plus an inspirational guide with age-appropriate building instructions and ideas that will help your child discover their creative building skills. This set provides three levels of building complexity, and also makes an excellent starter set for budding LEGO builders.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10708, 'Green Creativity Box', 66, 'Unleash your imagination with the LEGO® Green Creativity Box!', 'Unleash a world of open-ended creativity and imagination with the LEGO® Classic Green Creativity Box, featuring vibrant shades of green and fun bright colors. Imaginative building play is easy with these versatile LEGO bricks, including a mix of special pieces, plus an inspirational guide with age-appropriate building instructions and ideas that will help your child discover their creative building skills. This set provides three levels of building complexity, and also makes an excellent starter set for budding LEGO builders.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10709, 'Orange Creativity Box', 60, 'Unleash your imagination with the LEGO® Orange Creativity Box!', 'Unleash a world of open-ended creativity and imagination with the LEGO® Classic Orange Creativity Box, featuring vibrant shades of orange and fun bright colors. Imaginative building play is easy with these versatile LEGO bricks, including a mix of special pieces, plus an inspirational guide with age-appropriate building instructions and ideas that will help your child discover their creative building skills. This set provides three levels of building complexity, and also makes an excellent starter set for budding LEGO builders.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10713, 'Creative Suitcase', 213, 'Bring along a world of creativity in your own LEGO® Creative Suitcase!', 'Create, play and pack neatly away with this smart and convenient LEGO® Classic Creative Suitcase, featuring a selection of brightly colored LEGO building bricks including bricks, eyes, wheels and shapes, for building all kinds of houses, vehicles, creatures and creations. Open the case to access multiple compartments for sorting and storing LEGO pieces. This set also includes simple, age-appropriate building instructions that will help children discover their own creative building skills.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10714, 'Blue Baseplate', 1, 'Create your own world on a Blue LEGO® Baseplate!', 'Whether you are creating a seaside town, sunny swimming pool, ship at sea or something else from your imagination, this blue 32x32-stud baseplate is the perfect starting point for building, displaying and creative play with your LEGO® creations.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10715, 'Bricks on a Roll', 442, 'Create a world in motion with Bricks on a Roll!', 'Put your LEGO® creations on wheels with this exciting LEGO Classic toy, featuring a wide selection of wheels and tires in a variety of colors and sizes, plus a colorful selection of LEGO pieces, including bricks, shapes and eyes. This set makes a great addition to existing LEGO sets and includes age-appropriate building instructions that will help your child discover their creative building skills.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10720, 'Police Helicopter Chase', 63, 'Catch the thief and protect the ATM with the Police Helicopter Chase!', 'Join the police and be a hero with the LEGO® Juniors Police Helicopter Chase, featuring a helicopter with spinning propellers, an ATM and accessories. This LEGO® Juniors set offers an easy start to building with the LEGO brick for ages 4-7, with easy-to-assemble models featuring iconic reality-based hero adventures. Includes 2 minifigures: a police officer and a crook.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10722, 'Snake Showdown', 92, 'Help Kai protect the golden snake staff and stop Lasha!', 'Be part of the action in LEGO® Juniors NINJAGO™, and help Kai battle Lasha the snake villain for the golden snake staff, featuring a super Ninja car, motorbike and other accessories. This LEGO® Juniors set offers an easy start to building with the LEGO brick for ages 4-7, with easy-to assemble models featuring iconic Ninja adventures. Includes 2 minifigures: Kai and Lasha the snake villain.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10723, 'Ariel’s Dolphin Carriage', 70, 'Ride the waves with Ariel and Flounder as she explores new worlds in her dolphin carriage!', 'Enter the magical world of LEGO® Juniors Disney Princess™ with Ariel\'s dolphin-drawn carriage, plus underwater castle with a chair, mirror, shell seat and drawer that opens and closes, and plenty of accessories. LEGO Juniors is an age-appropriate building experience for ages 4-7, with easy-to assemble models that feature Disney\'s beloved classic story of Ariel. Includes mini-doll: Ariel, her best friend Flounder and dolphin.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10725, 'Lost Temple', 172, 'Discover the Lost Temple and help Lloyd win the Sword of Fire!', 'Join the adventure with Lloyd and Jay, as they fight to get to the Sword of Fire before the snake villain. Featuring Jay\'s blue dragon, the snake villain\'s helicopter, the Lost Temple with lava ball, and other accessories. This LEGO® Juniors set offers an easy start to building with the LEGO brick for ages 4-7, with easy-to assemble models featuring iconic Ninja adventures. Includes 3 minifigures: Lloyd, Jay and a snake villain.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10726, 'Stephanie\'s Horse Carriage', 58, 'Plan a day of riding with friends!', 'Go on a carriage ride with Stephanie and her horse. This colorful set features a carriage with rolling wheels and space in the back for a basket with green apple, a stable with fence, feed basket and carrot, a stand with grooming brush and saddle, a crate with pitchfork, and bows. LEGO® Juniors sets are age-appropriate building experiences for ages 4-7, with fun and recognizable LEGO Friends sets that give children a great start with the LEGO brick. Includes a mini-doll plus a horse.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10730, 'Lightning McQueen Speed Launcher', 47, 'Power on and win with Disney•Pixar’s Lightning McQueen!', 'Join in the exciting Disney•Pixar Cars 3 racing world with Lightning McQueen’s Speed Launcher, featuring a race leaderboard, starting ramp and a launch function with a red button. Includes a simple guide to build and play, and bigger pieces help build confidence in younger kids. LEGO® Juniors is an age-appropriate build and play experience for ages 4-7. Includes a Lightning McQueen LEGO Juniors character.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10731, 'Cruz Ramirez Race Simulator', 59, 'Help Disney•Pixar’s Cruz Ramirez become the fastest race car around!', 'Be part of the exciting Disney•Pixar Cars 3 racing world with Cruz Ramirez and her Race Simulator, featuring a rotating screen, ramp and turbine fan to test Cruz’ racing skills. Includes a simple guide to build and play, and bigger pieces help build confidence in younger kids. LEGO® Juniors is an age-appropriate build and play experience for ages 4-7. Includes a Cruz Ramirez LEGO Juniors character.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10732, 'Guido and Luigi\'s Pit Stop', 75, 'Pull in to Disney•Pixar’s Guido & Luigi’s Pit Stop for fun and games!', 'Join in the Disney•Pixar Cars 3 fun at Guido & Luigi’s Pit Stop, featuring an air hose, fuel can and spare tire accessory elements and a number 95 pit sign. Includes a simple guide to build and play, and bigger pieces help build confidence in younger kids. LEGO® Juniors is an age-appropriate build and play experience for ages 4-7. Includes Guido and Luigi LEGO Juniors characters.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10733, 'Mater\'s Junkyard', 62, 'Take a break at the junkyard with Disney•Pixar’s Mater and his video screen!', 'Join Mater in his Easy to Build junkyard as he chats with Lightning McQueen on the video screen, featuring a movable crane and Tow Mater sign. Use the crane to lift the assorted car parts out of the box and attach them to the buildable tow truck, and have fun testing them on this lovable Disney•Pixar Cars 3 character. Includes a simple guide to build and play, and bigger pieces help build confidence in younger kids. LEGO® Juniors is an age-appropriate build and play experience for ages 4-7. Includes a Mater LEGO Juniors character.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10734, 'Demolition Site', 175, 'Tear it down and build it again!', 'Grab your hard hat and get to work on the LEGO® City construction site, featuring Easy to Build vehicles including a dump truck, digger with rotating back arm, and a demolition crane with wrecking ball, plus a building under construction. Designed for those new to construction play, LEGO Juniors sets are age-appropriate build and play experiences for children 4-7. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10735, 'Police Truck Chase', 90, 'Catch the crook before he gets away!', 'Join the LEGO® City police force and catch the crook, featuring Easy to Build models including a police truck with holding cell, roadblock with swinging gate, plus a motorbike for the crook and a jewel element. LEGO Juniors sets are age-appropriate build and play experiences for children 4-7. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10736, 'Anna & Elsa\'s Frozen Playground', 94, 'Play in the snow with Anna and Elsa at the ice palace!', 'Play in a magical winter playground with LEGO® Juniors Disney Frozen´s Anna and Elsa, featuring an Easy to Build ice palace with slide, bench and table, ramp for skiing, rotating fountain, snowball-firing catapult and an opening treasure chest with hidden ice crystals. LEGO Juniors is an age-appropriate build and play experience for ages 4-7. Includes two mini-doll figures and a polar bear cub.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10737, 'Batman™ vs. Mr. Freeze™', 63, 'Battle Mr. Freeze™ with Batman™ and his Batboat on the Gotham City Sea!', 'Be part of the action-filled world of Batman™ with an Easy to Build floating Batboat featuring an opening cockpit and bat-disc shooter, Mr. Freeze’s ice speeder and freeze gun with ice crystal, plus an ice jail with an ice crystal. LEGO® Juniors is an age-appropriate build and play experience for ages 4-7. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10738, 'Snow White\'s Forest Cottage', 67, 'Help Snow White choose a pie to bake for her animal friends!', 'Stop by for a visit at Disney Snow White’s Forest Cottage, featuring an oven and chimney, tree with fruit and a picnic table for Snow White and her animal friends. Includes a simple guide to build and play, and bigger pieces help build confidence in younger kids. LEGO® Juniors is an age-appropriate build and play experience for ages 4-7. Includes a mini-doll figure and 2 animal figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10739, 'Shark Attack', 108, 'Help Kai and Lloyd save NINJAGO® City from Great White!', 'Team up with Kai and Lloyd for some ninja fun as they battle Great White, featuring a training area with weapon stand, breakable blocks, spinning training dummy, flaming motorcycle and a shark car with flick missiles. This fun THE LEGO® NINJAGO® MOVIE™ set features a simple guide to build and play, and some bigger pieces to help build confidence in younger children. LEGO Juniors is an age-appropriate build and play experience for ages 4-7. Includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10740, 'Fire Patrol Suitcase', 110, 'Help the firefighters battle the blaze!', 'Be prepared for a LEGO® City emergency wherever you are with this fun, easy-to-carry suitcase play set, featuring a fire pickup with adjustable cherry picker and motorcycle to put out the flames of the buildable abandoned house with opening door. LEGO Juniors is an age-appropriate build and play experience for ages 4-7. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10742, 'Willy\'s Butte Speed Training', 95, 'Smash the speed record with Disney•Pixar’s Lightning McQueen and Sheriff!', 'Start your engines in this high-octane Willy’s Butte Speed Training LEGO® Juniors play set, featuring a detachable speed radar trailer, roadblock with breakable barriers, spinning Radiator Springs road sign and other accessories to ramp up the Disney•Pixar Cars 3 fun. Includes a simple guide to build and play, and bigger pieces help build confidence in younger kids. LEGO Juniors is an age-appropriate build and play experience for ages 4-7. Includes Lightning McQueen and Sheriff LEGO Juniors characters.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10743, 'Smokey\'s Garage', 116, 'Fix Disney•Pixar’s Lightning McQueen for his next exciting race!', 'Give Lightning McQueen a service in Smokey’s Garage after a hard day training on the racetrack. Drive the car up the ramp, change the tires, pick the tool accessories from the cabinet and role-play endless Disney•Pixar Cars 3 scenes with this fun LEGO® Juniors set. Includes a simple guide to build and play, and bigger pieces help build confidence in younger kids. LEGO Juniors is an age-appropriate build and play experience for ages 4-7. Includes Lightning McQueen, Junior Moon and Smokey LEGO Juniors characters.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10744, 'Thunder Hollow Crazy 8 Race', 191, 'Roll up for a demolition derby at the Disney•Pixar Thunder Hollow Crazy 8 Race!', 'Throw out the racing rulebook in this action-packed LEGO® Juniors set, featuring an Easy to Build ‘Fritter Time’ road sign with breakable barriers, ramps, flaming tires and assorted demolition derby accessories to set the pulse racing of any Disney•Pixar Cars 3 fan. Includes a simple guide to build and play, and bigger pieces help build confidence in younger kids. LEGO Juniors is an age-appropriate build and play experience for ages 4-7. Includes 4 LEGO Juniors characters.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10745, 'Florida 500 Final Race', 266, 'Race with Disney•Pixar’s Lightning McQueen for the trophy!', 'Start your engines and take part in the exciting Florida 500 Final Race from Disney•Pixar Cars 3, featuring an Easy to Build crew chief’s stand with raising red and green race flags and Start/Finish line arch, trackside barriers and a winners’ podium with checkered flags and a trophy. Includes a simple guide to build and play, and bigger pieces help build confidence in younger kids. LEGO® Juniors is an age-appropriate build and play experience for ages 4-7. Includes 5 LEGO Juniors characters.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10746, 'Mia\'s Farm Suitcase', 100, 'It’s feeding time down at the animal farm!', 'Jump in the pickup and drive with Mia to the LEGO® Friends farm to feed the animals, featuring a stable with opening gate, pen, wheelbarrow, hay bales and assorted food elements and farmyard tools. Help children learn to care for and nurture the animals with this easy-to-carry suitcase play set. LEGO Juniors is an age-appropriate build and play experience for ages 4-7. Includes a Mia mini-doll figure, plus foal and lamb figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10747, 'Andrea & Stephanie\'s Beach Holiday', 143, 'Have fun at the seaside with Stephanie and Andrea!', 'Splash around at the LEGO® Friends beach with Stephanie and Andrea, featuring an Easy to Build speedboat, dock with slide, smoothie stand, loungers, shower and assorted accessories to create a perfect, fun-packed day out in the sun. LEGO Juniors is an age-appropriate build and play experience for ages 4-7. Includes two mini-doll figures and a dolphin figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10748, 'Emma\'s Pet Party', 67, 'Join Emma and her cat for a fun party in the park!', 'Celebrate Chico’s birthday with Emma with this Easy to Build park setting, featuring an archway, seesaw, balloons and a cake stand with buildable cake, plus a wheelbarrow, 2 opening gift boxes with gifts, a picture and a marker element. This popular kids toy also includes a simple guide to build and play, with bigger starter pieces to help build confidence in younger children. Includes a mini-doll figure and a cat figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10749, 'Mia\'s Organic Food Market', 115, 'Pick up some tasty organic goodies from Mia and Twister!', 'Start the day out right with goodies from Mia’s Organic Food Market, featuring an Easy to Build truck with Quick Start chassis, opening side and rotating sign, plus a spinning merry-go-round, stand-alone crates and a picnic table with seats. This colorful and fun toy also includes a simple guide to build and play, with bigger starter pieces to help build confidence in younger children. Includes a mini-doll figure and bunny figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10750, 'Road Repair Truck', 73, 'Grab your shovel and get to work!', 'Join the LEGO® City roadwork crew and take care of the streets! This fun toy for boys and girls features an Easy to Build Road Repair Truck with Quick Start chassis, minifigure cab and an open back for tools, plus a trailer with ramp and a spinning cement mixer. This fun set also includes a simple guide to build and play, with bigger starter pieces to help build confidence in younger children. Includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10751, 'Mountain Police Chase', 115, 'Chase down the crook and recover the loot!', 'Be a hero of the LEGO® City Mountain Police Force! This cool toy for kids features an Easy to Build helicopter with opening minifigure cockpit, spinning rotors and a chain with hook, as well as a police station with desk, opening safe and jail cell with opening door, and a quad bike. This action-packed set also includes a simple guide to build and play, with bigger starter pieces to help build confidence in younger children. Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10753, 'The Joker™ Batcave Attack', 151, 'Swoop in with Batman™ and take on the Joker™!', 'Suit up and join Batman™ and Robin™ as they battle The Joker™ with an Easy to Build Batwing jet, featuring shooting functions in the wings, the Joker’s wacky hotrod, plus a Batcave with docking for the Batwing, jail cell and a control center. This fun construction toy set includes a simple guide to build and play, with bigger starter pieces to help build confidence in younger children. Includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10754, 'Spider-Man vs. Scorpion Street Showdown', 125, 'Swing into action with Spider-Man and catch the Scorpion!', 'Buckle up and join Spider-Man as he chases after the Scorpion in his Easy to Build Spidey-car with movable spider legs. This Spider-Man vs. Scorpion Street Showdown set also features a Scorpion car with movable pincers and tail, plus an alley wall with opening window, ramp that connects 2 ways, big web, flexible web ‘string\' and a buildable catapult. The building toy set also includes a simple guide to build and play, with bigger starter pieces to help build confidence in younger children. Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10755, 'Zane\'s Ninja Boat Pursuit', 131, 'Race against Chopper Maroon for the treasure map!', 'Get your ninja on and help Zane recover the map! This thrilling set features Easy to Build pieces including a floating boat with turning steering wheel and a chain with hook, a motorbike, plus a temple with spinning obstacles, secret weapons and a map. This fun children\'s toy also includes a simple guide to build and play, with bigger starter pieces to help build confidence in younger children. Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10756, 'Pteranodon Escape', 84, 'Escape Jurassic Island before the Pteranadon attacks!', 'Introduce your child to the excitement of exploring in a LEGO® Juniors Jurassic World adventure with this Pteranadon Escape set, featuring an Easy to Build helicopter with a Quick Start chassis and spinning rotor, small volcano with buildable lava balls and a buildable Pteranadon with movable wings and beak. This cool toy for kids also includes a simple guide to build and play to help build confidence in children ages 4-5. Includes 2 minifigures and a Pteranadon figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10757, 'Raptor Rescue Truck', 85, 'Rescue the Raptor before the volcano erupts!', 'Introduce your child to the thrill of exploration and a LEGO® Juniors Jurassic World adventure, with this exciting Raptor Rescue Truck set, featuring a Quick Start chassis and removable cage with opening gate, plus a posable and buildable Raptor with opening mouth. This fun toy also comes with a simple guide to build and play, to help build confidence in children ages 4-5. Includes Owen and tracker minifigures, plus a Raptor figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10758, 'T. rex Breakout', 150, 'Defend the baby dinosaur and eggs from the angry T. rex!', 'Introduce your child to the thrill of a LEGO® Juniors Jurassic World adventure! This thrilling T. rex Breakout set features a posable, buildable T. rex with opening mouth, 2 Quick Start bases with gate, breakable fence and wall element, small science station and a truck with Quick Start chassis. This fun construction toy includes a simple guide to build and play, to help build confidence in children ages 4-5. Includes Claire, guard and scientist minifigures, a T. rex figure and a baby dinosaur figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10759, 'Elastigirl\'s Rooftop Pursuit', 95, 'Grab the helicopter and help Elastigirl save the city!', 'Fire up your child\'s imagination for some LEGO® Juniors The Incredibles 2 excitement, with this fast-paced Elastigirl’s Rooftop Pursuit set. This action-packed set features a helicopter with Quick Start chassis, spinning hypno-propeller and opening cockpit, a rooftop section with Quick Start baseplate, billboard, helipad and satellite dish, turbine obstacle with spinning propeller, plus Elastigirl\'s Elasticycle. This fun building toy also includes a simple guide to build and play, to help build confidence in children ages 4-5. Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10760, 'Underminer Bank Heist', 149, 'Defend Metroville’s bank vault from the Underminer!', 'Fire up your child\'s imagination for some LEGO® Juniors The Incredibles 2 excitement, with this thrilling Underminer Bank Heist set, featuring a bank vault with breakaway door, Incredibile vehicle with Quick Start chassis, Tunneler machine with Quick Start chassis and spinning drill bits, plus a street build with brick wall, wanted poster and buildable streetlamp. This fun toy for boys and girls also includes a simple guide to build and play, to help build confidence in children ages 4-5. Includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10761, 'The Great Home Escape', 178, 'Capture Brick before she knocks the house down!', 'Fire up your child\'s imagination for some LEGO® Juniors The Incredibles 2 adventures with The Great Home Escape set. This exciting set features a house facade with Quick Start wall and baseplate, moving fireplace with secret control panel, waterfall with capture function, a pool area, lounge chair with catapult function, plus a buildable car with Quick Start chassis and removable catapult. This fun children\'s toy also includes a simple guide to build and play, to help build confidence in children ages 4-5. Includes 3 minifigures and a baby figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10801, 'Baby Animals', 13, 'Look after baby animals from all around the world!', 'These cute creatures from the LEGO® DUPLO® Around the World collection are perfect for little animal lovers to develop early role-play skills. As they care for their new friends, talk to them about what different baby animals are called and where they live in the wild. This set offers great value for learning and play with a tiger cub, giraffe calf, polar bear cub and a turtle hatchling.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10804, 'Jungle', 86, 'Fly through the Jungle and make some animal friends!', 'This set offers so many ways to play and learn for little adventurers—whether it’s looking for treasure in the ruins, making their own animal stories, taking pictures with the camera, flying in the plane with turning propeller or just good old building fun! Includes 2 LEGO® DUPLO® figures: a dad and child, plus an elephant and calf, tiger, monkey and a crocodile.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10805, 'Around the World', 163, 'Go Around the World on LEGO® DUPLO® adventures!', 'This special LEGO® DUPLO® Around the World set puts a world of animals at your fingertips! Little explorers can travel from place to place by boat or plane to learn about different animals and their natural habitats. With 5 LEGO® DUPLO® figures plus 17 animals from all around the world, including a whale with opening mouth function!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10808, 'Little Plane', 13, 'Safety check the LEGO® DUPLO® Little Plane, then head for the skies!', 'Little pilots will enjoy hours of flying with this Little Plane with turning propeller. Encourage early construction skills by building the radar tower with turning radar, then show your child how to check everything is safe before the flight. LEGO® DUPLO® bricks are specially designed to be safe for little hands and the simple build means they can take off sooner! Includes a pilot DUPLO figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10809, 'Police Patrol', 15, 'Stop the crook and lock him in the police van!', 'LEGO® DUPLO® Police Patrol is a great way to develop early role-play skills with excitement and suspense. The buildable police van has turning wheels and the back can be detached to stand alone as a small jail with opening door. The bank building encourages early construction skills with a simple build so the play can start sooner. Includes 2 LEGO® DUPLO® figures: a police officer and a crook.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10812, 'Truck & Tracked Excavator', 26, 'Dig and shovel all day, then drive the rubble away!', 'Little diggers will love operating these easy-to-build construction machines. Move the Tracked Excavator over uneven land and dig with its big shovel. Take its working, flexible arm apart to make it shorter and then load up the Truck with its tipping function to drive the rubble away! LEGO® DUPLO® bricks are specially designed to be safe for little hands. Includes 2 construction worker DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10813, 'Big Construction Site', 67, 'Get busy with a bulldozer, tipper truck and posable crane!', 'Little construction workers will love these 3 buildable machines. Clear the site with the tracked bulldozer, before tipping new building supplies from the truck. Then use the crane with its claw and posable arm to hoist bricks and construct a building. LEGO® DUPLO® bricks are specially designed to be safe for little hands. Includes 3 construction worker DUPLO figures to encourage lots of role-play fun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10816, 'My First Cars and Trucks', 36, 'Learn to build and create your own fleet of LEGO® DUPLO® vehicles!', 'With LEGO® DUPLO® My First Cars and Trucks, toddlers will learn to combine the wheelbases and colorful bricks to make vehicles of all shapes and sizes. Endless options for creativity and storytelling are packed into this inspirational set and there are decorated bricks and building cards to spark new ideas. The large DUPLO bricks are specially designed to be safe and suitable for little hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10817, 'LEGO® DUPLO® Creative Chest', 70, 'Get creative with LEGO® DUPLO® throughout the year!', 'With this set, young builders can get creative with LEGO® DUPLO® throughout the year—a springtime chick, a big ice cream for summer, a colorful tree in the fall or a winter snowman. Building cards and decorated bricks are included to give inspiration for simple models and develop your child\'s imagination. The colorful LEGO® DUPLO® bricks are specially designed to be fun and safe for little hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10818, 'My First Truck', 29, 'Learn to match pairs with LEGO® DUPLO® My First Truck!', 'Help your child learn to match pairs with LEGO® DUPLO® My First Truck. The truck is easy to build using chunky DUPLO bricks, designed especially to be fun and safe for little hands, and it comes with 8 pairs of colorful food-decorated bricks—perfect for matching or memory games. There is also a market stall to open up all sorts of role play opportunities. Includes 2 child DUPLO figures plus a cat.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10820, 'LEGO® DUPLO® Creative Building Basket', 110, 'Combine the bricks to create your own buildings and stories!', 'Young children will love using these brightly colored LEGO® DUPLO® bricks to create buildings and vehicles with a city and fun park theme. With lots of accessory elements, decorated bricks, plus 2 child DUPLO figures and a dog included for inspiration, there are endless options for building and role-play in this versatile set. DUPLO bricks are specially designed to be fun and safe for little hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10822, 'Sofia the First Magical Carriage', 30, 'Join Sofia the First and ride along in her magical carriage!', 'Disney Junior\'s Sofia the First fans will love creating adventures in Sofia\'s Magical Carriage pulled by her flying horse, Minimus the Great. Have a woodland tea party with Whatnaught the squirrel near his revolving tree, then help Sofia find the magical book hidden in the secret library. Includes a LEGO® DUPLO® figure: Sofia, plus Minimus the Great and Whatnaught the squirrel.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10823, 'Batwing Adventure', 28, 'Help Batman™ use the Batwing to retrieve the stolen treasure back from The Penguin!', 'Your child will love building this fun LEGO® DUPLO® Batwing Adventure play set and helping Batman™ retrieve the stolen treasure. There’s lots of action in this set for your little super hero: start the story off by launching the Batwing´s cannon, then push The Penguin down the slide before he escapes in his duck vehicle. Includes two DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10827, 'Mickey & Friends Beach House', 48, 'Spend a day at the beach with Mickey Mouse and friends!', 'Help your child sit Donald Duck in the speedboat and pull Goofy along on the wakeboard, while Mickey Mouse uses the camera to take pictures from the deck at his Beach House. Little Disney fans will love building and rebuilding this model with a fun vacation theme and creating their own role-play stories. Includes 3 LEGO® DUPLO® figures: Mickey Mouse, Donald Duck and Goofy.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10828, 'Doc McStuffins´ Pet Vet Care', 30, 'The Doc is in…and now she\'s caring for pets too!', 'Disney Junior\'s Doc McStuffins fans will love lifting the cat onto the scales to check its weight before examining it on the table. Then they can feed Findo before opening the door of the kennel to let him settle down for the night. Show young children how to care for animals in this fun set with simple builds. Includes a LEGO® DUPLO® figure: Doc McStuffins, plus Hallie, Findo the dog and a cat.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10831, 'My First Caterpillar', 19, 'Turn this colorful caterpillar into a beautiful butterfly!', 'Young children will love learning to build and create with LEGO® DUPLO® My First Caterpillar. The colorful DUPLO bricks are specially designed to be safe for little hands, and building cards make it easy to change a caterpillar into a beautiful butterfly. Use the special decorated bricks to encourage counting an apple, 2 carrots and 3 flowers—there’s so much to learn!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10832, 'Birthday Picnic', 19, 'Play in the park and enjoy a fun birthday picnic!', 'Play out real-life scenarios in LEGO® DUPLO® My Town: a recognizable world with modern DUPLO figures. Young children will love taking balloons and a birthday picnic to the park with Grandma. Have fun with the seesaw that really rocks, build the tree and spread out the blanket—it’s the perfect place for a picnic! Includes three DUPLO figures plus a squirrel figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10833, 'Preschool', 39, 'Play and learn all day long at the LEGO® DUPLO® Preschool!', 'Play out real-life scenarios in LEGO® DUPLO® My Town: a recognizable world with modern DUPLO figures. Toddlers will love showing you their preschool day with this colorful DUPLO set, from playtime on the mat, lunch, and toileting routines to tidy-up time. Help reinforce your child’s learning and encourage early role-play skills. Includes three DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10834, 'Pizzeria', 57, 'Enjoy a delicious pizza at the LEGO® DUPLO® Pizzeria!', 'Play out real-life scenarios in LEGO® DUPLO® My Town: a recognizable world with modern DUPLO figures. Toddlers will love serving delicious pizza straight from the oven in this colorful restaurant, while learning the routines and etiquette of eating out. They can also take orders over the phone then load up the bike for delivery. Includes three DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10835, 'Family House', 69, 'Play out everyday scenes and routines in the Family House!', 'Play out real-life scenarios in LEGO® DUPLO® My Town: a recognizable world with modern DUPLO figures. There are endless play opportunities in this easy-to-build house—toddlers can have fun practicing activities and routines, from getting up in the morning, preparing and eating a meal to washing the car. Watch role-play skills develop as they play out everyday life with three DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10836, 'Town Square', 98, 'Explore the Town Square for endless fun and play opportunities!', 'Play out real-life scenarios in LEGO® DUPLO® My Town: a recognizable world with modern DUPLO figures. Discover the Town Square with your toddler—there’s so much to see and do! Turn the gearwheels to rotate the car for the mechanic, buy fresh produce at the bakery and greengrocer, or go to the doctor for a checkup! Includes five DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10837, 'Santa\'s Winter Holiday', 45, 'Build your own holiday season fun with Santa and his sleigh!', 'Bring some LEGO® DUPLO® holiday magic to your toddler, as they fly Santa around in his sleigh. Young children will love landing the sleigh to meet the 2 child DUPLO figures for some festive fun down the sledging slope. Help build the slope, the fir tree and snowman to develop early construction skills. Includes 3 DUPLO figures plus 2 animal figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10838, 'Family Pets', 15, 'Play all day with the cute LEGO® DUPLO® Family Pets!', 'Take a trip to the park to play with all the Family Pets! Young children will love to create stories with this inspiring collection of animal figures—they can throw the flying disc for the dog, groom the cat with the brush, give the bird a bath and feed carrots to the rabbit. Add these loving pets to other LEGO® DUPLO® My Town sets for endless animal fun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10839, 'Shooting Gallery', 32, 'Test your aim at the LEGO® DUPLO® Shooting Gallery!', 'Young children will love to fire the cannon at the 3 targets on the LEGO® DUPLO® Shooting Gallery stall. Encourage them to have fun trying to knock them over, and they can win a prize for one of the 2 DUPLO figures. Help them fetch a drink from the juice kiosk, and then rebuild it together and play all over again!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10840, 'Big Fair', 106, 'Enjoy a day of family fun at LEGO® DUPLO® Big Fair!', 'Play out weekend family fun with modern LEGO® DUPLO® figures in the bright and colorful Big Fair. Toddlers will love to building the Ferris wheel and turning it to watch the cars go round, rotating the carousel with gearwheel function and 4 horses to ride on, and playing with the big wavy slides again and again. They can also drive the little train and visit the ice cream kiosk, detach the giant ice cream and give it to mom or dad! Includes 5 DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10841, 'Fun Family Fair', 61, 'Turn the carousel for a day of fun at the fair!', 'Help your toddler build the iconic fairground carousel and play out a day of family fun. Young children will love using the special gearwheel function or spinning the top of the carousel to watch the 4 horses go round and round. Have fun practicing role-play and storytelling as they push the LEGO® DUPLO® figures down the slides or buy a ticket at the stand. Includes 4 DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10843, 'Mickey Racer', 15, 'Help Disney’s Mickey Mouse get his roadster ready for the next race!', 'Little Mickey Mouse fans will love to build and rebuild the race car, starting gate and Mickey-shaped gas pump. Help them develop fine motor skills as they play at filling up the car and tuning it up for the race. Then line up at the starting gate—and he\'s off! Includes a LEGO® DUPLO® figure: Disney\'s Mickey Mouse.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10844, 'Minnie Mouse Bow-tique', 70, 'Build and run the store with Disney’s Minnie Mouse and Daisy Duck!', 'Little fans of Disney’s Minnie Mouse will love to practice role-play skills by selling bows and skirts in the shop downstairs, welcoming Daisy Duck and sitting outside at the table, and taking Minnie Mouse upstairs for a good night’s rest in the bedroom. Help them rebuild the model in lots of different ways to encourage imagination and develop fine motor skills. Includes 2 LEGO® DUPLO® figures, plus a cuckoo figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10845, 'My First Carousel', 24, 'Turn the cone to make the carousel spin!', 'Introduce your child to basic cause and effect principles by using chunky LEGO® DUPLO® bricks to make a turning carousel. Watch them learn to turn the top of the carousel top and see the seats on the special gearwheels spin round below. With three child DUPLO figures and decorated bricks for matching, there are so many ways to play and learn with this exciting model.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10846, 'Flo\'s Café', 28, 'Hang out with Lightning McQueen, Mack and Cruz Ramirez!', 'Disney•Pixar Cars 3 fans will love creating friendship stories with these iconic characters in Radiator Springs. Help your young Cars fan develop fine motor skills building Lightning McQueen, Cruz Ramirez and Mack, and when they’ve all finished hanging out at Flo\'s V8 Café, your child can fuel them all up at the gas pump. They\'ll have endless fun driving Lightning McQueen up the ramp into Mack\'s trailer and heading off to his next race.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10847, 'Number Train', 23, 'Introduce counting with this easy-to-build train!', 'The LEGO® DUPLO® Number Train is a colorful introduction to numbers and counting. Your toddler will love to build and rebuild this chunky train, learning early number recognition as they go! With two child DUPLO figures and a cat figure for added role-play opportunities, this set provides endless building, driving and learning fun. DUPLO bricks are designed to be safe and suitable for little hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10848, 'My First Bricks', 80, 'Develop creativity and building skills with a selection of basic bricks!', 'Fire your toddler’s imagination with this great selection of basic LEGO® DUPLO® bricks for endless building fun! With these brightly colored bricks including some with double-sided decorations, a propeller and building cards for inspiration, they can build just about anything imaginable—a plane, a boat or a little house! DUPLO bricks are specially designed to be fun and safe for little hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10849, 'My First Plane', 10, 'Watch little builders take flight with My First Plane!', 'The LEGO® DUPLO® My First Plane will keep little pilots entertained for hours. The easy build is great for developing fine motor skills and the window brick decorated with characters helps fire the imagination for stories and role-play. Once the plane has landed, it can also be rebuilt into a boat or helicopter! DUPLO bricks are specially designed to be fun and safe for little hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10850, 'My First Cakes', 8, 'Watch little bakers serve up cute LEGO® DUPLO® cakes!', 'See how many different cakes your child can build for a birthday party or just a special treat! Toddlers will love coming up with different combinations, sparking creativity while developing fine motor skills. For café-based role-play, recipe inspiration or building practice, this set serves up all kinds of fun. LEGO® DUPLO® bricks are specially designed to be fun and safe for little hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10851, 'My First Bus', 6, 'Watch little bus drivers go places as they build and play!', 'Toddlers will love to build and rebuild this cute yellow bus for endless driving fun. This simple set helps develop fine motor and construction skills, while the window bricks decorated with characters encourage role-play. LEGO® DUPLO® bricks are specially designed to be safe for little hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10852, 'My First Bird', 7, 'Watch budding builders take flight with this colorful parrot!', 'Your toddler will love flying this cute LEGO® DUPLO® parrot all around the room! It’s easy to build, developing early construction and fine motor skills as they go. Fire their imagination and combine the bricks in different ways to make all sorts of colorful birds. DUPLO bricks are specially designed to be safe for little hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10854, 'LEGO® DUPLO® Creative Box', 120, 'Imagine and create with this big box of colorful bricks!', 'Open up a world of creativity with this huge selection of colorful LEGO® DUPLO® bricks. With fun accessories such as opening windows, your young builder can soon make their own DUPLO city or any other creation that captures their imagination. There\'s also a child DUPLO figure and a cat figure included to inspire endless role-play fun. DUPLO bricks are specially designed to be fun and safe for little hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10855, 'Cinderella´s Magical Castle', 56, 'Dance with Cinderella and the Prince in the Magical Castle!', 'Disney Cinderella fans will love recreating the ball scene with the Prince in this beautiful castle. Turn the gear wheels to make them dance, but remember to keep an eye on the clock! Develop early construction skills with this easy-to-build set with iconic accessories and decorated bricks to bring the magic to life. Includes two LEGO® DUPLO® figures: Cinderella and Prince Charming, plus a bird figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10856, 'Mater´s Shed', 23, 'Join in Mater’s video chat with Lightning McQueen!', 'Little fans of Disney•Pixar’s Cars 3 will love building and hanging out with Mater the tow truck in his shed, driving around the cones and using the wrench. Help your child develop fine motor skills and practice role-play by pretending to video call with Lighting McQueen on Mater\'s computer. The friendship between these 2 characters can spark endless fun, even when Lightning is racing miles away!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10857, 'Piston Cup Race', 31, 'Race Lightning McQueen and Jackson Storm for the Piston Cup!', 'Disney•Pixar Cars 3 fans will love lining up Lightning McQueen and Jackson Storm for the final race of the Piston Cup, and helping Luigi to start the race. First help them master early construction and fine motor skills by building the 3 cars and the starting gate. Then explore imagination and role-play with them as Luigi raises his flag. Who will win this time?
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10858, 'My First Puzzle Pets', 18, 'Learn about colors and pets with 3 fun puzzles!', 'Help your child build these colorful 3-D puzzles out of chunky LEGO® DUPLO® bricks. Preschoolers will love sorting these baby bricks into 3 different colors, and seeing what animal they can build in each color. Use the decorated bricks to start stories and develop language as they learn what different pets like to eat. DUPLO bricks are specially designed to be fun and safe for small hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10859, 'My First Ladybug', 6, 'Create, learn and play with the little ladybug!', 'Preschoolers will enjoy playing with this cute ladybug on wheels. It’s simple to build and great for developing fine motor and early construction skills. It’s also a fun toy to take along for creative play wherever you go! Turn the decorated ladybug head to make her go to sleep or wake up, and use the flower to talk about where ladybugs live. LEGO® DUPLO® bricks are specially designed to be fun and safe for small hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10860, 'My First Race Car', 6, 'Create racing role-play stories with the colorful car!', 'Little racing drivers will love to build and rebuild this My First Race Car set for endless driving fun. It’s simple for young children to build, developing fine motor and early construction skills, and it’s a fun preschool toy to take along and play with wherever you go! Turn the decorated driver brick to choose who drives the car! LEGO® DUPLO® bricks are specially designed to be fun and safe for small hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10861, 'My First Emotions', 28, 'Explore different emotions with these buildable characters.', 'Help your toddler learn to recognize and understand different emotions, using these bright, buildable characters made from chunky LEGO® DUPLO® bricks that are specially designed to be fun and safe for small hands. Turn the double-sided face bricks to explore different facial expressions, and use the double-sided story bricks to create your own tales around moods and feelings. There are hours of fun to be had together with these big bricks, developing language skills along the way.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10862, 'My First Celebration', 41, 'Throw a LEGO® DUPLO® celebration with these buildable cakes!', 'Create colorful cakes for any kind of party with LEGO® DUPLO® My First Celebration. Have fun with your preschooler as they build 3 individual cakes and a big layer cake! Toddlers will love to put the candles and decorations on top, then split the big cake into 4 pieces and share with family or friends as they learn about different occasions and how we celebrate them. DUPLO baby bricks are specially designed to be fun and safe for small hands.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10863, 'My First Animal Brick Box', 34, 'Make an animal train with these fun and colorful models.', 'Toddlers will have so much fun building their own animal train with the My First Animal Brick Box! Help them sort the bricks into different colors and talk about each iconic animal as you build them and enjoy creative play together: an elephant with a slide for a trunk, a crocodile with hinged jaws, a lion with opening mouth, a giraffe with a bendy neck and a white bird. The bright and chunky LEGO® DUPLO® bricks are specially designed to be fun and safe for small hands and come in a handy storage box.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10864, 'Large Playground Brick Box', 71, 'Develop creativity and fine motor skills with a playground theme!', 'Fire your toddler’s imagination with this exciting LEGO® DUPLO® Large Playground Brick Box, designed to make an adventure playground full of fun features. This brightly colored set of big bricks includes a spinning windmill, a working swing, 2 slides, a bouncy car ride on a spring and 2 DUPLO figures, so young children can build and rebuild a different playground every time. The packaging also doubles as a handy DUPLO storage box.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10865, 'Fun Creations', 70, 'Imagine and create with this great-value set of colorful bricks!', 'Inspire endless creativity with this big pile of brightly colored LEGO® DUPLO® bricks! Build a rainbow of models, like a whale, a penguin, a little boat or a plane. There’s so much to make in this versatile set that helps develop fine motor and construction skills. Play out stories and adventures with your child\'s creations—they will love to talk about the different colors and shapes as they play with this great preschool toy.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10867, 'Farmers\' Market', 26, 'Buy fresh fruit and vegetables from the market stall!', 'Play out real-life scenarios in LEGO® DUPLO® Town: a recognizable world with modern DUPLO figures. Toddlers will love to take a trip to the Farmers’ Market and learn about all the fresh produce on offer. When they’ve practiced the routines of buying from a market stall with the 3 DUPLO figures, they can load up the family car and drive away! This set is easy to build with large building bricks and helps develop fine motor skills.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10868, 'Farm Pony Stable', 59, 'Take care of the ponies at the Farm Pony Stable!', 'Play out real-life scenarios in LEGO® DUPLO® Town: a recognizable world with modern DUPLO figures. Preschoolers will love learning to care for the ponies at the pony stable, using the brush to groom them and then leading them to the tipping hay feeder. The stables make a great toddler toy as they are easy to build and rebuild in different ways, providing endless role-play opportunities for little pony lovers. Includes 2 DUPLO figures plus 2 pony figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10869, 'Farm Adventures', 104, 'Enjoy a visit to the adventure farm and feed the animals!', 'Play out real-life scenarios in LEGO® DUPLO® Town: a recognizable world with modern DUPLO figures. Visit the adventure farm with your toddler and help to feed all the friendly animals. Little farmers will love to pull the string to make the bell go up and down, then have some fun on the slide. Put all the animals to bed in the barn and head into the farmhouse for waffles and a sleepover! This great learning toy for toddlers includes 3 DUPLO figures plus 5 animal figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10870, 'Farm Animals', 16, 'Learn to look after the little farm animals!', 'Little animal lovers will enjoy looking after this selection of farm animals. Help them put the chicken in its coop, lead the piglet and calf to the feeding trough and water bucket, and pet the friendly cat. The chicken coop is simple for preschoolers to build and this educational toy offers great practice for early construction skills. Includes 4 animal figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10871, 'Airport', 29, 'Head off on vacation at the LEGO® DUPLO® Airport!', 'Play out real-life scenarios in LEGO® DUPLO® Town: a recognizable world with modern DUPLO figures. Help your little pilot get ready for take-off at the DUPLO Airport! It’s easy for preschoolers to build the boarding gate, luggage slide and revolving air traffic control tower in this best toy for 2 to 5-year-olds. Toddlers will love to help the pilot get all her passengers aboard the buildable plane and head for the skies! Includes 3 DUPLO figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10876, 'Spider-Man & Hulk Adventures', 38, 'Help Spider-Man and Hulk fight Sandman at Avengers HQ!', 'Little superheroes will love to create endless role-play adventures with this Marvel superhero toy, as Marvel’s Spider-Man and Hulk try to stop Sandman from stealing an important suitcase. Help young children develop fine motor skills as they build and rebuild Spider-Man\'s garage and Hulk\'s laboratory at Avengers HQ, then use the wrench to fix up the motorbike before Spider-Man speeds off to save the day! Includes 3 LEGO® DUPLO® figures: Spider-Man, Hulk and Sandman.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10877, 'Belle´s Tea Party', 19, 'Enjoy a tea party with Belle and her extraordinary friends!', 'Enter the kitchen of the enchanted castle to sing and dance with Disney’s Belle and her new friends. Disney Beauty and the Beast fans will love to role-play scenes from the movie or create new stories of their own. Develop early construction skills with this easy-to-build LEGO® DUPLO® Disney toy full of much-loved characters and decorated bricks to bring the magic to life. Includes a LEGO® DUPLO® figure: Belle, plus Mrs. Potts, Chip and Cogsworth figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10878, 'Rapunzel´s Tower', 37, 'Help Rapunzel groom Maximus and play out life in the tower.', 'Disney Tangled fans will love to build and rebuild Disney Rapunzel’s Tower in different ways, helping to develop their fine motor skills. This LEGO® DUPLO® Disney toy is perfect for role-playing daily life in the tower, from grooming the horse or painting outside to letting down Rapunzel\'s long hair from her window and tucking her into bed under the covers. Includes a LEGO® DUPLO® figure: Rapunzel, plus a Maximus the horse figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10879, 'Gentle Giants Petting Zoo', 24, 'See the baby dinosaurs at the Jurassic World Gentle Giants Petting Zoo!', 'Little dinosaur fans will love to create endless role-play adventures as they visit the LEGO® DUPLO® Jurassic World 10879 Gentle Giants Petting Zoo with this fun toddler toy. Help young children develop fine motor skills as they build and rebuild the baby dinosaur enclosure and help Gray Mitchell use his camera to snap pictures of the baby Triceratops as he stands on the swinging bridge, or the Diplodocus as he eats the vegetation. But don\'t get too close—baby dinosaurs can still bite! Includes a LEGO® DUPLO® Gray Mitchell figure plus 2 baby dinosaur figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (10880, 'T. rex Tower', 22, 'Help Owen Grady get the escaped T. rex under control in Jurassic World!', 'Enter Jurassic World with your child and recreate all the drama and tension from the movie, with this exciting set! There’s a T. rex on the loose and it’s snapping its jaws! Preschool children will love to help Owen Grady speed in with the car, face off with the huge dinosaur and make it safely into the lookout tower to call for backup. This easy-to-build dinosaur toy with large building bricks is great for creating endless role-play stories with a dinosaur theme. Includes an Owen Grady LEGO® DUPLO® figure, plus a T. rex figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (17101, 'BOOST Creative Toolbox', 847, 'Bring your LEGO® creations to life!', 'Combine the versatile LEGO® building system with advanced technology to boost your creativity with the awesome LEGO BOOST Creative Toolbox. Download the free tablet app to your device and follow the step-by-step instructions to build and code any of the 5 multifunctional models. Experience Vernie the Robot—a moving and talking robot; the M.T.R.4 (Multi-Tooled Rover 4)—a robust, versatile rover with 4 different tool attachments including a spring-loaded shooter; the Guitar4000—a musical instrument with pitch bend and sound effects; Frankie the Cat—an interactive pet that plays, purrs and expresses its mood; or the AutoBuilder—an automated production line that really builds miniature LEGO models! Bring your creations to life with the app’s intuitive, icon-based coding interface and complete an array of exciting activities designed for each model. This set also includes a playmat for use with specific activities, and a LEGO BOOST wall poster!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21019, 'The Eiffel Tower', 321, 'Build your own LEGO® interpretation of the iconic Eiffel Tower!', 'Presenting the LEGO® Architecture interpretation of one of the most iconic landmarks ever constructed – The Eiffel Tower! Designed and built by French entrepreneur, Gustave Eiffel, the original 324-meter-tall masterpiece of wrought iron engineering formed the grand entrance to the 1889 World’s Fair, held in Paris to celebrate the 100th anniversary of the French Revolution. During construction, the 18,038 wrought iron elements making up the tower’s lattice structure were bolted together at Eiffel’s factory on the outskirts of Paris, before being transported to the site, hoisted into place by steam-powered cranes operating from the elevator shafts, and assembled using no less than 2.5 million individual rivets. The resulting structure was extremely rigid and over the years has withstood storms, floods and everything else mother nature has thrown at it. Today, The Eiffel Tower is one of the world’s most popular landmarks, attracting millions of curious visitors from around the world each year. With this exceptional model, you can now build your very own 321-piece Eiffel Tower in LEGO brick form and display it in your home, office or wherever you like!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21028, 'New York City', 598, 'Celebrate New York City with this LEGO® Architecture Skyline model!', 'Celebrate the architectural diversity of New York City with this detailed LEGO® brick model. The LEGO Architecture Skyline Collection offers models suitable for display in the home and office, and has been developed for all with an interest in travel, architectural culture, history and design. Each set is scaled to give an accurate representation of the comparative size of each structure, with true-to-life color depiction. This set features the Flatiron Building, Chrysler Building™, Empire State Building, One World Trade Center and the Statue of Liberty, and is finished with a decorative “New York City” nameplate.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21029, 'Buckingham Palace', 780, 'Recreate Buckingham Palace with LEGO® Architecture!', 'Build a LEGO® brick model of London\'s official royal residence. This magnificent model focuses on the palace\'s east wing with its famous balcony, forecourt and palace gates. A section of the Mall is also depicted, complete with a double-decker bus, black taxicab and the Victoria Memorial. The model has been designed to deliver an interesting and rewarding building experience and is suitable for display in the home and office. It has been developed for all with an interest in architecture, travel, history and design.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21030, 'United States Capitol Building', 1032, 'Explore the architecture of the United States Capitol Building!', 'Discover the architectural secrets of the iconic United States Capitol Building with this amazing LEGO® Architecture interpretation that focusses on the structure\'s neoclassical style facade, steps and lawns, finished with a decorative “U.S. Capitol” nameplate. Remove the dome to access the rotunda interior depicting the National Statuary Hall, with columns, 8 statues and tiled floor. This model has been designed to deliver an interesting and rewarding building experience and is suitable for display in the home and office. It has been developed for all with an interest in travel, architectural culture, history and design. The scale of this model matches the LEGO Architecture 21022 Lincoln Memorial.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21032, 'Sydney', 361, 'Celebrate Sydney with this LEGO® Architecture Skyline model!', 'Capture the architectural essence and splendor of Sydney with this magnificent set that brings together the iconic Sydney Opera House™, Sydney Harbour Bridge, Sydney Tower and Deutsche Bank Place, in an inspirational skyline setting. Each individual LEGO® structure provides a unique and rewarding building experience with true-to-life color and relative scale depiction. Sydney\'s sparkling harbor is represented in the tiled baseplate, adding an extra dimension and feel of authenticity to this detailed recreation of one of the world\'s most glamorous cities.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21033, 'Chicago', 444, 'Celebrate Chicago with this LEGO® Architecture Skyline model!', 'Recreate Chicago’s blend of historical and modern architecture with this realistic LEGO® brick model. The LEGO Architecture Skyline Collection offers models suitable for display in the home and office, and has been developed for all with an interest in travel, architectural culture, history and design. Each set is scaled to give an accurate representation of the comparative size of each structure, with true-to-life color depiction. This set features the Willis Tower™, John Hancock Center, Cloud Gate, DuSable Bridge, Wrigley Building and the Big Red, and is finished with a decorative “Chicago” nameplate.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21034, 'London', 468, 'Celebrate London with this LEGO® Architecture Skyline model!', 'Celebrate the architectural diversity of London with this detailed LEGO® brick model. The LEGO Architecture Skyline Collection offers models suitable for display in the home and office, and has been developed for all with an interest in travel, architectural culture, history and design. Each set is scaled to give an accurate representation of the comparative size of each structure, with true-to-life color depiction. This set features the National Gallery, Nelson’s Column, London Eye, Big Ben (the Elizabeth Tower) and Tower Bridge, and is finished with a decorative “London” nameplate.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21035, 'Solomon R. Guggenheim Museum®', 744, 'Recreate the Solomon R. Guggenheim Museum® with LEGO® Architecture!', 'Discover the architectural secrets of Frank Lloyd Wright’s Solomon R. Guggenheim Museum®. This accurately detailed LEGO® model faithfully recreates the curves and distinctive lines that have made this building an architectural icon for the last half-century. The simple, grid-patterned facade of the annex tower complements the main building with its circular rotundas, while buildable exterior elements depict a section of New York City’s 5th Avenue Museum Mile, complete with its signature yellow cabs. The Guggenheim sign, featuring Wright’s architectural lettering, has also been recreated in a similar typeface to heighten the authenticity of the model. This LEGO Architecture model has been designed to deliver a rewarding building experience for all with an interest in architecture, travel, history and design, and is suitable for display in the home and office.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21036, 'Arc de Triomphe', 386, 'Experience the grandeur of the Arc de Triomphe!', 'Capture the architectural elegance of one of the world’s best-known monuments with this impressive LEGO® Architecture interpretation of the Arc de Triomphe. This detailed model faithfully reproduces Paris’ iconic masterpiece, with statue-adorned pillars, sculptural reliefs and subtle coloring that adds warmth while emphasizing the model’s bold lines, curves and contours. It also includes a golden plate to represent the Tomb of the Unknown Soldier, a LEGO interpretation of the eternal flame and a decorative “Arc de Triomphe” nameplate. This LEGO brick model has been designed to deliver a pleasantly challenging and rewarding building experience for all with an interest in architecture, travel, history and design, and makes a perfect display piece for the home or office.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21039, 'Shanghai', 597, 'Celebrate Shanghai with this LEGO® Architecture Skyline set!', 'Recreate Shanghai in China\'s blend of historical and modern architecture with this realistic 21039 LEGO® Architecture Skyline Collection model. This LEGO brick collectible toy features the city\'s iconic points of interest, including Chenghuang Miao Temple, Longhua Temple and Pagoda, Radisson Blu Hotel, Bund area, Oriental Pearl, World Financial Center, the Shanghai Tower and Huangpu River, and is finished with a decorative Shanghai nameplate. The LEGO Architecture Skyline Collection offers models suitable for display in the home and office, and has been developed for all with an interest in travel, architectural culture, history and design. Each set is scaled to give an accurate representation of the comparative size of each structure, with realistic color depiction.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21119, 'The Dungeon', 219, 'Enter the zombie-spawning dungeon at your peril!', 'Venture into The Dungeon on a perilous quest for valuable ores! Craft torches from your resources to light your way and disable the mob spawner. Wield your iron pickaxe to defeat the roaming zombies, then mine the gold ore and grab the chest containing wheat and redstone. But watch out… zombies can spawn anywhere! Rebuild the set for more LEGO® Minecraft™ creations! Includes 3 minifigures with assorted accessories: Steve and 2 zombies.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21121, 'The Desert Outpost', 519, 'Prepare for battle at The Desert Outpost!', 'Hostile mobs are spawning like never before, and the desert is becoming a very scary place to be… it’s time to build The Desert Outpost! Help Alex construct the house and lookout tower, build a protective wall and ring the fortress with burning torches. Have the tame wolf stand guard while you craft a bed, table, door, ladder and a boat, then sail out in search of crops to farm within the outpost walls. As darkness falls, silhouettes of approaching skeletons appear on the desert horizon. Grab your weapons, load up the TNT launcher, and prepare for battle! Rebuild the set for more LEGO® Minecraft™ creations! Includes 2 minifigures with assorted weapons and accessories: Steve and Alex, plus a wolf and 2 skeletons.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21122, 'The Nether Fortress', 571, 'Battle the hostile mobs at The Nether Fortress!', 'You’re running low on supplies that the Overworld just can’t offer… light the obsidian portal and step through to reach The Nether Fortress! This forbidding structure is protected by an array of hostile mobs. Help Alex defeat the Blaze that guards the fortress. Take your diamond pickaxe and mine glowstone to light your way, but be careful not to trigger a lava flow! Build an access point to breach the fortress wall, grab your diamond sword and spring a surprise attack on the Zombie Pigman. Take on the red-eyed, fireball-shooting Ghast to obtain the chest containing 2 diamonds and a golden sword, collect mushrooms and Nether wart, and mine Nether quartz ore. It’s all in a day’s work for a LEGO® Minecraft™ hero! Rebuild the set for more LEGO Minecraft creations! Includes 3 minifigures with assorted weapons and accessories: Steve, Alex and a Zombie Pigman, plus a Blaze and a Ghast.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21123, 'The Iron Golem', 208, 'Spring a surprise attack with The Iron Golem!', 'Smelt iron ingots in the furnace, craft iron blocks on the crafting table, then create an iron golem and spring a surprise on the roaming zombie. Enjoy hands-on Minecraft™ adventures, featuring your favorite characters and objects with this LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Includes 2 minifigures: Alex and a zombie, plus an iron golem and a baby pig.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21124, 'The End Portal', 559, 'Venture into the stronghold and activate the End portal!', 'Battle the cave spider and the endermen, retrieve valuable ores from the chest and collect the eyes of ender to activate the End portal! Enjoy hands-on Minecraft™ adventures featuring your favorite characters and objects with this LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Includes a Steve minifigure, plus 2 endermen and a cave spider.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21125, 'The Jungle Tree House', 706, 'Build and defend The Jungle Tree House!', 'Join forces with Alex to defeat the invading mobs. Activate the secret trapdoor to surprise the roaming skeleton, lure the exploding Creeper™ onto the floor trap and make a quick exit down the waterfall. Enjoy hands-on Minecraft™ adventures featuring your favorite characters and objects with this LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Includes 2 minifigures: Steve and Alex, plus a Creeper™, skeleton, ocelot and a sheep.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21126, 'The Wither', 318, 'Prepare to battle the wither!', 'Build the TNT cannon and wage battle against the fearsome wither and wither skeletons that protect the nether fortress! Enjoy hands-on Minecraft™ adventures featuring your favorite characters and objects with this LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Includes a Steve minifigure, plus a wither and 2 wither skeletons.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21129, 'The Mushroom Island', 247, 'Discover The Mushroom Island!', 'Sail out on a new Minecraft™ adventure to discover The Mushroom Island, mine vital supplies, grow crops and nurture the mooshroom and her baby. Enjoy hands-on Minecraft adventures featuring your favorite characters and objects with this easy-to-reconfigure, modular LEGO® Minecraft set, complete with explosion function—designed for young fans of the highly successful sandbox video game. Includes an Alex minifigure and a Creeper™.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21130, 'The Nether Railway', 387, 'Ride The Nether Railway!', 'Build an awesome rail system and journey through the Nether. Avoid the soul sand, hopping magma cubes and the zombie pigman as you search for precious nether quartz ore. Enjoy hands-on Minecraft™ adventures featuring your favorite characters and objects with this easy-to-reconfigure, modular LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Includes a Steve minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21134, 'The Waterfall Base', 729, 'Build and defend the awesome Waterfall Base!', 'Use your Minecraft™ creativity and know-how to build the ultimate shelter, packed with exterior and interior details and features. Rear livestock, grow crops and do a spot of fishing, but remember to look out for the hostile mobs! Enjoy hands-on Minecraft adventures featuring your favorite characters and objects with this easy-to-reconfigure, modular LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Includes Steve and Alex minifigures, plus a buildable enderman, zombie, cat and dyed sheep.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21135, 'The Crafting Box 2.0', 717, 'Expand your LEGO® Minecraft™ universe!', 'Create your own customized Minecraft landscapes in endless combinations with The Crafting Box 2.0. Build, rebuild, combine and enjoy hands-on Minecraft adventures featuring your favorite characters and objects. This easy-to-reconfigure, modular LEGO® Minecraft set, designed for young fans of the highly successful sandbox video game, includes 5 brick bags, each containing one set of bricks with 3 alternative model configurations. Also includes a Steve minifigure plus horse, cow, slime and Creeper™ figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21136, 'The Ocean Monument', 1122, 'Unlock the treasures of the Ocean Monument!', 'Head for the depths of the Minecraft™ sea to discover the Ocean Monument. Battle the elder guardian with spring-loaded shooter, activate the dry sponge function to enter the monument and locate the lever to open the treasure chamber full of golden blocks. Enjoy hands-on Minecraft adventures featuring your favorite characters and objects with this easy-to-reconfigure LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Includes Steve and Alex minifigures, plus squid, guardian and elder guardian figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21137, 'The Mountain Cave', 2863, 'Experience the Mountain Cave!', 'Build and experience the Mountain Cave, featuring an amazing minecart track with an integrated redstone‑powered minecart elevator, and an array of other features and functions, including TNT blasting, rotating spider‑spawner, charged Creeper™ explosion and a lava burst. Position the light brick to illuminate the rotating spider-spawner, wall of redstone, jack o’lantern, first-night shelter, furnace, lava or the torch above the cave entrance. Enjoy hands‑on Minecraft™ adventures featuring your favorite characters and objects with this easy-to-reconfigure, modular LEGO® Minecraft set designed for young fans of the highly successful sandbox video game. Includes Steve and Alex minifigures, plus 13 mobs including a charged Creeper™.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21138, 'The Melon Farm', 69, 'Grow and trade your crops at the Melon Farm!', 'Harvest your crops and make a Carrot on a Stick to guide the saddled pig to the Melon Farm, trade your melon slice with the villager and activate the exploding Creeper™ function. Enjoy hands-on Minecraft™ adventures with this LEGO® Minecraft set—designed for fans of the highly successful sandbox video game. Combine this set with other LEGO Minecraft models to create your own unique LEGO Minecraft universe. Also includes a Steve LEGO Minecraft minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21139, 'The Nether Fight', 84, 'Battle the hostile mobs in the Nether Fight!', 'Head for the fiery Nether, activate the exploding TNT function and use your enchanted axe to defeat the zombie pigman and wither skeleton. Enjoy hands-on Minecraft™ adventures with this LEGO® Minecraft set—designed for fans of the highly successful sandbox video game. Combine this set with other LEGO Minecraft models to create your own unique LEGO Minecraft universe. Also includes an Alex LEGO Minecraft minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21140, 'The Chicken Coop', 198, 'Enjoy Minecraft™ farming adventures with the Chicken Coop!', 'Have fun tending to the chickens at the Chicken Coop, featuring an elevated henhouse that delivers eggs directly into a chest. Enjoy hands-on Minecraft™ adventures with this LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Combine this set with other LEGO Minecraft models to create your own unique LEGO Minecraft universe. Includes an Alex LEGO Minecraft minifigure, plus baby chicken and tamed wolf figures, and 2 chicken figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21141, 'The Zombie Cave', 241, 'Enter the Zombie Cave at your peril!', 'Activate the TNT function to blast your way into the bat-infested Zombie Cave. Battle a zombie and a baby zombie, and mine for coal, redstone, gold and diamond ores. Enjoy hands-on Minecraft™ adventures with this LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Combine this set with other LEGO Minecraft models to create your own unique LEGO Minecraft universe. Also includes a Steve LEGO Minecraft minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21142, 'The Polar Igloo', 278, 'Set up base at the Polar Igloo!', 'Discover an igloo in a snow-covered biome, complete with a polar bear and a baby polar bear. Do a spot of fishing and build an arrow dispenser to defend against the stray. Enjoy hands-on Minecraft™ adventures with this LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Combine this set with other LEGO Minecraft models to create your own unique LEGO Minecraft universe. Also includes an Alex LEGO Minecraft minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21143, 'The Nether Portal', 470, 'Board the minecart and journey through the Nether Portal!', 'Craft a portal, build an awesome rail system and journey into the Nether. Battle the flying blaze and the fireball shooting ghast, activate the lava fall, and mine light-emitting glowstone. Enjoy hands-on Minecraft™ adventures with this LEGO® Minecraft set—designed for young fans of the highly successful sandbox video game. Also includes a Steve LEGO Minecraft minifigure, plus small magma cube and baby zombie pigman figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21144, 'The Farm Cottage', 549, 'Create a flourishing Farm Cottage!', 'Use your LEGO® Minecraft™ creativity to build this exciting 2-level waterside Farm Cottage, featuring a detailed interior and a host of exterior features. Harvest wheat, carrots and beetroot, care for the baby pig and donkey, and protect your crops from the rabbits—and yourself from the skeleton! Enjoy hands-on Minecraft adventures with this easy-to-reconfigure, modular LEGO® Minecraft set; designed for young fans of the highly successful sandbox video game. Also includes Steve and Alex LEGO Minecraft minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21307, 'Caterham Seven 620R', 773, 'Add quirky vehicle style to your shelf or desk!', 'Build a display model of the stylish Caterham Seven 620R in LEGO® bricks. Packed with authentic details, it features a removable nose cone, engine and engine cover, and an opening boot containing axle stands. An ideal gift for LEGO fans and car enthusiasts with a love of classic sports cars.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21308, 'Adventure Time™', 496, 'What time is it? It’s LEGO® Adventure Time™!', 'Display and role-play with this LEGO® Adventure Time™ set, featuring eight buildable Adventure Time characters with an assortment of play-starting accessory elements. An ideal gift for fans of the popular Cartoon Network animated TV series.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21309, 'LEGO® NASA Apollo Saturn V', 1969, 'Build the first rocket to land people on the Moon!', 'Display and role-play with this majestic meter-high LEGO® brick model of the NASA Apollo Saturn V. Packed with authentic details, it features 3 removable rocket stages, including the S-IVB third stage with the lunar lander and lunar orbiter. The set also includes 3 stands to display the model horizontally, 3 new-for-June-2017 astronaut microfigures for role-play recreations of the Moon landings, plus a booklet about the manned Apollo missions and the fan designers of this educational and inspirational LEGO Ideas set.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21310, 'Old Fishing Store', 2049, 'Prepare for the ultimate fishing trip!', 'Visit the beachside Old Fishing Store, featuring a shop packed with fishing-themed elements, and a connected watchtower with a 360-degree viewing balcony and office on the lower level. Ideal for display and role-play, this model has 2 removable roofs, an opening back wall in the shop for easy access, 4 minifigures, cat and 3 seagull figures, as well as loads of other cool details and elements to fire up the imagination.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21312, 'Women of NASA', 231, 'Build, play and learn from inspiring women of NASA!', 'Explore the professions of some of the groundbreaking women in science, technology, engineering and mathematics (STEM) with the LEGO® Ideas Women of NASA set. It features minifigures of 4 pioneering women of NASA— astronomer and educator Nancy Grace Roman, computer scientist and entrepreneur Margaret Hamilton, astronaut, physicist and entrepreneur Sally Ride and astronaut, physician and engineer Mae Jemison—and 3 builds illustrating their areas of expertise. Role-play space exploration from planning to moon landing, beginning with the iconic scene from Massachusetts Institute of Technology in 1969 of Hamilton with software that she and her team programmed. Build the posable Hubble Space Telescope and launch a LEGO version of the Space Shuttle Challenger with 3 removable rocket stages. The set also includes a booklet about the 4 featured women of NASA, and the fan creator and LEGO designers of this fun and educational set.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21313, 'Ship in a Bottle', 962, 'Designed by fan creator, Jake Sadovich, Idaho, USA.', 'Continue a nautical tradition when you build the LEGO® Ideas Ship in a Bottle, featuring a highly detailed ship with the captain’s quarters, cannons, masts, crow’s nest and printed sail elements. Fan creator, Jake Sadovich, was inspired by an actual ship in a bottle that he had built a few years earlier when he decided to build a replica in LEGO brick form. His creation reached the qualifying 10,000 votes with LEGO Ideas.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (21314, 'TRON: Legacy', 230, 'Reimagine Disney’s TRON: Legacy movie scenes with LEGO® bricks!', 'Build, play and display with this futuristic LEGO® Ideas 21314 TRON: Legacy set from Disney, featuring 2 Light Cycles, each with minifigure seats and translucent-colored light-style elements, plus a divisible TRON grid with attachment points for the vehicles. Use the grid as a display base for the Light Cycles or split it in 2 to recreate the chase scene from Disney\'s TRON: Legacy movie. Alternatively, stage an Identity Disc battle between the 3 included LEGO minifigures—Sam Flynn, Quorra and Rinzler—on the grid. This construction toy includes a booklet with information about its fan creator and LEGO designers, plus the lowdown on Disney’s TRON: Legacy movie and its main characters.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31029, 'Cargo Heli', 132, 'Airlift vital supplies with the awesome 3-in-1 Cargo Heli!', 'Airlift heavy loads with the high-powered 3-in-1 Cargo Heli! Taxi to the helipad and prepare for takeoff. When you’re airborne, hover into position, lower the winch hook and carefully lift the cargo container. Features a smart red and yellow color scheme, working main rotor and tail rotor, 2 detailed engines, navigation lights, wheeled undercarriage, winch hook and a cargo container with opening doors. Now let’s get this cargo delivered! Rebuilds into a cool cargo ship or an awesome cargo plane.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31035, 'Beach Hut', 286, 'Enjoy summer adventures with the 3-in-1 Beach Hut!', 'Everybody go surfing! There’s lots to do at the sunny, 3-in-1 LEGO® Creator Beach Hut. Collect starfish, swim from the cozy jetty, take to the waves for a spot of surfing or try your hand at paddleboarding! Fold out the Beach House and you have a beachfront surf shop where you can hire surfboards, give surfing lessons and serve sun-loving customers with cold, refreshing beverages. This awesome 3-in-1 set is full of imaginative details and rebuilds into a cool summer shack with outdoor swimming pool, or a cozy summer cottage by the sea—all this from just one set of bricks! Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31043, 'Chopper Transporter', 124, NULL, 'Haul the helicopter to the airfield with the Chopper Transporter, featuring a flatbed truck with orange warning beacons and deep-tread tires, and a helicopter with a tinted cockpit and spinning rotors. This 3-in-1 LEGO® Creator model can be rebuilt into a tractor or an off-roader, or combined with other small-scale LEGO Creator vehicles for endless play scenarios.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31046, 'Fast Car', 222, 'Get ready for the ultra-cool 3-in-1 Fast Car!', 'Experience the joys of motoring with the awesome Fast Car, featuring a yellow, white and black color scheme, large spoiler, alloy-look rims with low-profile tires, opening hood with detailed engine, opening scissor doors, fold-down roof and a large driver\'s cab with space for 2 minifigures (not included). This 3-in-1 LEGO® Creator model can be rebuilt to create a pickup truck or a skid loader for a treble build-and-play experience.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31047, 'Propeller Plane', 230, 'Take a flight in the cool 3-in-1 Propeller Plane!', 'Enjoy the nostalgic charm of this classic Propeller Plane, featuring a red, white and black color scheme, spinning propellers, retractable wheels and an opening cockpit with room for a minifigure (not included). This 3-in-1 LEGO® Creator model can be rebuilt to create a hydroplane or a helicopter for a treble build-and-play experience. Both alternative models can accommodate a minifigure (not included).
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31049, 'Twin Spin Helicopter', 326, 'Conquer ice and snow with the 3-in-1 Twin Spin Helicopter!', 'Winch up the snowcat and head for colder climates with the awesome 3-in-1 Twin Spin Helicopter, featuring a light-blue and white color scheme, working winch, landing skis and elevated rear landing gear, plus a tracked snowcat vehicle that fits beneath the helicopter. Turn the dial at the rear of the helicopter to rotate the Twin Spin rotors. This model can be rebuilt to create a snowmobile with functioning winch or a single-engine airplane with spinning propeller.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31051, 'Lighthouse Point', 528, 'Meet the wildlife at the brightly lit Lighthouse Point!', 'Have fun with this charming model, featuring a lighthouse and a lightkeeper\'s cottage with detailed interior, including a table, chair, lamp and a painting. The lighthouse includes a LEGO® light brick, and the seashore features lapping waves, a bench, open-air fire, rocks and a pier. This 3-in-1 LEGO Creator set features an easy-to-remodel modular system for extended play scenarios and can be rebuilt to create a house with pier and speedboat or a boathouse. Includes 2 minifigures, plus an orca and 2 seagulls.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31052, 'Vacation Getaways', 792, 'Head for sunnier climes with the Vacation Getaways set!', 'Explore exciting destinations with this awesome camper, complete with trailer, motorboat and an array of brick-built features and accessories. Remove the roof, windshield or rear section to access its detailed interior, complete with toilet, fold up bed, kitchen, sofa and a TV. The set also includes a foldaway barbecue, table and chairs, which can be transported on the camper\'s roof. This versatile 3-in-1 LEGO® Creator model can be rebuilt to create a summer home or a yacht. Includes 2 minifigures, plus a buildable bear.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31056, 'Green Cruiser', 122, 'Take an open-top drive in the cool 3-in-1 Green Cruiser!', 'Drive in style with this sleek open-top Green Cruiser, featuring a green, white and black color scheme, tinted windshield, opening front trunk and rear hood, detailed engine, and a large two-minifigure cockpit with detailed dashboard and steering wheel. The 3-in-1 LEGO® Creator model has a three-part modular design for quick model reconfiguration, and rebuilds into a Fast Boat or a Truck.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31057, 'Air Blazer', 102, 'Perform cool maneuvers with the 3-in-1 Air Blazer!', 'Complete secret missions with the agile, high-speed Air Blazer helicopter, featuring spinning main rotor and tail rotor, tinted cockpit, large engines, rear landing light and a red and black color scheme. This 3-in-1 LEGO® Creator model rebuilds into a Seaplane or a Catamaran.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31058, 'Mighty Dinosaurs', 174, 'Enjoy roaring adventures with the 3-in-1 Mighty Dinosaurs!', 'Have fun with the awesome T. rex, featuring a dark-green and beige color scheme, bright orange eyes, posable joints and head, large claws and an opening mouth with pointed teeth. Also includes the dinosaur’s prey in the form of a buildable rib cage. Rebuild this 3-in-1 LEGO® Creator Mighty Dinosaurs model to create a Triceratops or a Pterodactyl.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31059, 'Sunset Street Bike', 194, 'Take the 3-in-1 Sunset Street Bike for high-speed spin!', 'Build your own superbike with this awesome Sunset Street Bike, featuring a detailed engine and exhaust, wide rubber tires, high-rise fenders, windshield, working spring suspension and handlebar steering, and an orange, black and white color scheme. Rebuild this 3-in-1 LEGO® Creator model into a Road Bike or a Dragster.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31060, 'Airshow Aces', 246, 'Take the 3-in-1 Airshow Aces to town!', 'Enjoy a great day at the airshow with this amazing set, featuring a jet, propeller plane with foldup wings and a transport truck with detachable trailer, plus two buildable flags and a buildable windsock. This 3-in-1 LEGO® Creator set features a three-part modular design that enables quick model reconfiguration, and can be combined with the 31054 and 31055 LEGO Creator mini modular vehicle sets to create new vehicles for extended play. Rebuild to create a Construction Truck or two Race Cars.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31062, 'Robo Explorer', 205, 'Have fun with the cute 3-in-1 Robo Explorer!', 'Impress your friends with this awesome model! This characterful Robo Explorer features an azure, black and gray color scheme, bright-green eyes, working tracks, rotating body and head, and posable arms with working claw and searchlight. Rebuild this 3-in-1 LEGO® Creator model into a Robot Dog with a light-up jetpack or a Robot Bird with light-up eyes!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31063, 'Beachside Vacation', 275, 'Enjoy the beach life with the 3-in-1 Beachside Vacation!', 'Enjoy summer adventures with this sunny beach house, featuring a blue-striped color scheme, two large windows with green-and-white awnings and yellow door, plus a detailed interior with an armchair, fish tank and a ceiling fan, and exterior details including a hammock, palm tree and a beach and ocean area. Also includes a buildable water scooter. Rebuild this 3-in-1 LEGO® Creator model into a Beachside Shop or a Boatside Harbor. Includes two minifigures, plus a buildable sea turtle and seagull.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31064, 'Island Adventures', 359, 'Fly to warmer climes for 3-in-1 Island Adventures!', 'Head for exciting destinations aboard the huge seaplane, featuring a bright-yellow, white and dark-blue color scheme, twin engines with spinning propellers, twin booms, adjustable elevator, landing floats, and an opening cargo hatch and cockpit with detailed dashboard. Also includes a tropical island with two palm trees, plus an empty bottle and a map. Rebuild this 3-in-1 LEGO® Creator model into an Island Hut or a Speedboat. Includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31066, 'Space Shuttle Explorer', 285, 'Launch a satellite with the 3-in-1 Space Shuttle Explorer!', 'Carry out daring space missions with the Space Shuttle Explorer, featuring an authentic white, black and gray color scheme, large engines, opening payload bay with robotic arm, satellite with foldout wings and a minifigure cockpit with tinted canopy. This 3-in-1 LEGO® Creator model rebuilds into a Moon Station or a Space Rover for further outer‑space adventures. Also includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31067, 'Modular Poolside Holiday', 356, 'Play all day on a 3-in-1 Poolside Holiday!', 'Enjoy a wealth of summer activities with the Poolside Holiday set, featuring a house with a red and tan color scheme, rooftop terrace with flowers and barbecue, and a garden area with trees, greenery, swimming pool and a table tennis table with rackets. Interior details include a guitar amplifier, flat-screen TV and a sofa. Mix and match the buildable modules to create a rooftop pool or a rooftop garden, and easily swap the window, door and other modular sections to customize the house with the new-for-June-2017 LEGO® Creator modular system. Combine this set with the 31068 and 31069 modular-system sets to create a dream house with endless build and play opportunities! This 3‑in‑1 LEGO Creator model can also be rebuilt to create a Skate Park Holiday or a Music Garage Holiday. Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31068, 'Modular Modern Home', 386, 'Enjoy eco-friendly adventures with the 3-in-1 Modern Home!', 'Build the bright and airy Modern Home, featuring a white, brown and pale-blue color scheme, large windows, solar skylight, upper-level bedroom and balcony with parasol, and a ground-level room with sofa and armchair. Mix and match the buildable modules to create a rooftop terrace, and easily swap the window, door and other modular sections to customize the house with the new-for-June-2017 LEGO® Creator modular system. Combine this set with the 31067 and 31069 modular-system sets to create a dream house with endless build and play opportunities! This 3‑in‑1 LEGO Creator model can also be rebuilt to create a Lakeside Home or a Garden Home. Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31069, 'Modular Family Villa', 728, 'Build and enjoy the delightful 3-in-1 Family Villa!', 'Enjoy urban adventures at the 3-level Family Villa, featuring a red-tiled roof, white facade with lots of windows and colorful details, plus a garden area with a basketball hoop, outdoor fireplace, mailbox, doghouse and a stairway that leads to a mid-level terrace with a sun lounger. Interior details include a bedroom and kitchen, tables and a sofa. Mix and match the buildable modules and easily swap the window, door and other modular sections to customize the house with the new-for-June-2017 LEGO® Creator modular system. Combine this set with the 31067 and 31068 modular-system sets to create a dream house with endless build and play opportunities! This 3‑in‑1 LEGO Creator model can also be rebuilt to create a Golf Hotel or a Summer Villa with a swimming pool. Includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31070, 'Turbo Track Racer', 670, 'Get behind the wheel of the awesome 3-in-1 Turbo Track Racer!', 'Climb into the cockpit of the powerful Turbo Track Racer, featuring a light-blue color scheme with a broad white racing stripe, white rear spoiler, black and white rims with low profile tires, automatic upswing doors and a detailed cockpit with roll cage, racing steering wheel, speedometer, moving gearshift, emergency brake lever, and flame-yellow and gray adjustable racing seats. Also features an opening rear hatch and hood, detailed engine with chrome colored grilles and moving parts, tinted windshield and detailed headlights, taillights, exhaust pipes and wing mirrors. This 3-in-1 LEGO® Creator model rebuilds into a Forklift Truck or a Cool Blue Racer.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31071, 'Drone Explorer', 109, 'Be an eye in the sky with the 3-in-1 Drone Explorer!', 'Carry out secret missions and explorations with the Drone Explorer, featuring an orange, white and black color scheme, and lots of realistic details, including twin rotors and posable cameras, plus a large opening cockpit and landing gear that doubles as a lifting claw. This 3-in-1 LEGO® Creator building toy rebuilds into a Swamp Boat or a Propeller Plane for even more action and adventure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31072, 'Extreme Engines', 109, 'Enter the racing world with the 3-in-1 Extreme Engines set!', 'Enjoy racing adventures with the LEGO® Creator Extreme Engines set, featuring a Race Car with a sporty blue, white, yellow and black color scheme and authentic detailing, including a large rear engine, side air intakes and wide rims with low profile tires. This 3-in-1 construction toy also features adjustable wing mirrors and rear spoiler and rebuilds into a Hot Rod or a Speedboat for further racing action and adventure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31073, 'Mythical Creatures', 223, 'Create a world of scary 3-in-1 Mythical Creatures!', 'Enjoy monstrous adventures with the 3-in-1 Mythical Creatures set. Create a fire-breathing Dragon with a dark-red and yellow color scheme, large fangs, green eyes and pointed claws. This 3-in-1 children\'s toy also features posable legs, head, tail and wings, and rebuilds to create a Giant Spider or an axe-bearing Troll for more scary LEGO® fun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31074, 'Rocket Rally Car', 241, 'Blast off from the start line in the 3-in-1 Rocket Rally Car!', 'Be the first to the finish line with the cool 3-in-1 Rocket Rally Car, featuring a fresh green, black and blue color scheme, large tinted windshield, and blue alloy rims with low profile tires. Open the doors to access the detailed cockpit, lift the rear hood to access the roof-mountable rocket engine, and press the button to raise the hood scoop. This 3-in-1 LEGO® Creator popular kids toy rebuilds into a Jet Truck or a Quad Bike for even more action and adventure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31075, 'Outback Adventures', 225, 'Head into the wilds with the 3-in-1 Outback Adventures set!', 'Set off on Outback Adventures with this awesome 3-in-1 set, featuring a classic Off-roader vehicle with roof spots, hood-mounted spare wheel, bull bar, minifigure cab with roll cage, and wide rims with chunky tires, plus a working winch and a buildable tree trunk and greenery. This LEGO® Creator toy for boys and girls rebuilds to create a Wilderness Campsite or a Winch Helicopter for even more excitement, and includes an explorer minifigure ready for adventure with his faithful buildable dog.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31076, 'Daredevil Stunt Plane', 200, 'Thrill the crowds with the 3-in-1 Daredevil Stunt Plane set!', 'Perform amazing stunts with the Daredevil Stunt Plane set, featuring a classic biplane with a bright red, white and blue color scheme with star-printed elements and golden accents, minifigure cockpit, spinning propeller and a wheeled undercarriage. This 3-in-1 LEGO® Creator building toy rebuilds into a Rocket Car or a Rocket Boat for more exciting stunts and adventures, and includes a stuntman minifigure, ready to perform in his colorful stuntman suit, helmet and goggles.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31079, 'Sunshine Surfer Van', 379, 'Enjoy seaside fun with the 3-in-1 Sunshine Surfer Van set!', 'Head out on summer adventures with the Sunshine Surfer Van set, featuring a camper with a bright yellow, white and blue color scheme, and a host of realistic details including a roof rack for storing the included surfboard, foldaway sun lounger and chair, parasol, table and barbecue. Remove the roof and side section for access to the detailed interior, complete with fold-down bed, TV and kitchenette. This 3-in-1 LEGO® Creator construction toy rebuilds into a Lifeguard Tower or a Beach Buggy for even more seaside fun, and includes 2 minifigures, both ready for summer adventures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31080, 'Modular Winter Vacation', 374, 'Hit the slopes with the 3-in-1 Modular Winter Vacation set!', 'Enjoy active adventures with the Modular Winter Vacation set, featuring a cozy ski cabin with a rooftop ski slope, slalom flags, balcony with open fire, outdoor picnic bench and a shop with a detailed interior, cash register and a serving hatch from where customers can purchase ski equipment and drinks. You can mix and combine the buildable modules and easily swap the window, door and other modular sections to customize the ski cabin with the LEGO® Creator modular system. This 3-in-1 construction toy also rebuilds into a Bobsleigh Track with bobsleigh and camera or a Yeti Surprise, and includes 2 minifigures, both dressed for adventures in the winter landscape.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31081, 'Modular Skate House', 422, 'Enjoy awesome activities at the 3-in-1 Modular Skate House!', 'Create your dream location with the 3-in-1 Modular Skate House, featuring a detailed interior with radio, TV and sofa, plus a large outdoor skateboard ramp, monkey bars, climbing wall and a basketball hoop. You can also take a ride on a scooter or try your hand at some graffiti art. Mix and combine the buildable modules and easily swap the windows, door and other modular sections to customize the Modular Skate House with the LEGO® Creator modular system. This 3-in-1 construction toy also rebuilds into a Games Arcade with machines and a corner café or a Skate Park complete with an exciting skateboard track, and includes 2 minifigures, both ready for fun and adventure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (31313, 'LEGO® MINDSTORMS® EV3', 601, 'Create and command robots that do what you want with LEGO® MINDSTORMS® EV3!', 'Combining the versatility of the LEGO® building system with the most advanced technology we\'ve ever developed, LEGO MINDSTORMS® EV3 lets you unleash a world of walking, talking and thinking robots that do anything you can imagine. Complete a series of challenging missions using the intuitive icon-based EV3 Programmer App for tablet devices to build and program TRACK3R, R3PTAR, SPIK3R, EV3RSTORM and GRIPP3R, and then create your own programs. Take your robotics skills to the next level with the companion EV3 Software for PC and Mac, with its more advanced yet familiar programming interface. For instant control, download the free Robot Commander app for smart devices or use the infrared remote control included with each set. Want to share your own creations and be inspired by others? Log on to LEGO.com/MINDSTORMS to access a world of exciting content and interact with a huge online community of LEGO MINDSTORMS fans. The LEGO MINDSTORMS EV3 robot revolution continues!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (40171, 'LEGO® Friends Buildable Hedgehog Storage', 249, 'Keep things safe inside this cute buildable hedgehog!', 'Build a big version of the cute hedgehog animal figures you can find in LEGO® Friends sets. Add a big blue and pink bow to accessorize, or build it without. Then lift off the top of the hedgehog to find a handy storage compartment inside.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (40270, 'Valentine\'s Bee', 140, 'Say “I love you” with a LEGO® BrickHeadz™ Valentine\'s Bee!', 'Build your way to someone’s heart and say “Bee my Valentine’s honey” with this cute LEGO® BrickHeadz™ construction character. Check out its cute pink cheeks, movable wings, detachable heart decoration, pot of honey, and roses and sunflowers. It also comes with a buildable collector\'s baseplate with a seasonal calendar and BrickHeadz logo for your loved one to display in their home, office or anywhere they like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (40271, 'Easter Bunny', 126, 'Hop to it with a LEGO® BrickHeadz™ Easter Bunny!', 'Hunt for eggs with this fun LEGO® BrickHeadz™ Easter Bunny construction character. Check out its cute cheeks and enormous movable ears. This perfect seasonal gift also comes with a detachable carrot and bucket, plus 2 Easter eggs and flowers, and stands on a buildable collector\'s baseplate with a seasonal calendar and BrickHeadz logo for easy display in the home, office or anywhere they like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (40307, 'Castle Interior Kit', 115, 'Decorate and customize your castle!', 'Make your castle fit for a princess with this LEGO® l Disney Castle Interior Kit, featuring small, buildable castle furniture and household items, assorted decorative accessory elements, a fabric rug and blanket, plus decorative stickers. Rebuild the furniture to make alternative items using the pictures for inspiration. Use this kit to customize your LEGO® l Disney building toys and inspire even more role-play fun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (40388, 'Mini-Doll Dress-Up Kit', 80, 'Create beautiful mini-doll outfits!', 'Kit out your mini-doll figures in Disney Princess style with the LEGO® l Disney Mini-Doll Dress-Up Kit, featuring a buildable sewing machine, dressing table, vanity table with chair and a clothes rack, plus assorted accessory elements. Use this kit to customize your LEGO® l Disney sets and inspire even more role-play fun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41066, 'Anna & Kristoff’s Sleigh Adventure', 174, 'Help Anna and Kristoff bring summer back to Arendelle!', 'Enter the world of Disney Frozen on an exciting sleigh ride with Anna and Kristoff. Whether you\'re traveling through the snow or shopping for winter supplies at Wandering Oaken\'s Trading Post, Kristoff\'s sleigh allows you to reenact memorable scenes from the film and create new stories of your own. Includes Anna and Kristoff mini-doll figures plus Sven the reindeer.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41123, 'Foal\'s Washing Station', 77, 'Pamper Emma\'s cute pet foal at the Foal\'s Washing Station!', 'Care for Emma\'s pet foal with the LEGO® Friends Foal\'s Washing Station. With a turntable and flexible hose to clean the horse thoroughly, plus lots of accessory elements for grooming and feeding, you can primp and pamper her to perfection. Includes an Emma mini-doll figure, plus a foal.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41124, 'Heartlake Puppy Daycare', 286, 'Look after Heartlake\'s coolest canines!', 'Look after playful pups with Andrea and Mia at LEGO® Friends Heartlake Puppy Daycare. Outside there\'s a dog park with agility obstacles with a functioning roundabout and a podium. Inside there\'s a bath, grooming station, feeding station, dog beds and an office area inside. Includes 2 mini-doll figures plus a Husky and a Pug.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41126, 'Heartlake Riding Club', 575, 'Train for the next big horse show at the Heartlake Riding Club!', 'Train and care for horses at the LEGO® Friends Heartlake Riding Club with rotating exerciser and adjustable-height jump. There\'s a stable for each horse, a changing room, cafeteria, loft bedroom and a range of riding and horse-care accessory elements. Includes Mia and Stephanie mini-doll figures, plus 2 horses and a mouse.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41127, 'Amusement Park Arcade', 174, NULL, 'Hand in your ticket, take your aim and play all day at the LEGO® Friends Amusement Park Arcade. First push the lever to shoot the basketball into the hoop. Push the trigger on the water gun to shoot the projectile and knock down the 3 targets. Then take the mallet and try to whack the frog right down. Includes a Mia mini-doll figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41128, 'Amusement Park Space Ride', 195, NULL, 'The LEGO® Friends Amusement Park Space Ride comes with articulated arms and hologram stickers to create great speed effects. As you spin the ride faster, the arms lift the rockets higher into the air. There\'s also a photo booth with movable camera to catch the action, and an ice cream stand to cool down after the ride. Includes an Olivia mini-doll figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41130, 'Amusement Park Roller Coaster', 1124, NULL, 'Push the LEGO® Friends Amusement Park Roller Coaster around the track, sit a mini-doll in the front carriage to activate the light brick, and activate the cool functions as you go! Turn the Ferris wheel with its swinging gondolas, then push the car to the top of the drop tower and release to watch it go spinning round. This set is full of detailed functions and accessories for a day at the iconic Amusement Park. Includes 4 mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41132, 'Heartlake Party Shop', 176, 'Head to the Heartlake Party Shop for all your celebration supplies!', 'Explore the LEGO® Friends Heartlake Party Shop, with opening door and all the supplies you can need for a great party. Turn the revolving carousel to see all the products, then browse the balloon and accessories stands. Place your chosen gift inside a gift box and don\'t forget to check out the gumball machine and chocolate fountain! Includes 2 mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41134, 'Heartlake Performance School', 774, 'Learn to sing, dance and play with friends in Heartlake City!', 'Travel to the LEGO® Friends Heartlake Performance School in the iconic yellow school bus with opening doors and removable roof. Use the opening lockers to store school stuff then head to the classroom, canteen or studio—the musical instruments can all be removed to create a performance space with viewing bench and rotating speaker outside. Includes Andrea, Noah and Iva mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41142, 'Palace Pets Royal Castle', 186, 'Host a grand ball for all the Palace Pets!', 'With LEGO® Disney Whisker Haven Tales with the Palace Pets™ you can play with and care for these beloved royal pets within the much-loved Disney Princess environment. Whisker Haven is a magical land where the pets can meet and play together. Build the Palace Pets Royal Castle with its golden roof and customizable towers, then throw a royal ball with your own touch of fairytale magic.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41143, 'Berry\'s Kitchen', 61, 'Make a cake for Berry’s tea party!', 'With LEGO® | Disney Whisker Haven Tales with the Palace Pets™, the beloved royal pets of your favorite Disney Princess characters can all meet and play together. Berry’s Kitchen is the perfect venue for a woodland tea party, and it’s modular, so you can rebuild it in different ways for more baking fun. Includes Berry.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41144, 'Petite\'s Royal Stable', 75, 'Win the show jumping prize with Petite!', 'With LEGO® Disney Whisker Haven Tales with the Palace Pets™, the beloved royal pets of your favorite Disney Princess characters can all meet and play together. Help Petite win the show jumping trophy and then get her ready to go out to a tea party! Includes Petite.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41145, 'Ariel and the Magical Spell', 222, 'Explore the secrets of the sea with Ariel and Flounder.', 'Slide back the glass door and step inside Disney Princess™ Ariel’s Cave. Swim over to Ursula’s grotto and place Ariel at the revolving stand to reveal her human legs. This set is easy to build and perfect for fans of Disney’s The Little Mermaid to reenact their favorite scenes or create new stories of their own. Includes 2 mini-doll figures plus a Flounder figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41146, 'Cinderella\'s Enchanted Evening', 350, 'Drive off in Cinderella’s beautiful horse-drawn carriage!', 'Reenact scenes from the iconic Disney movie, Cinderella, with this easy-to-build model. Play with Cinderella in her house with kitchen and upstairs sleeping area. Then change her into her ball gown and go to the ball in the carriage—and take off the roof for easy play inside with 2 seats for Cinderella and her Fairy Godmother. Includes 2 mini-doll figures, plus 2 figures: a horse and a mouse.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41147, 'Anna\'s Snow Adventure', 153, 'Take a break with Anna and her horse on their journey!', 'Enter the world of Disney Frozen and join Anna as she takes a break on her journey to visit her sister. With a feeding station for her horse and a campfire to make hot chocolate, they have everything they need to rest and refuel. The sleeping shelter has an opening function for easy play inside. Includes an Anna mini-doll, plus her horse.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41148, 'Elsa\'s Magical Ice Palace', 701, 'Spend a day in the snow at Elsa’s enormous Magical Ice Palace!', 'Build a grand and glittering Ice Palace for Elsa and feel the magic and adventure with the special sliding bridge and revolving staircase functions. There’s so much detail inside and out to help recreate scenes from Disney’s Frozen and Frozen Fever, or to create new and exciting stories with these much-loved characters. Includes Elsa and Anna mini-dolls plus Olaf, Marshmallow and four Snowgies.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41149, 'Moana’s Island Adventure', 205, 'Help Moana find the heart of Te Fiti and fulfill her destiny!', 'Explore the beautiful world of Disney’s Moana with Moana’s Island Adventure. Recreate memorable scenes from the movie as Moana learns about the legends of her ancestors, finds the heart of Te Fiti and plays the drums in the cave. Then create new adventures of your own, living out island life in and around her house with Pua her pet pig. Includes a Moana mini-doll, plus Pua the pig.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41150, 'Vaiana\'s Ocean Voyage', 307, 'Set sail with Vaiana to restore the heart of Te Fiti!', 'Discover the vibrant world of Disney’s Vaiana and join her on her epic adventure to bring back the heart of Te Fiti and restore harmony. This beautiful sailboat with opening storage under the deck, and island with transformation function, are perfect for recreating iconic scenes from the movie or creating new stories by the sea. Features a Vaiana mini-doll, Maui big figure, Heihei and two Kakamora.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41151, 'Mulan\'s Training Day', 104, 'Get in training with Disney Mulan, ready for the challenge ahead!', 'LEGO® l Disney Mulan’s Training Day is easy to build and perfect for recreating favorite moments from the movie. Train hard using the turning training dummy, and sword and catapult with boulders, before taking a break with her foal, Khan. This LEGO® l Disney toy for girls and boys includes lots of beautiful and authentic details, including Mulan\'s yellow dress, her fan and a tea ceremony. Get creative using the modular design to easily move and swap sections within the model, or integrate the family temple with other compatible LEGO l Disney sets to build your own dream creations. Includes a mini-doll figure plus a horse figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41152, 'Sleeping Beauty\'s Fairytale Castle', 322, 'Help Disney Aurora turn the spinning wheel in her Fairytale Castle!', 'LEGO® l Disney Sleeping Beauty’s Fairytale Castle is easy to build and perfect for playing out favorite moments from Disney’s Sleeping Beauty. There’s a bedroom, spinning wheel, vanity and a special birthday cake. Maleficent’s lair adds drama and excitement to the role-play action. Get creative using the modular design of this fun toy to easily move and swap sections within the model, or rearrange the rooms of the castle and integrate them with other compatible LEGO l Disney toys to build your own dream creations. Includes 2 mini-doll figures plus Merryweather and bunny figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41153, 'Ariel\'s Royal Celebration Boat', 380, 'Sail off to new adventures with Disney Ariel and Eric.', 'LEGO® l Disney Ariel’s Royal Celebration Boat has everything you need to play out a happy ending for Disney’s The Little Mermaid’s Ariel and Prince Eric. Dance on the revolving dancefloor under the gazebo, spin Sebastian’s starfish decks, discover secret treasure and launch the colored firework bricks. Get creative using the modular design of this great children\'s toy to easily move and swap sections within the model, or integrate the gazebo with other compatible LEGO l Disney toys to build your own dream creations. Includes 2 mini-doll figures plus Sebastian and Max figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41154, 'Cinderella\'s Dream Castle', 585, 'Dine and dance at the Dream Castle with Disney Cinderella.', 'LEGO® l Disney Cinderella’s Dream Castle is the ultimate set to play out your fairytales, whether recreating scenes from Disney’s Cinderella or creating new stories of your own. With a grand dining room, bedroom, dressing area, kitchen, fireplace and balcony, there\'s so much to explore and hidden secrets to discover in this popular toy for kids. Get creative using the modular design to easily move and swap sections within the model, or rearrange the rooms of the castle and integrate them with other compatible LEGO l Disney toys to build your own dream creations. Includes 2 mini-doll figures plus a foal and 2 mice figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41155, 'Elsa\'s Market Adventure', 125, 'Visit Arendelle Market with Elsa and Olaf!', 'Join much-loved characters Elsa and Olaf on LEGO® l Disney Elsa’s Market Adventure. There’s a cart selling fruit and vegetables, a flower stall under the beautiful clock tower, and a dock with a rowing boat for picnics on the water. Turn the clock face brick to set summer or Frozen wintertime scenes with this great toy for girls and boys. Get creative using the modular design to easily move and swap sections within the model, or integrate the clock tower with other compatible LEGO l Disney toys to build your own dream creations. Includes an Elsa mini-doll figure plus Olaf with his personal snow flurry.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41181, 'Naida\'s Gondola & the Goblin Thief', 67, 'Protect the crystals from the goblin thief!', 'Join the exciting new adventures in Elvendale with Naida the water elf as she goes in search of rare ingredients and crystals in the unexplored goblin forest. Ride the river in her gondola with a seat, basket with crystals, map and a compass. Defend the crystals from Roblin the Goblin on the island with its spyglass, evil instructions and hidden catapult with evil seeds. Includes a mini-doll figure plus a goblin figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41182, 'The Capture of Sophie Jones', 226, 'Protect Sophie Jones from being captured in Elvendale!', 'Join the exciting new adventures in Elvendale with Sophie Jones, as she sneaks through the magic portal and visits Mr. Spry’s grocery store. This set features a store with price list, groceries, a bed on the second level, as well as a hidden magic portal and a goblin capture-mobile with a lowering net. Includes a mini-doll figure plus goblin and squirrel figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41183, 'The Goblin King\'s Evil Dragon', 339, 'Search for crystals in the cave with the evil Goblin King!', 'Join the exciting new adventures in Elvendale with Cronan Darkroot the Goblin King as he goes in search of crystals to power his evil portal. Fly on the back of Ashwing, with a cage for crystals, and posable wings with gripping claws, plus a crystal cave with hiding place for Lil’ Blu and an explosion function to reveal a crystal. Includes a mini-doll figure plus a goblin, momma bear and bear cub.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41185, 'Magic Rescue from the Goblin Village', 637, 'Explore the secret Goblin Village without getting caught!', 'Take part in exciting new Elvendale adventures in the Goblin Village, featuring three buildings loaded with accessories, including a crystal workshop with magnifying glass and rotating crystal platform, cage-making workshop with lookout perch and dungeon with exploding gate function, activated by pulling down on the plant. Includes two mini-doll figures plus three goblins, a panther and a chameleon figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41186, 'Azari & the Goblin Forest Escape', 145, 'Escape the carnivorous plants with Azari and Firebolt!', 'Join exciting adventures in Elvendale as Azari the fire elf evades Guxlin the Goblin and its carnivorous plant traps in her flying Fire Chariot, featuring extending flames, space for up to 3 mini-doll figures, crossbow shooter and her pegasus, Firebolt. Includes a mini-doll figure, plus animal and goblin figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41187, 'Rosalyn\'s Healing Hideout', 460, 'Heal the baby dragon and transform a goblin from bad to good!', 'Join exciting adventures in Elvendale as Rosalyn Nightshade the healer elf aids the elves in their quest and guards the forest with Sapphire the dragon, featuring translucent wings, space for 2 mini-doll figures and the baby dragon on her back, plus an unfolding tree that reveals a hidden 2-level treehouse with an alchemy room and medical workstation. Includes 2 mini-doll figures, plus a goblin and 3 animal figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41188, 'Breakout from the Goblin King\'s Fortress', 695, 'Stop the Goblin King’s evil plan and rescue Emily Jones’ sister!', 'Join the exciting adventures in Elvendale as Emily Jones sneaks into the Goblin King’s Fortress to save her sister, Sophie Jones. This set includes Emily’s raft with a grappling hook and movable rudder, plus the fortress with a lowering drawbridge, secret door behind the crystals, firing catapult, revolving throne and a dangling cage over snapping plants. Includes 3 mini-doll figures plus goblin and shadow raven figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41190, 'Emily Jones & the Eagle Getaway', 149, 'Help Emily Jones find the lost diary page and outwit the shadow bat!', 'Seek the magic within to recover the stolen magical diary page with Emily Jones and Lumia the eagle! This thrilling LEGO® Elves set features a fully posable and buildable eagle figure with space for a mini-doll figure, cave with rotating treasure chest and upside-down bed for the bat, plus a ledge with a bat glider with disc shooter. This creative play set includes a mini-doll figure, plus bat and spider figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41191, 'Naida & the Water Turtle Ambush', 205, 'Help Naida defend the Guardian Water Turtle from the shadow bat!', 'Seek the magic within to help Naida protect the Elemental Guardian creature! This exciting LEGO® Elves building toy features a large buildable water turtle with movable head and legs, and space for a mini-doll figure, plus a small island with disc shooter and a boat with chain shooter and space for a bat. Includes a mini-doll figure, small turtle figure, fish figure and a bat figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41192, 'Azari & the Fire Lion Capture', 360, 'Free the Guardian Fire Lion from the evil shadow bats’ chain!', 'Seek the magic within to help Azari and the Guardian Fire Lion face the shadow bats! This thrilling LEGO® Elves construction toy features a buildable magic fire lion with movable legs, wings and tail, opening jaw and space for a mini-doll figure. There\'s also a bat capture vehicle with raising chain pole, catapult and detachable small glider, plus a small bat cave with opening spiderweb door, 2 bat beds and additional accessories. Includes a mini-doll figure, plus 2 bat figures and a spider figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41193, 'Aira & the Song of the Wind Dragon', 451, 'Join forces with Aira and Lumia to protect the Wind Dragon!', 'Seek the magic within to help Aira, Lumia and the Guardian Wind Dragon face the shadow bat! This amazing LEGO® Elves toy for girls and boys features a fully posable and buildable wind dragon with transparent wings and space for 2 mini-doll figures. The set also includes a bat airship with shooting function and spinning propeller, and a ‘floating\' island music school with opening entrance door, hidden chest and rotating sign. Includes 2 mini-doll figures, plus bat and bird figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41194, 'Noctura\'s Tower & the Earth Fox Rescue', 646, 'Rescue the captured Guardian Earth Fox from Noctura’s tower!', 'Seek the magic within to help Farran free the Guardian Earth Fox and then together face Noctura and her evil shadow bats! This fantastic LEGO® Elves creative play set features a fully posable and buildable earth fox with opening jaw and movable legs, head and translucent tail, plus a 2-level tower with opening translucent bat wings, moving head, spiderweb trap/door, disc shooter, space for the 4 Elemental ‘diamonds\' and additional accessories. Includes 2 mini-doll figures plus spider and 2 bat figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41230, 'Batgirl™ Batjet Chase', 206, 'Recover Batgirl’s ePad from the evil Kryptomite™!', 'Join in the action-packed LEGO® DC Super Hero Girls™ world as Batgirl™ battles the yellow Kryptomite™ for her stolen ePad. This great set features a Batgirl mini-doll figure, the Batjet with opening cockpit, stud shooters on the wings and a net shooter at the front, plus Kryptomite buggy with an ePad and a fearful yellow Kryptomite.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41231, 'Harley Quinn™ to the rescue', 217, 'Save the super hero café from the evil Kryptomites!', 'Join in the action-packed LEGO® DC Super Hero Girls™ world as Harley Quinn™ battles the mischievous green Kryptomites at the Capes and Cowls Café. This great set features Harley Quinn™ and Steve Trevor™ mini-doll figures, a two-level café building with a cupcake catapult and rotating arcade machine, plus Harley Quinn’s jet with movable wings, a net shooter, and two mischievous green Kryptomites.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41232, 'Super Hero High School', 712, 'Train your skills and learn how to become a Super Hero!', 'Join in the action-packed LEGO® DC Super Hero Girls™ world as Supergirl™ and Poison Ivy™ battle Lena Luthor™. This great set features three mini-doll figures, a three-level school building with swiveling classrooms, café, extending ramp, chain and disc shooters, Poison Ivy’s motorbike and Lena’s jet with rotating thrusters and a gripping claw at the front, plus two hypnotized purple Kryptomites.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41233, 'Lashina™ Tank', 145, 'Rescue Krypto™ from Lashina’s clutches!', 'Join in the action-packed LEGO® DC Super Hero Girls™ world as Supergirl’s dog Krypto™ faces Lashina™ and the blue Kryptomite™. This great set features a Lashina mini-doll figure, Lashina’s tank with a stud shooter and space in the back for Krypto, plus Krypto’s house with defense shield and a catapult. Includes Krypto and a confused blue Kryptomite.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41234, 'Bumblebee™ Helicopter', 142, 'Keep the crystals from the evil Kryptomites!', 'Be part of the action-packed LEGO® DC Super Hero Girls™ world as Bumblebee™ protects her shipment of crystals from the Kryptomites. This great set features a Bumblebee™ mini-doll figure, helicopter with opening cockpit, spinning rotors, stud shooters, zipline and space in the back for the crystals, plus a dumpster and small stud shooter for the two angry red Kryptomites.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41237, 'Batgirl™ Secret Bunker', 351, 'Help Batgirl™ nab Mad Harriet™ and recover the microchip!', 'Join in the action-packed LEGO® DC Super Hero Girls™ world as Batgirl™ and her Bat-Bot encounter Mad Harriet™ and the green Kryptomite™ when they break into the Batgirl Secret Bunker! This great set features an opening bunker with 2 levels including a workout area, IT lab, gear-up area, zipline, Bat-Wagon with foldout wings and foldup wheels, and plenty of accessory elements.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41238, 'Lena Luthor™ Kryptomite™ Factory', 432, 'Stop Lena Luthor™ from making evil little Kryptomites!', 'Join in the action-packed LEGO® DC Super Hero Girls™ world as Supergirl™ confronts Lena Luthor™ at the Kryptomite™ factory! This great set features a 3-level factory with lab, Kryptomite dispenser/slide, crystal element, break-out door, holding cell, rooftop shooter and a ‘power drain’ room, plus Lena Luthor’s getaway boat, Supergirl’s jet boat with dual shooters, Krypto™ and 3 Kryptomite figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41239, 'Eclipso™ Dark Palace', 1078, 'Rescue The Flash™ from Eclipso’s evil plans!', 'Join in the action-packed LEGO® DC Super Hero Girls™ world as Wonder Woman™ battles Eclipso™ to save The Flash™! This great set features a cool foldout palace with 2 levels, 4 ‘power drain’ tubes, planning room, vanity and weapons cabinets, Eclipso’s Jewel Jet, Wonder Woman’s Invisible Jet, loads of accessory elements, plus 3 orange Kryptomites.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41300, 'Puppy Championship', 185, 'Help Mia’s cute pups win the Championship!', 'Join Mia and her puppies for a LEGO® Friends dog show. With grand entrance doors, a revolving turntable, agility seesaw and a jump with knockable bar, the dogs can show off their skills all day long. There are steps up to a judging platform and a fun slide, microphone, and grooming and feeding stations. Includes a mini-doll figure, plus two dog figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41301, 'Puppy Parade', 145, 'Arrive at the dog show in style with a puppy limo!', 'Drive the Puppy Parade limo, with its cute doggy features and space inside for all of the LEGO® Friends puppies you’ve collected. Arrive at the podium to award Apollo with the golden puppy trophy, and catch it all on the TV camera with Andrea presenting on the microphone. Includes a mini-doll figure plus a dog figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41302, 'Puppy Pampering', 45, 'Get puppy Lara ready for her big dog show debut!', 'Groom Lara the puppy all day long with LEGO® Friends Puppy Pampering, featuring a bubble bath, vanity with mirror and fan and a dog bowl with juicy bone. Includes a dog figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41303, 'Puppy Playground', 62, 'Train for the big dog show with Sky the puppy!', 'Practice dog agility tricks all day with Sky the puppy in the LEGO® Friends Puppy Playground, featuring a tilting seesaw, jump with knockable bar, and big hoop jump with a bone as a reward! Includes a dog figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41306, 'Mia\'s Beach Scooter', 79, 'Hop on the scooter and zoom off to catch some waves!', 'Find the best surf spots in LEGO® Friends Mia’s Beach Scooter with sidecar, then use the two surfboards to catch some waves with Toffee the Pug before relaxing with a drink of water, and using the binoculars to look out to sea. Includes a mini-doll figure plus Toffee the Pug figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41309, 'Andrea\'s Musical Duet', 86, 'Sing your heart out with Andrea and her pet parrot!', 'Play and perform with LEGO® Friends Andrea’s Musical Duet. Pop Cleo the parrot on the revolving bird stand, then help Andrea sound check her electric guitar and stand at the microphone. Give a great performance with Andrea and Cleo, turning the revolving stage for an added special effect. Includes a mini-doll figure plus a parrot figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41310, 'Heartlake Gift Delivery', 185, 'Drive the van to send special gifts all around Heartlake City!', 'Help Stephanie make a LEGO® Friends Heartlake Gift Delivery, featuring a van and shop facade with a gift stand, mailbox and a cash register. Select a present from the stand, pack it into a gift box and then use the sack truck to help load it into the van for deliveries all around Heartlake City. Includes a mini-doll figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41311, 'Heartlake Pizzeria', 289, 'Enjoy pizza with friends at Heartlake’s Italian restaurant!', 'The LEGO® Friends Heartlake Pizzeria has all the equipment needed to play at making and baking fresh pizza in the kitchen. Serve them out on the restaurant balcony, or use the phone to take orders then deliver them with Oliver on the scooter. There’s even a stand selling basil and tomato plants to happy customers. Includes two mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41312, 'Heartlake Sports Center', 328, 'Stay fit and healthy at the Heartlake Sports Center!', 'Get active at the LEGO® Friends Heartlake Sports Center. Inside the sliding entrance door there are lockers, a gym with a punch bag and gymnastic rings, juice bar, rolling treadmill and a yoga studio with an exercise bar, weights and a yoga mat. Outside there’s a bike rack, soccer goal and basketball game with shooting function. Includes two mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41313, 'Heartlake Summer Pool', 589, 'Enjoy swimming in the sunshine at the Heartlake Summer Pool!', 'The LEGO® Friends Heartlake Summer Pool is the place to be when the sun is shining, with a long slide into the water, springing diving board and a swim-up bar for a refreshing drink. There’s an outdoor shower behind the aquarium as well as a block with restroom, lifeguard stand, and a hot tub with day bed for a truly relaxing experience. Includes two mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41314, 'Stephanie\'s House', 622, 'Make cakes ready for a party at Stephanie’s House!', 'Explore and play in LEGO® Friends Stephanie’s House, featuring a kitchen with bay window, opening fridge and oven, lounge with television and spiral staircase up to a bedroom with curved balcony, shower room and an office. Share friendship moments on the swing chair on the porch, and look after the baby rabbit in his hutch. Includes three mini-doll figures plus a baby rabbit figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41315, 'Heartlake Surf Shop', 186, 'Get ready for a day of watersports action at the Surf Shop!', 'The LEGO® Friends Heartlake Surf Shop includes a cash register and all kinds of holiday supplies. Hire a range of watersports equipment, from surfboards, a kayak and paddle to flippers and a waterproof camera. Outside there’s a beach area with sun lounger and shower, a jetty with buoys and a rock, which is home to a seal figure. Includes a mini-doll figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41316, 'Andrea\'s Speedboat Transporter', 309, 'Cruise in style to the hottest beach party in town!', 'LEGO® Friends Andrea’s Speedboat Transporter is the coolest way to cruise the Heartlake coastline by land or sea. The sporty beach car has a trailer and rope for towing, and the speedboat has steering controls and a turning propeller. Enjoy the party scene with a juice bar, beach area, sun loungers and a barbecue. Includes 2 mini-doll figures and a turtle figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41317, 'Sunshine Catamaran', 603, 'Jump aboard the luxury Sunshine Catamaran with friends!', 'Take a luxury cruise on the LEGO® Friends Sunshine Catamaran, with a sun deck, pool, bridge, slide, spiral stairs, garage and sliding doors into the living quarters. Lift the top off the boat for easy access to the kitchen, bedrooms and lounge with a clear bottom. Use the personal water scooter to pull the banana boat or inflatable ring, and play with the friendly dolphin all day long. Includes 3 mini-doll figures and 2 dolphin figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41318, 'Heartlake Hospital', 871, 'Look after the sick and injured people of Heartlake City!', 'The LEGO® Friends Heartlake Hospital has 3 floors of medical rooms and equipment to help care for patients. There’s a nursery with crib and weighing scales, an x-ray suite with scanner and lightbox, and an examination room with a bed and microscope for checking samples. The downstairs waiting room has a reception desk and vending machine as well as an emergency entrance for those arriving by ambulance or helicopter. Includes 3 mini-doll figures plus a newborn baby figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41319, 'Snow Resort Hot Chocolate Van', 246, 'Keep warm with delicious hot chocolate from the van!', 'Drive and play in the hot chocolate van with rotating hot chocolate mug icon on top for all to see. Inside there’s a hot chocolate machine with whipped cream and cookies to sell. Outside there’s a table for customers and a double slide with 2 sledges for endless winter fun. Includes 2 mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41320, 'Heartlake Frozen Yogurt Shop', 370, 'Chill out with frozen yogurt at Heartlake’s coolest hangout!', 'The LEGO® Friends Heartlake Frozen Yogurt Shop comes with a frozen yogurt machine with self-serve function, bar with a choice of toppings, weighing scales, phone to take orders, inside seating area and outside table with a parasol. There’s also a drive thru with ordering station and a cool yellow car with room to carry your frozen yogurt on the back. Includes 2 mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41322, 'Snow Resort Ice Rink', 307, 'Glide across the ice and show off your skills!', 'Take to the ice with the LEGO® Friends Snow Resort Ice Rink, featuring an outdoor rink with opening doors, hockey goals and a seating area. Give a performance on the revolving stage at the skating lodge, hire hockey and skating equipment and buy yourself a treat at the pretzel shop. There’s even a tree where a friendly bunny lives. Includes 2 mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41323, 'Snow Resort Chalet', 402, 'Stay cozy and warm in the beautiful log cabin!', 'The LEGO® Friends Snow Resort Chalet has an outdoor hot tub, kitchen and a lounge area with log fire. Upstairs there’s a bedroom with 3 beds, vanity and a dog bed. There’s also a cool snowmobile for exploring and a cute husky puppy to look after. Includes 2 mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41324, 'Snow Resort Ski Lift', 585, 'Get into winter sports with friends at the snow resort!', 'The LEGO® Friends Snow Resort Ski Lift is the ultimate winter sports resort for the friends from Heartlake City. Enjoy the mountaintop restaurant, working ski lift, ski slope sliding function, rock climbing wall, ski hire stand, trail map and the little bear with his own slope and mountain cave. There are enough activities to keep you busy all winter! Includes 2 mini-doll figures, plus a bear cub figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41325, 'Heartlake City Playground', 326, 'Have fun playing at Heartlake City Playground with Mia and Sienna!', 'Designed by 9 year old Sienna – winner of the LEGO® Friends Designer contest.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41326, 'LEGO® Friends Advent Calendar', 217, 'Count down to Christmas with LEGO® Friends!', 'Open the LEGO® Friends Advent Calendar each day in December to add a piece to your Christmas party scene. Includes a Stephanie mini-doll figure in a calendar with 24 secret compartments, each containing its own buildable surprise.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41327, 'Mia\'s Bedroom', 86, 'Explore Mia’s bedroom and discover her personality!', 'This LEGO® Friends Mia’s Bedroom building toy is set on a green heart-shaped base and perfectly reflects Mia’s outdoorsy spirit. She has a tree house-style bed with steps, a little house for her pet bunny underneath, a skateboard and ramp to practice new tricks, plus more sporting equipment, bunny treats and a walkie-talkie to keep in touch with her friends. Includes a mini-doll figure and a bunny figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41328, 'Stephanie\'s Bedroom', 95, 'Stephanie is always on the go… even at home in her bedroom!', 'This LEGO® Friends Stephanie’s Bedroom construction toy is set on a blue heart-shaped base and perfectly reflects Stephanie’s sporty personality. It has its own mini golf putting green with a ball and golf club, a little doghouse, a mobile phone to call friends, an alarm clock and a trophy to show Stephanie\'s sporting achievements. Includes a mini-doll figure and a puppy figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41329, 'Olivia\'s Deluxe Bedroom', 163, 'Work on Olivia’s latest invention in her hi-tech bedroom!', 'LEGO® Friends Olivia’s Deluxe Bedroom is set on a pink heart-shaped base and perfectly reflects Olivia’s scientific side. Her robot has a functioning elevator and track system to get to the top of the room, and there’s a separate breakfast area with a coffee machine that pops the mug out when the coffee is ‘ready\'. You\'ll also find a desk with computer and drawers, swivel chair, rocket-shaped bed and a tablet. This fun toy includes a mini-doll figure and a buildable robot figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41330, 'Stephanie\'s Soccer Practice', 119, 'Score goal after goal with Stephanie and Dash!', 'LEGO® Friends Stephanie’s Soccer Practice features a soccer goal with moving goalkeeper platform, and a football launcher with shooting function for endless play with this great children’s toy, alone or with a friend. There’s also a strategy board and a drinks station, plus Stephanie\'s pet puppy to add to the fun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41332, 'Emma\'s Art Stand', 210, 'Spend a day painting in the park with Emma and Chico!', 'Use the scooter to tow LEGO® Friends Emma’s Art Stand wherever you like with this cool toy for kids. It has double windows that open as a sales hatch, various artwork tiles, a cash register, Heartlake City Park map and a bed for Emma’s cat. Lift off the roof or swing open the entire back of the trailer for easy play inside. There\'s also a separate area with an easel and stool next to a tree. Includes a mini-doll figure plus cat figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41333, 'Olivia\'s Mission Vehicle', 223, 'Drive to the rescue in Heartlake City with Olivia and Zobo.', 'LEGO® Friends Olivia’s Mission Vehicle comes with an Olivia mini-doll, a buildable Zobo figure and a cat figure, and there is room to fit all 5 girls from Heartlake City inside this popular kids’ toy! Discover the secret compartment under Zobo’s control center with a map of Heartlake City Park. Use the satellite to find people who need help and put up the ladder to help rescue the cat from the tree.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41334, 'Andrea\'s Park Performance', 229, 'Put on a show in the park with Andrea and Pepper!', 'This LEGO® Friends Andrea’s Park Performance toy for girls and boys includes a stage with 2 different sets. Put on a puppet show with moving puppet function or rotate the stage background to give a musical performance featuring a piano with moving keys. There are park benches for the audience and a hot dog stand selling food and water. Includes 2 mini-doll figures, plus a baby and a bird figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41335, 'Mia\'s Tree House', 351, 'Climb up to the tree house and help Mia settle in!', 'This LEGO® Friends Mia’s Tree House construction toy is packed with features and details to create hours of fun for Mia, her brother, and any friends who might come to visit. There’s a folding ladder, scramble net and a zip wire for access to and from the second floor, plus a water gun, a book of ghost stories, artwork tiles, board game, pizza, sports equipment, Mia\'s skateboard and much more inside. Includes 2 mini-dolls plus 2 animal figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41336, 'Emma\'s Art Café', 378, 'Get inspired with Emma at her favorite Art Café!', 'LEGO® Friends Emma’s Art Café is where the people of Heartlake City meet up and get creative over a bite to eat. The iconic design of this fun toy features a giant panini on the roof, while inside is a panini machine, coffee machine, seating area and cash register. There\'s also an outside art area that is hinged so it can be moved around, and a bench full of paints for the resident graffiti artist. Includes 2 mini-doll figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41338, 'Stephanie\'s Sports Arena', 460, 'Show off your sporting prowess at the Sports Arena!', 'LEGO® Friends Stephanie’s Sports Arena features 2 cool game functions to keep sports fans playing with this cool children’s toy all day long. There’s a tennis court with a moving ball function and a basketball arena with shooting function. In the main building, there\'s an entrance hall, souvenir shop, taco bar and a spectator stand, plus 2 floodlights. Includes 2 mini-dolls.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41339, 'Mia\'s Camper Van', 488, 'Set up camp with Mia’s luxury camper van!', 'LEGO® Friends Mia’s Camper Van makes camping with friends a dream! Lift off the roof of this cool toy for kids for easy access to the kitchen and bathroom inside, flip open the lid of the upstairs sleeping area, put up the canopy and get to work on the tent with 2 beds inside. There\'s also a picnic table, an inflatable dinghy and a friendly horse for endless outdoor adventures! Includes 2 mini-dolls and a horse figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41340, 'Friendship House', 722, 'Plot mission after mission together at the Friendship House!', 'The LEGO® Friends Friendship House is the ultimate base for special moments between the friends of Heartlake City—whether starting adventures or enjoying some downtime. This popular kids’ toy features a kitchen, living room with craft table, bedroom with double-sided TV screen, terrace with speakers, barbecue, hot tub, juice bar and a lookout tower on the roof. Outside, there\'s a swing, a bike with a trailer full of tools and lots of cool features in this converted fire station building including a working pulley, alarm, pole, slide and a garage with opening door. Includes 3 mini-dolls plus 3 animal figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41485, 'Finn', 91, 'Join the Resistance with a LEGO® BrickHeadz construction character featuring Finn!', 'This LEGO® BrickHeadz construction character featuring Finn is fun to build using LEGO bricks that recreate all of his iconic details from the blockbuster Star Wars: The Force Awakens movie, including First Order Stormtrooper armor and utility belt. He also has a detachable blaster pistol and stands on a buildable collector’s baseplate with BrickHeadz icon for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41486, 'Captain Phasma™', 127, 'Lead the First Order with a LEGO® BrickHeadz construction character featuring Captain Phasma™', 'This LEGO® BrickHeadz construction character featuring Captain Phasma™ is fun to build using colorful LEGO bricks that recreate all of her iconic details from the blockbuster Star Wars: The Force Awakens movie, including Stormtrooper armor, helmet and a buildable cape. She also has a detachable blaster pistol and stands on a buildable collector’s baseplate with BrickHeadz icon for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41487, 'Lloyd', 102, 'Unleash your true ninja spirit with LEGO® BrickHeadz Lloyd!', 'This Lloyd LEGO® BrickHeadz construction character is fun to build using colorful LEGO bricks that recreate all of his iconic details, including ninja outfit with headband and belt. He also has a detachable katana sword and stands on a buildable collector’s baseplate with BrickHeadz icon for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41488, 'Master Wu', 89, 'Learn the way of the ninja with LEGO® BrickHeadz Master Wu!', 'This Master Wu LEGO® BrickHeadz construction character is fun to build using colorful LEGO bricks that recreate all of his iconic details, including white kimono, buildable golden hat and flowing beard. He also has a detachable staff and stands on a buildable collector’s baseplate with BrickHeadz icon for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41585, 'Batman™', 91, 'Celebrate THE LEGO® BATMAN MOVIE with a LEGO BrickHeadz Batman!', 'New for March 2017, LEGO® BrickHeadz construction characters bring you a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. This Batman™ BrickHeadz construction character is fun to build using colorful LEGO System bricks that recreate all of his iconic details, including his Batsuit with icon and utility belt decoration, plus a Batarang. He also stands on a buildable baseplate with series number and BrickHeadz icon for easy display, so you can bring the Caped Crusader to any room or office.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41586, 'Batgirl™', 99, 'Channel Batgirl™ with your own LEGO® BrickHeadz version!', 'New for March 2017, LEGO® BrickHeadz construction characters bring you a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. This Batgirl™ BrickHeadz construction character is fun to build using LEGO System bricks that recreate all of her iconic details, including her Batgirl icon and a yellow Batarang. She also stands on a buildable baseplate with series number and BrickHeadz icon for easy display. Whatever the mission, Batgirl will not let you down.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41587, 'Robin™', 101, 'Showcase the Boy Wonder with LEGO® BrickHeadz Robin™!', 'New for March 2017, LEGO® BrickHeadz construction characters bring you a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. This Robin™ BrickHeadz construction character is fun to build using colorful LEGO System bricks that recreate all of his iconic details, including icon and outfit. Proudly display Batman’s junior counterpart in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41588, 'The Joker™', 151, 'Show off the evil trickster with LEGO® BrickHeadz The Joker™!', 'New for March 2017, LEGO® BrickHeadz construction characters bring you a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. This The Joker™ BrickHeadz construction character is fun to build using LEGO System bricks that recreate all of his iconic details from THE LEGO BATMAN MOVIE, including BrickHeadz eyes, buildable white face, green hair and outfit. Display Batman’s enigmatic archenemy in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41590, 'Iron Man', 96, 'Stand your ground with your own LEGO® BrickHeadz Iron Man!', 'New for March 2017, LEGO® BrickHeadz construction characters are a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. This Iron Man BrickHeadz construction character is fun to build using colorful LEGO System bricks that recreate all of his iconic details, including red and yellow suit of armor decoration. He also stands on a buildable baseplate with series number and BrickHeadz icon for easy display, so you can add a touch of Iron Man mightiness to any room or office.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41591, 'Black Widow', 143, 'Recruit your own elite agent with LEGO® BrickHeadz Black Widow!', 'New for March 2017, LEGO® BrickHeadz construction characters bring you a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. This Black Widow BrickHeadz construction character is fun to build using LEGO System bricks that recreate all of her iconic details, including black costume with belt and red buckle decoration, and buildable iconic hair! She also comes with two detachable batons and stands on a baseplate with series number and BrickHeadz icon for easy display. Whatever the assignment, you will be glad to have this Russian femme fatale fighting on your side.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41592, 'The Hulk', 93, 'Have a smashing time with LEGO® BrickHeadz The Hulk!', 'New for March 2017, LEGO® BrickHeadz construction characters bring you a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. This larger-than-life Hulk BrickHeadz construction character is fun to build using colorful LEGO System bricks that recreate all of his iconic details, including buildable fists and hair, plus decorated muscles. Flex your new BrickHeadz muscles in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41593, 'Captain Jack Sparrow', 109, 'Treasure your own LEGO® BrickHeadz construction character featuring Disney’s Captain Jack Sparrow!', 'New for March 2017, LEGO® BrickHeadz construction characters bring you a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. From Disney Pirates of the Caribbean: Dead Men Tell No Tales comes this BrickHeadz construction character featuring Captain Jack Sparrow, which is fun to build using colorful LEGO System bricks that recreate all of his iconic details, including a belt, headband and long flowing hair. He also has a buildable and detachable cutlass in hand and stands on a baseplate with series number and BrickHeadz icon for easy display. Bring a dram of swashbuckling pirate adventure to your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41594, 'Captain Armando Salazar', 118, 'Lead a LEGO® BrickHeadz ghost crew featuring Disney’s Captain Armando Salazar!', 'New for March 2017, LEGO® BrickHeadz construction characters bring you a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. This BrickHeadz construction character featuring Captain Armando Salazar is fun to build using LEGO System bricks that recreate all of his iconic details, including buildable hair and decorated waistcoat and buttons. He also has a buildable and detachable cutlass in hand and stands on a baseplate with series number and BrickHeadz icon for easy display. Add some Disney Pirates of the Caribbean: Dead Men Tell No Tales swashbuckling action to your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41595, 'Belle', 139, 'Add some Disney fairytale romance with a LEGO® BrickHeadz construction character featuring Belle!', 'New for March 2017, LEGO® BrickHeadz construction characters bring you a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. This beautiful BrickHeadz construction character featuring Belle is fun to build using colorful LEGO System bricks that recreate all of her iconic details from the classic Disney animation Beauty and the Beast, including buildable flowing hair with a ribbon and earrings. She also has a buildable rose in hand and stands on a baseplate with series number and BrickHeadz icon. Add some fairytale romance to your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41596, 'Beast', 116, 'Bring a classic Disney tale to life with a LEGO® BrickHeadz construction character featuring Beast!', 'New for March 2017, LEGO® BrickHeadz construction characters bring you a brand new way to collect, build and display iconic characters from your favorite movies, TV series, games and comics. This BrickHeadz construction character featuring Beast is fun to build using colorful LEGO System bricks that recreate all of his iconic details, including decorated waistcoat outfit and buildable mane and horns, as seen in the classic Disney animation Beauty and the Beast. He also stands on a baseplate with special design for easy display.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41597, 'Go Brick Me', 708, 'Build a LEGO® BrickHeadz version of yourself!', 'Fuel your creativity by making a LEGO® BrickHeadz version of yourself, friends and family or colleagues with this fun set. Create two BrickHeadz construction characters using the specially selected LEGO bricks for different hairstyles and skin color, plus there are two kinds of glasses, a sticker sheet to personalize your builds, and a brick separator. Display your creations on the buildable baseplates in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41598, 'The Flash™', 122, 'Live life in the fast lane with LEGO® BrickHeadz The Flash™!', 'The Flash™ LEGO® BrickHeadz construction character is fun to build using colorful LEGO bricks that recreate all of his iconic details, including buildable golden ear wings and lightning chest logo. He also stands on a buildable collector’s baseplate with BrickHeadz icon for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41599, 'Wonder Woman™', 143, 'Stand tall with LEGO® BrickHeadz Wonder Woman™!', 'This Wonder Woman™ LEGO® BrickHeadz construction character is fun to build using colorful LEGO bricks that recreate all of her iconic details, including flowing black hair, headdress and gauntlets. She also has a detachable sword and shield in her hands, and stands on a buildable collector\'s baseplate with BrickHeadz icon for easy display. Add some Amazonian Warrior power to your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41600, 'Aquaman™', 135, 'Dive in with LEGO® BrickHeadz Aquaman™!', 'This Aquaman™ LEGO® BrickHeadz construction character is fun to build using colorful LEGO bricks that recreate all of his iconic details, including flowing beard and hair, scale-like armor and buckle. He also has a detachable trident and stands on a buildable collector\'s baseplate with BrickHeadz icon for easy display. Add a splash of Justice League excitement in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41601, 'Cyborg™', 108, 'Get an upgrade with LEGO® BrickHeadz Cyborg™', 'This Cyborg™ LEGO® BrickHeadz construction character is fun to build using colorful LEGO bricks that recreate all of his iconic details, including a cybernetic face mask with an infrared eye and body armor. He also has a cannon arm and stands on a buildable collector\'s baseplate with BrickHeadz icon for easy display. Have a blast in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41602, 'Rey', 119, 'Feel the Force with a LEGO® BrickHeadz construction character featuring Rey!', 'This LEGO® BrickHeadz construction character featuring Rey is fun to build using colorful LEGO bricks that recreate all of her iconic details from the blockbuster Star Wars: The Last Jedi movie, including decorated torso and belt. She also has a detachable Lightsaber and stands on a buildable collector\'s baseplate with BrickHeadz icon for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41603, 'Kylo Ren™', 130, 'Summon the dark side with a LEGO® BrickHeadz construction character featuring Kylo Ren™!', 'This LEGO® BrickHeadz construction character featuring Kylo Ren™ is fun to build using LEGO bricks that recreate all of his iconic details from the blockbuster Star Wars: The Last Jedi movie, including decorated torso and belt. He also has a detachable Lightsaber and stands on a buildable collector\'s baseplate with BrickHeadz icon for easy display in your home, office or any galaxy you choose.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41604, 'Iron Man MK50', 101, 'Save the universe with LEGO® BrickHeadz Iron Man MK50!', 'This Iron Man MK50 LEGO® BrickHeadz construction character is fun to build using colorful LEGO bricks that recreate all of his iconic details from the blockbuster Avengers: Infinity War movie, including his electromechanic armor suit. He also has thrusters for a speedy getaway and stands on a buildable collector\'s baseplate for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41605, 'Thanos', 105, 'Feel the power of Infinity with LEGO® BrickHeadz Thanos!', 'This Thanos LEGO® BrickHeadz construction character is fun to build using colorful LEGO bricks that recreate all of his iconic details from the blockbuster Avengers: Infinity War movie, including purple skin, chest armor and Infinity Gauntlet with Infinity gem decorations. He also stands on a buildable collector\'s baseplate for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41606, 'Star-Lord', 113, 'Be a legendary outlaw with LEGO® BrickHeadz Star-Lord!', 'This Star-Lord LEGO® BrickHeadz construction character is fun to build using colorful LEGO bricks that recreate all of his iconic details from the blockbuster Avengers: Infinity War movie, including golden hair, battle helmet, red eyes and boot rockets. He also has dual detachable blasters and stands on a buildable collector\'s baseplate for easy display in your home, office or any galaxy you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41607, 'Gamora', 136, 'Master the skills of a green-skinned assassin with LEGO® BrickHeadz Gamora!', 'This Gamora LEGO® BrickHeadz construction character is fun to build using colorful LEGO bricks that recreate all of her iconic details from the blockbuster Avengers: Infinity War movie, including green skin, dark pink hair highlights and black outfit. She also has a detachable sword and stands on a buildable collector\'s baseplate for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41608, 'Han Solo™', 141, 'Be a rogue with a LEGO® BrickHeadz™ construction character featuring Han Solo!', 'This LEGO® BrickHeadz™ 41608 Han Solo is fun to build using colorful LEGO bricks that recreate all of his iconic details from the Star Wars saga, including a brown jacket and utility belt. He also has a detachable blaster and stands on a buildable collector\'s baseplate with BrickHeadz logo for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41609, 'Chewbacca™', 149, 'Growl like a Wookiee with a LEGO® BrickHeadz™ construction character featuring Chewbacca!', 'This LEGO® BrickHeadz™ 41609 Chewbacca is fun to build using colorful LEGO bricks that recreate all of his iconic details from the Star Wars saga, including matted fur and ammunition belt. He also has a detachable blaster and stands on a buildable collector\'s baseplate with BrickHeadz logo for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41610, 'Tactical Batman™ & Superman™', 209, 'Join the Justice League™ with LEGO® BrickHeadz™ Tactical Batman™ and Superman™!', 'These LEGO® BrickHeadz™ 41610 Tactical Batman™ and Superman™ construction characters are fun to build using colorful LEGO bricks that recreate all their iconic details from the blockbuster Justice League™ movie, including Super Hero costumes and capes. Each stands on a buildable collector\'s baseplate with BrickHeadz icon for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41611, 'Marty McFly & Doc Brown', 240, 'Travel back to the future with LEGO® BrickHeadz™ Marty McFly and Doc Brown!', 'These LEGO® BrickHeadz™ 41611 Marty McFly and Doc Brown construction characters are fun to build using colorful LEGO bricks that recreate all their iconic details from the blockbuster Back to the Future movie, including the maverick scientist’s white overalls and the time-traveling teenager\'s red puffer vest. Doc also has a detachable DeLorean time machine controller, while Marty comes with a detachable camcorder. Each character stands on a buildable collector\'s baseplate with BrickHeadz icon for easy display in your home, office or anywhere—at any time—you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41613, 'Mr. Incredible & Frozone', 160, 'Join Mr. Incredible and Frozone for LEGO® BrickHeadz™ crime-fighting fun!', 'These LEGO® BrickHeadz™ 41613 Mr. Incredible & Frozone construction characters are fun to build using colorful LEGO bricks that recreate all their iconic details from Disney•Pixar’s blockbuster Incredibles 2 movie. Each character stands on a buildable collector\'s baseplate with BrickHeadz logo for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (41614, 'Owen & Blue', 234, 'Train a raptor with LEGO® BrickHeadz™ Owen and Blue!', 'These LEGO® BrickHeadz™ 41614 Owen & Blue construction characters are fun to build using colorful LEGO bricks that recreate all their iconic details from the blockbuster Jurassic World: Fallen Kingdom movie, including a dino trainer, Owen’s tranquilizer gun and velociraptor Blue\'s ferocious white teeth. Each character stands on a buildable collector\'s baseplate with BrickHeadz logo for easy display in your home, office or anywhere you like.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42031, 'Cherry Picker', 155, 'Reach dizzying heights with the awesome LEGO® Technic Cherry Picker!', 'Reach dizzying heights with the awesome LEGO® Technic Cherry Picker! This tough 2-in-1 model is packed with realistic details, including a working boom with basket, 4 warning lights, sturdy wheels and a detailed lifting mechanism. Let’s get to work! This 2-in-1 model rebuilds into a robust Tow Truck.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42032, 'Compact Tracked Loader', 252, 'Clear the ground with the LEGO® Technic Compact Track Loader!', 'Clear the ground with the Compact Tracked Loader! This robust LEGO® Technic model has all the features of the real-life machine, including a sophisticated, rear-hinged boom mechanism that provides full control of the huge bucket and grabber, roof spotlights, warning beacon, gear lever and large triangular crawler tracks for increased traction and maneuverability on soft terrain. A cool white, gray and black color scheme adds the finishing touch to this awesome model! Rebuilds into a powerful Snow Groomer.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42033, 'Record Breaker', 125, 'Smash land speed records with the LEGO® Technic Record Breaker!', 'Smash land speed records with the LEGO® Technic Record Breaker! This sleek, aerodynamic dragster features supercool blue, white and gray color scheme, tinted canopy, detailed engine and a powerful, high-speed pull-back motor. Climb aboard if you dare! Combine with the 42034 Quad Bike to create the mega-awesome Extreme Off-Roader for even more high-speed action!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42036, 'Street Motorcycle', 375, 'Take to the open road with the LEGO® Technic Street Motorcycle!', 'Cruise on the open road with the awesome LEGO® Technic Street Motorcycle! This cool, sturdy model has all the features of the real-life machine, including full fairing, rugged front and rear suspension, chain drive, working steering, kickstand, detailed engine with moving pistons and a sporty, light blue and red color scheme. Experience the joy of motorcycling! This 2-in-1 model rebuilds into a cool Retro Bike.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42037, 'Formula Off-Roader', 494, 'Take on mountainous terrain with the LEGO® Technic Formula Off-Roader!', 'Power over mountainous terrain with the sturdy LEGO® Technic Formula Off-Roader! Featuring a fresh lime green and blue color scheme, huge deep-tread tires mounted on cool lime green rims, working steering, robust chassis, hinged cab cage, large roof-mounted spotlights and a detailed 4-cylinder engine with moving pistons. This realistic model with super-rugged suspension is geared up for the toughest off-road action! Rebuilds into a high-speed Muscle Racer.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42039, '24 Hours Race Car', 1219, 'Scream around the circuit in the lightning-fast LEGO® Technic 24 Hours Race Car!', 'Scream around the circuit in the lightning-fast 24 Hours Race Car! This robust, immaculately detailed LEGO® Technic model has all the features of a real-life race car, including a detailed V8 engine with moving pistons, opening gull-wing doors, all-round independent suspension, working front steering, high fenders and an opening front trunk and engine hood. Put on your racing gloves and step on the gas! Upgrade with the 8293 Power Functions motor set (not supplied) and you have bright LED headlights plus motorized gull wing doors and engine cover. This 2-in-1 model rebuilds into a SUV Racer.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42044, 'Display Team Jet', 113, 'Thrill the crowds with the Display Team Jet!', 'Perform thrilling aerial maneuvers with the aerodynamic 2-in-1 Display Team Jet, featuring a large cockpit, retractable undercarriage and a yellow, black and white color scheme with black-and-white checkered racing stickers. This robust 2-in-1 LEGO® Technic model can be rebuilt to create a Stunt Plane for a double build-and-play experience. Digital 3D building instructions for both models are available online.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42045, 'Hydroplane Racer', 180, 'Thunder over the ocean with the Hydroplane Racer!', 'Enter the water speed championships with the Hydroplane Racer, featuring a unique aerodynamic design with large sponsons, large cockpit and a blue and white color scheme with black-and-white checkered racing stickers. This robust 2-in-1 LEGO® Technic model also features moving engine pistons and a spinning propeller, and can be rebuilt to create a Race Boat for a double build-and-play experience! Digital 3D building instructions for both models are available online.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42049, 'Mine Loader', 476, 'Call in the powerful Mine Loader!', 'Head underground aboard this authentic replica of a real-life mine loader, featuring a yellow and black color scheme, versatile working grabber, detailed engine with moving pistons, articulated central steering mechanism and huge tires. This rugged 2-in-1 LEGO® Technic model also includes a cargo element, and can be rebuilt to create a Mine Cutting Machine for a double build-and-play experience! Digital 3D building instructions for both models are available online.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42052, 'Heavy Lift Helicopter', 1043, 'Airlift massive loads with the Heavy Lift Helicopter!', 'Call in the mighty 2-in-1 Heavy Lift helicopter with an array of intricate technical details and motorized functions, including contra-rotating rotors, opening loading ramp and cargo bay doors and a working winch. This model also features movable elevator and rudders, a multidirectional nose wheel and a buildable cargo accessory. Comes with an orange, white and gray color scheme. Rebuilds into a Tandem Rotor Helicopter.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42053, 'Volvo EW160E', 1166, 'Operate the powerful Volvo EW160E!', 'Get to know the high-tech innovation of the Volvo EW160E with this authentic LEGO® Technic replica of the real-life wheeled excavator. This detailed model, developed in partnership with Volvo Construction Equipment, has been designed to provide an immersive and rewarding build and play experience and features an advanced pneumatic system for operation of the extendable boom and working bucket. Manual features and functions include a detailed, height-adjustable cab with seat, armrests, sun visor and adjustable mirrors, rotating superstructure, rear-controlled front steering, working front blade and extendable outriggers. Upgrade with the 8293 LEGO Power Functions motor set (not supplied) for a fully motorised boom and working lights. This 2-in-1 model can be rebuilt to create a Volvo L30G compact material handler.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42054, 'CLAAS XERION 5000 TRAC VC', 1977, 'Harness the awesome power of the CLAAS XERION 5000 TRAC VC', 'Explore the high-tech world of industrial farm machines with this authentic LEGO® Technic replica of the CLAAS XERION 5000 TRAC VC. This highly detailed 2-in-1 model has been designed to provide an immersive and rewarding build and play experience, and comes with an array of motorized functions including a rotating operator\'s cab, working crane arm and extendable outriggers. Manual functions include front-wheel, 4-wheel and crab steering, and a working crane claw. The model comes with the trademarked green, gray and red color scheme, detailed operator\'s cab, 4 huge tractor tires and a tree trunk element for extended play scenarios. It can also be rebuilt to create a CLAAS XERION 5000 TRAC VC with Silage Plow.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42055, 'Bucket Wheel Excavator', 3929, 'Experience the huge Bucket Wheel Excavator!', 'Enter the world of mining on a colossal scale with the massive Bucket Wheel Excavator—the largest LEGO® Technic set to date! This highly detailed 2-in-1 model has been designed to provide an immersive and rewarding build and play experience, and comes with an array of motorised functions, including forward and reverse driving, moving conveyor belts, working boom with revolving bucket wheel, and a rotating superstructure. You can even rebuild the model to create a Mobile Aggregate Processing Plant.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42056, 'Porsche 911 GT3 RS', 2704, 'Discover the iconic Porsche 911 GT3 RS!', 'Experience the iconic Porsche 911 GT3 RS with this authentic LEGO® Technic replica. Inside the box you’ll discover a special collector’s book chronicling the history of LEGO Technic and Porsche GT cars, together with 4 original-design rims bearing the RS emblem. The sets of elements are boxed, and the building sequence gives an insight into the real-life vehicle’s assembly process. The model features detailed, orange bodywork, red suspension springs, detailed headlights, taillights, brake calipers and rims with low-profile tires. The accessible cockpit features a detailed dashboard, working gearbox, steering wheel with gearshift paddles, racing seats and a glove compartment containing a unique serial number. Functions include opening doors and hood with storage compartment and suitcase, and an opening rear lid that houses a detailed flat 6 engine with moving pistons. This 1:8 scale model has been designed to provide an immersive and rewarding building experience.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42057, 'Ultralight Helicopter', 199, 'Take to the skies with the Ultralight Helicopter!', 'Enjoy aerial adventures with this aerodynamic one-man helicopter, featuring spinning main and tail rotors, controllable tail rudder, detailed engine with moving pistons, open cockpit with detailed seat, and a white, red and black color scheme with a selection of stickers for an authentic helicopter look. This robust 2-in-1 LEGO® Technic model can be rebuilt to create an Experimental Aircraft, providing a double build-and-play experience. Both models can be built by following the free interactive, 3D digital LEGO Building Instructions app.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42058, 'Stunt Bike', 140, 'Hit the ramp at high speed with the awesome Stunt Bike!', 'Perform impressive stunts with this high-speed LEGO® Technic Stunt Bike model, featuring a yellow and black color scheme with checkered racing stickers, front and rear lights, authentic exhaust pipes and extra-wide rims with low profile tires. The Stunt Bike is also equipped with a pull-back motor, and comes with a buildable stunt ramp. Combine with the 42059 Stunt Truck pull-back model for extended play possibilities or to create the Power Racer combi model.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42059, 'Stunt Truck', 142, 'Fly off the ramp at high speed with the super-fast Stunt Truck!', 'Perform amazing stunts with this high-speed LEGO® Technic Stunt Truck model, featuring a blue, black and white color scheme with checkered racing stickers, sturdy front bumper and wide blue rims with low profile tires. This Stunt Truck is also equipped with a pull-back motor, and comes with a buildable stunt ramp. Combine with the 42058 Stunt Bike pull-back model for extended play possibilities or to create the Power Racer combi model.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42060, 'Roadwork Crew', 365, 'Call in the Roadwork Crew!', 'Get to work with this exciting, two-vehicle LEGO® Technic Roadwork Crew set, featuring a truck with working steering, tipping flatbed and a removable trailer, plus a tracked digger with rotating superstructure and working boom and bucket. This detailed 2-in-1 set comes with a classic orange, gray and black color scheme and can be rebuilt to create a Mini Gritter with Plow, providing a double build-and-play experience! Both models can be built by following the free interactive, 3D digital LEGO Building Instructions app.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42061, 'Telehandler', 260, 'Utilize the power and reach of the awesome Telehandler!', 'Reach for the sky with this replica of a real-life telehandler. This robust 2-in-1 LEGO® Technic model comes with a red, gray and black color scheme and an array of realistic features and functions, including a detailed cab, large tires, working four-wheel steering, extendable boom and a tipping bucket. Rebuild this model to create a Tow Truck for a double build-and-play experience! Both models can be built using the free interactive, 3D digital LEGO Building Instructions app, available online.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42062, 'Container Yard', 631, 'Grab, lift, load and deliver at the Container Yard!', 'Enjoy a rewarding build-and-play experience with this robust and detailed 2-in-1 LEGO® Technic Container Yard set, featuring an articulated truck with working steering, opening doors, detachable trailer and two loadable containers, plus a container loader with working steering and extendable boom with working grabber. This set can be rebuilt to create a Container Straddle-Carrier with truck and container. Both models can be built using the free interactive, 3D digital LEGO Building Instructions app, available online.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42063, 'BMW R 1200 GS Adventure', 603, 'Experience the BMW R 1200 GS Adventure!', 'Explore the high-tech innovation of the BMW R 1200 GS Adventure with this authentic LEGO® Technic replica, featuring a blue and black color scheme, black spoke wheels with all-terrain tires, windshield and a detailed dashboard and exhaust. Functions include handlebar steering, front and rear suspension, two-cylinder boxer engine with moving pistons, visible shaft drive, opening top case and luggage panniers, and a kickstand. This 2-in-1 model has been designed to provide an immersive and rewarding building experience. It was developed in partnership with BMW and rebuilds into a unique concept model, created in collaboration with BMW designers. A free interactive, 3D digital LEGO® Building Instructions app is available online, for both models.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42064, 'Ocean Explorer', 1327, 'Discover new horizons with the Ocean Explorer!', 'Enjoy seafaring adventures with this LEGO® Technic Ocean Explorer set, featuring a ship with a dark-blue, red and white color scheme, plus a buildable submarine with movable arms and spinning propeller, and a buildable helicopter with spinning rotors. The ship features a large captain’s bridge with radar and funnel detailing, plus a landing pad, working crane and an opening deck hatch for access to the ship’s hull, complete with bulbous bow and two fenders. This detailed 2-in-1 set has been designed to provide an immersive and rewarding building experience and can be rebuilt to create a Push Boat and Barge.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42065, 'RC Tracked Racer', 370, 'Travel over the toughest terrain with the RC Tracked Racer!', 'Spin, turn, clamber over obstacles and race at breakneck speed with this fully motorized, remote-controlled LEGO® Technic RC Tracked Racer, featuring a lime-green, white and black color scheme with decorative stickers, driver’s cab with roll bars and two large tracks, each powered by six wheels. Drive forward or backward, left or right and make 360° turns. Rebuild to create an RC Off-Road Truck.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42066, 'Air Race Jet', 1151, 'Prepare for vertical takeoffs and landings with the Air Race Jet!', 'Reach supersonic speeds with this huge, aerodynamic LEGO® Technic Air Race Jet, featuring a blue, black and red color scheme with racing stickers and an array of intricate technical details and motorized functions, including an adjustable jet nozzle for vertical or horizontal takeoff position, hatch access to a spinning fan, opening fuselage, retractable undercarriage, and adjustable flaps. Manual functions include working front steering, movable tail rudders and an opening cockpit. This robust and highly detailed 2-in-1 model has been designed to provide an immersive and rewarding build-and-play experience and can be rebuilt to create a Private Jet.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42068, 'Airport Rescue Vehicle', 1098, 'Mobilize the Airport Rescue Vehicle!', 'Head for the runway with this authentic 2-in-1 LEGO® Technic Airport Rescue Vehicle, featuring a red, black and gray color scheme, working boom mechanism, 4-cylinder engine with moving pistons, large driver’s cab with detailed dashboard, wing mirrors, equipment storage compartment, twin-axle steering, double rear axle and chunky tires. Upgrade with the 8293 Power Functions motor set (not supplied) for a motorized boom mechanism and working warning beacons. Rebuild this model to create a Fire Rescue Vehicle for a double build-and-play experience.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42069, 'Extreme Adventure', 2382, 'Traverse uncharted territory with the Extreme Adventure!', 'Experience the ultimate in traction and maneuverability with the Extreme Adventure vehicle, featuring 4 high-grip tracks with working suspension, upswing doors with lowering running board function, raisable roof tent, working winch, front steering, opening hood, detailed V8 engine with moving pistons and a lockable tailgate. Also includes a sliding storage drawer, side storage compartment with a first aid kit and 2 fire extinguishers, and a roof rack with 2 jerry cans in a rare dark-green color. This 2-in-1 LEGO® Technic model comes in a yellow, black and purple color scheme with decorative sticker detailing, and can be rebuilt to create a Mobile Base Vehicle.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42070, '6x6 All Terrain Tow Truck', 1862, 'Harness the power of the mighty 6x6 All Terrain Tow Truck!', 'Carry out vehicle rescue operations with the fully remote-controlled 6x6 All Terrain Truck. This authentic 2-in-1 LEGO® Technic model features a blue, red, yellow and black color scheme, large chunky tires, heavy-duty bull bar with chain and hook, movable lights and a detailed driver’s cab with opening doors. Remote-controlled functions include forward and reverse drive, front steering, extendable outriggers, and a working crane and winch. Rebuild this model to create a Research Explorer Vehicle for a double build-and-play experience.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42071, 'Dozer Compactor', 171, 'Call in the powerful Dozer Compactor!', 'Capture the awesome power of a real-life dozer compactor with this 2-in-1 LEGO® Technic replica, featuring a host of realistic functions and details, including a driver’s cab, working blade and steering, and realistic hard compactor wheels. This advanced building set comes with a fresh blue, gray, black and orange color scheme with stickers for additional detailing. Rebuild to create an Articulated Truck for a double build-and-play experience.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42072, 'WHACK!', 135, 'Get ready for high-speed action and impacts with the WHACK!', 'Experience the amazing power and acceleration of this high-speed LEGO® WHACK! model, featuring a lime-green, red and gray color scheme with racing stickers, sturdy front bumper, large rear spoiler and wide black rims with low profile tires. This advanced building set is equipped with a pull-back motor and a new-for-December-2017 engine pop-out function, which is activated on impact. Combine with the 42073 BASH! pull-back model for extended play possibilities or to create the WHACK! ‘N\' BASH! combi model.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42073, 'BASH!', 139, 'Get ready for high-speed action and impacts with the BASH!', 'Experience the amazing power and acceleration of this rugged, high-speed LEGO® BASH! model, featuring a red, black and gray color scheme with racing stickers, sturdy front bumper, large rear spoiler and wide black rims with low profile tires. This advanced building set is equipped with a pull-back motor, and an engine pop-out function, which is activated on impact. Combine with the 42072 WHACK! pull-back model for extended play possibilities or to create the WHACK! ‘N\' BASH! combi model.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42074, 'Racing Yacht', 330, 'Put the wind in your sails with this amazing Racing Yacht!', 'Enter the world of water sports with this amazing LEGO® Technic Racing Yacht, featuring a sporty yellow and blue color scheme with maritime racing stickers, colorfully printed sails with lines and winches, and a detailed hull. Turn the ship’s wheel or move the tiller to operate the rudder and wind the winches to move the sails. This sturdy 2-in-1 advanced building set can be rebuilt to create a highly detailed Catamaran.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42075, 'First Responder', 513, 'Explore iconic vehicle design with the First Responder!', 'Enjoy a rewarding build and play experience with this awesome replica of a fire department SUV, featuring a red and black color scheme with sticker detailing, wide black rims with chunky tires, blue warning beacons, and roof-mounted spot lamps. This highly detailed 2-in-1 LEGO® Technic advanced building set also features a range of functions, including working steering and suspension, working winch and a raisable light tower, plus a driver\'s cab with opening doors and a storage compartment with a selection of tool accessories.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42076, 'Hovercraft', 1020, 'Transport supplies over land and sea with the all-terrain Hovercraft!', 'Reach inhospitable areas with the LEGO® Technic Hovercraft set, featuring a black and white color scheme, working crane with operator’s cab and a raisable loading platform. Maneuver the Hovercraft to spin the twin rear fans and operate the working steering to move them left and right. This advanced building set also includes an expedition truck with a detachable cargo container. Rebuild the set to create a Jet Boat.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42077, 'Rally Car', 1005, 'Push the limits with the awesome LEGO® Technic Rally Car!', 'Discover awesome detail and design with this amazing 2-in-1 LEGO® Technic Rally Car model, featuring sporty blue, white, red and black bodywork with racing stickers, large rear spoiler, 4 spot lamps and 6-spoke red rims with low-profile tires. This advanced building set also features a detailed cockpit with racing seats and roll cage, 2-fan engine cooling system, opening hood and rear hatch, and a V6 engine with moving pistons. Rebuild the Rally Car to create a Buggy for a double build and play experience.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42078, 'Mack Anthem', 2595, 'Discover innovative design with the Mack Anthem truck and trailer!', 'Explore state-of-the-art engineering and design with this authentic LEGO® Technic replica of the Mack Anthem truck and trailer. Developed in partnership with Mack® Trucks Inc., this model comes with an array of realistic technical details and functions, including front-axle steering, rear wheel drive and a 6 cylinder straight engine with working pistons and spinning radiator fan. The detachable trailer has extendable outriggers, working landing legs, synchronized crane arms with side loading capability, and a loadable container with lockable doors, while the accessible driver’s cab has opening doors, adjustable seats, detailed dashboard, steering wheel, sun visors and a bunk bed. This 2-in-1 advanced building set also features a Mack bulldog hood ornament, and can be rebuilt into a detailed replica of the iconic Mack LR garbage truck.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (42084, 'Hook Loader', 176, 'Collect and transport heavy cargo with the Hook Loader!', 'Enjoy a rewarding build-and-play experience with this authentic LEGO® Technic replica of a real-life hook loader, featuring a driver’s cab, heavy-duty tires, large warning light, working steering and hook loading functionality. Turn the crank to lift and lower the cargo container to and from the truck chassis. This 2-in-1 advanced building set can be rebuilt to create an Airport Fire Truck.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45500, 'EV3 Intelligent Brick', 1, NULL, 'This programmable, intelligent brick serves as the heart and brain of LEGO® MINDSTORMS® Education EV3 robots. It features an illuminated six-button interface that changes color to indicate the brick\'s active state, a high-resolution black and white display, built-in speaker, USB port, a mini SD card reader, four input ports and four output ports. The brick also supports USB, Bluetooth and Wi-Fi communication with a computer and has a programming interface that enables programming and data logging directly onto the brick. It is compatible with mobile devices and is powered by AA batteries or the EV3 Rechargeable DC Battery. The brick features:
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45501, 'EV3 Rechargeable DC Battery', 1, NULL, 'The lithium ion EV3 Rechargeable DC Battery is designed for use with the EV3 Intelligent Brick and features a capacity of 2050 mAh. It provides longer run time than AA batteries and can be charged without taking the model apart. The battery is included in the EV3 Education Core Set and has a charge time of around three to four hours. It requires the 45517 DC Charger, which is the same charger as used for the rechargeable NXT DC Battery. These are sold separately.', 4, 5, 25);
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45502, 'EV3 Large Servo Motor', 1, NULL, 'The EV3 Large Servo Motor is a powerful motor that uses tacho feedback for precise control to within one degree of accuracy. By using the built-in rotation sensor, the intelligent motor can be made to align with other motors on the robot so that it can drive in a straight line at the same speed. It can also be used to give an accurate reading for experiments. The motor case design also makes it easy to assemble gear trains.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45503, 'EV3 Medium Servo Motor', 1, NULL, 'The EV3 Medium Servo Motor is great for lower-load, higher speed applications and when faster response times and a smaller profile are needed in the robot’s design. The motor uses tacho feedback for precise control within one degree of accuracy and has a built-in rotation sensor.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45504, 'EV3 Ultrasonic Sensor', 1, NULL, 'The digital EV3 Ultrasonic Sensor generates sound waves and reads their echoes to detect and measure distance from objects. It can also send single sound waves to work as sonar or listen for a sound wave that triggers the start of a program. Students could design a traffic-monitoring system and measure distances between vehicles, for instance. There is an opportunity to discover how the technology is used in everyday items like automatic doors, cars and manufacturing systems.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45505, 'EV3 Gyro Sensor', 1, NULL, 'The digital EV3 Gyro Sensor measures the robot’s rotational motion and changes in its orientation. Students can measure angles, create balancing robots and explore the technology that powers a variety of real-world tools like Segway®, navigation systems and game controllers.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45506, 'EV3 Color Sensor', 1, NULL, 'The digital EV3 Color Sensor distinguishes between eight different colors. It also serves as a light sensor by detecting light intensities. Students can build color sorting and line-following robots, experiment with light reflection of different colors, and gain experience with a technology that is widely used in industries like recycling, agriculture and packaging.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45507, 'EV3 Touch Sensor', 1, NULL, 'The analog EV3 Touch Sensor is a simple but exceptionally precise tool that detects when its front button is pressed or released and is able to count single and multiple presses. Students can build start/stop control systems, create maze-solving robots and uncover the technology’s use in devices such as digital musical instruments, computer keyboards and kitchen appliances.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45508, 'EV3 Infrared Beacon', 1, NULL, 'This has been designed for use with the EV3 Infrared Seeker Sensor. The beacon emits an infrared signal which the sensor can track. The beacon can also be used as a remote control for the EV3 brick through signals sent to the infrared sensor.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45509, 'EV3 Infrared Sensor', 1, NULL, 'The digital EV3 Infrared Seeking Sensor detects proximity to the robot and reads signals emitted by the EV3 Infrared Beacon. Students can create remotely-controlled robots, navigate obstacle courses and learn how infrared technology is used in TV remotes, surveillance systems and even in target acquisition equipment.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45514, 'EV3 Cable Pack', 7, NULL, 'This Cable Pack contains the same seven RJ12 Connector Cables as included in the 45544 EV3 Core Set. The cables can also be used with NXT. The Pack contains:
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (45517, 'Transformer 10V DC', 1, NULL, 'This standard 10V DC transformer allows you to recharge the 9693 Rechargeable Battery, the 45501 EV3 Rechargeable Battery, the 8878 Power Functions Rechargeable Battery Box, and the 45302 Smarthub Rechargeable Battery.', 25, 5, 25);
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60051, 'High-speed Passenger Train', 610, 'Get around LEGO® City fast in the High-speed Passenger Train!', 'Travel around the city in no time with the motorized LEGO® City High-speed Passenger Train! Operate the 8-channel, 7-speed infrared remote control to power around the curved tracks at top speed. This streamlined, super-efficient train has a high-speed front profile and electricity contact points on top. Lift off the roof of the front car to place the driver inside at the cool dashboard and open the passenger cars to access the seats and tables. Wait for the train with the traveler at the way station, and pedal safely across the crossing with the cyclist once the train has gone past. Includes 3 minifigures: train driver, traveler and a cyclist.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60052, 'Cargo Train', 888, 'Move heavy goods across LEGO® City with the Cargo Train!', 'Move heavy goods – and animals! – around the city with the super-powerful LEGO® City Cargo Train! This awesome motorized train with 4-channel, 7-speed, infrared remote control can transport almost anything. So it’s your job to make sure the cargo is in the right place at the right time to keep the city running smoothly. Attach the cattle wagon and 2 cargo wagons together and pull them around the circular rail track with the locomotive. Operate the forklift to move the pallets safely between the wagons and truck. Keep track of all the cargo leaving and arriving in the office at the impressive cargo train station. There you can use the sliding overhead crane with hook to move heavy cargo between vehicles or onto the ground. With so many play functions and cool features, this really is the ultimate set for train enthusiasts! Includes 4 minifigures: forklift driver, train driver, farmer and a truck driver.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60100, 'Airport Starter Set', 81, 'Help get LEGO® City\'s mail on the helicopter!', 'Join the LEGO® City postal workers, featuring a helicopter with spinning main and tail rotors and storage boxes that open, plus 2 hand trucks, a gasoline barrel, mailbox and 3 pieces of mail. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60101, 'Airport Cargo Plane', 157, 'Load up the Cargo Plane and get ready to fly!', 'Get the LEGO® City Airport Cargo Plane ready for delivery, featuring a back hatch that opens, turning nosewheel, big engines and accessible cockpit, plus an airport service car with hand truck and space for 4 packages. Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60106, 'Fire Starter Set', 90, 'Save the dockworker and put out the blaze!', 'Race the fire hovercraft to the pier and put out the fire! Send the diver into the water to save the dockworker and then help the other firefighters put out the flames on the engine. Keep the pier safe and become a LEGO® City firefighting hero!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60107, 'Fire Ladder Truck', 214, 'Put out the burning oil barrel!', 'Be a hero in LEGO® City with the Fire Ladder Truck, featuring an extending ladder that spins 360 degrees and a pull-out fire hose with a special stud-shooter function to knock down the flames. Includes 2 minifigures: a female firefighter and a male firefighter.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60108, 'Fire Response Unit', 257, 'Call the Fire Response Unit for help!', 'Be part of the crew that helps protect LEGO® City from emergencies. The Fire Response Unit features a helicopter that carries water elements in a tank and can drop water elements from its opening cargo doors, a motorcycle with a fire extinguisher, and a container with a roof element that turns when hit by the water bricks to put the fire out. Includes 3 minifigures: a pilot, firefighter and a worker.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60109, 'Fire Boat', 412, 'Save the lighthouse and rescue the keeper with the Fire Boat!', 'Put out the lighthouse fire with the LEGO® City Fire Boat, featuring a movable crane arm, stud-shooting water cannon that can knock down the flames, plus a dinghy, firefighting gear, kitchen, medical station and lighthouse jetty. Includes 5 minifigures: the Captain, 2 male firefighters, a female firefighter and the lighthouse keeper.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60110, 'Fire Station', 919, 'Jump into action and save the hot dog stand… and lunch!', 'LEGO® City\'s Fire Station has 2 garages and a firehouse with 3 floors and a fire pole, in 3 modular sections to build, with a total of 9 combinations for the main firehouse and garages. Features the fire chief\'s car, fire truck with cherry picker and a helicopter. Includes 6 minifigures: 4 male firefighters, a female firefighter and a hot dog stand guy, plus a dog.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60117, 'Van & Caravan', 250, 'Pack up the gear; it’s time to go camping!', 'Spend some time camping with the family with this van with opening doors and detachable caravan that opens from the back, revealing a small kitchen and a bed, as well as a separate grill with sausages and a bone for the family dog. Includes 2 minifigures: a male camper and female camper, plus a dog.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60119, 'Ferry', 301, 'Take the Ferry to your next adventure!', 'Keep things moving in LEGO® City with the Ferry, featuring opening gates, space for a car, 2 fire extinguishers and other accessories. Includes 2 minifigures: a businessperson and ferry boat captain.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60120, 'Volcano Starter Set', 83, 'Explore the volcano and make an exciting discovery!', 'Join the adventure in exploring the LEGO® City Volcano, featuring an eruption function, ATV with walkie-talkie, metal detector, camera, chain and a boulder that opens with a crystal element inside. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60121, 'Volcano Exploration Truck', 175, 'Head off-road and make the big discoveries!', 'Hop in the exploration truck to go explore the volcano, featuring big off-road tires, bull bar on the front, a drill to crack boulders open, a lifting hook and space in the back to transport a boulder back to the lab for study, plus a boulder with a crystal element inside. Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60122, 'Volcano Crawler', 324, 'Bring out the heavy machinery to do exploring right!', 'Make bigger discoveries with the versatile Volcano Crawler, featuring wide tracks to move over any obstacles, a big jackhammer arm that rotates on its base and moves up and down, a boulder rack to hold rocks in place and an ATV with a chain to move boulders around. Includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60123, 'Volcano Supply Helicopter', 330, 'Fly in the exploration gear and fly out the crystals!', 'Bring in goods and fly out discoveries in the Volcano Supply Helicopter, featuring an opening back ramp, spinning rotors, lowering winch and hook, plus an excavator with arm and grabber, boulder opener tool with boulder rack and 2 boulders that open with crystal elements inside. Includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60124, 'Volcano Exploration Base', 824, 'Get busy with some serious scientific work!', 'Take part in the big discoveries with the Volcano Exploration Base, featuring a volcano with eruption function, mobile operations center with detachable truck cab and side opening lab, large excavator with extendable hammer arm that moves up and down, drone with spinning rotors, wheeled dumper, ‘lava\' boulders with crystal elements inside and various tools. Includes 6 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60125, 'Volcano Heavy-lift Helicopter', 1277, 'Help out the volcano explorers and bring in the big equipment!', 'Take part in big discoveries with the massive Volcano Heavy-lift Helicopter, featuring 2 sets of spinning rotors, an opening rear hatch and lowering crane, plus a volcano with eruption function, mobile lab that opens at the front, mobile boulder cracker, lifter, dumper and 4 boulders that open to reveal a crystal element inside. Includes 8 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60129, 'Police Patrol Boat', 200, 'Keep the crook from escaping his boat ride to prison!', 'Lock up the crook and transport him to Prison Island in the LEGO® City Police Patrol Boat, featuring a cell with breakout function, buildable brick spotlight plus a crook\'s boat with an anchor and chain, plus other accessory elements. Includes 4 minifigures: a policeman, policewoman, female crook and a male crook.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60134, 'Fun in the park - City People Pack', 157, 'Fill up your city with people!', 'Grow your city\'s population with this great pack, featuring a wide range of minifigures and endless possibilities for activities, with playground equipment, a picnic table, bench and a hot dog stand. Includes 14 minifigures, plus baby and dog figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60135, 'ATV Arrest', 47, 'Chase down the crook with the ATV!', 'Be part of the action with the LEGO® City police as they keep the city safe, featuring a police ATV and pair of handcuffs, plus a two-wheeled hand truck and safe with opening door, gold bars and a crowbar. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60136, 'Police Starter Set', 80, 'Stop the crooks before they empty the ATM!', 'Be part of the action with the LEGO® City police as they stop the crooks from getting away with the money from the ATM, featuring a police ATV that includes a radio and a set of handcuffs, plus an ATM with breakout function and opening door on the back, money bills, dynamite and a jackhammer. Includes four minifigures plus a police dog figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60137, 'Tow Truck Trouble', 144, 'Catch the crook before he tows the safe away!', 'Be part of the action with the LEGO® City police as they race after the crook trying to tow away a safe. This set includes a tow truck with winch arm and hook, police off-road bike and a police pursuit bike with radio, plus a safe with a large opening door and smaller compartment inside, money bills, jewel and other accessory elements. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60138, 'High-speed Chase', 294, 'Help Chase McCain and the police nab the crook!', 'Be part of the action with the LEGO® City police as they call in Chase McCain to help stop the crook escaping with the loot in the stolen sports car. This set features a police helicopter with spinning rotors and a lowering winch with hook, police pursuit car, stolen sports car and a barrier. Includes four minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60139, 'Mobile Command Center', 374, 'Stop the crooks before they escape from the mobile jail!', 'Be part of the action with the LEGO® City police as they stop the crook’s escape from the jail cell in the Mobile Command Center, featuring a detachable truck cab, room for two minifigures, monitoring room with screens, satellite dish, opening roof, side doors and rear ramp, storage area for the motorbike and tools and a jail cell breakout feature, plus the crooks’ ATV. Includes four minifigures and a police dog figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60140, 'Bulldozer Break-in', 561, 'Protect the bank and stop the crooks!', 'Be part of the action with the LEGO® City police as they protect the bank’s safe and ATM from the crooks and their bulldozer, with a high security truck loaded with accessories, helicopter with searchlight, spinning rotors, plus the crooks’ bulldozer with chains and hooks. Includes five minifigures plus a police dog figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60141, 'Police Station', 894, 'Throw the crooks back in jail after they break out!', 'Be part of the action with the LEGO® City police as they try to keep the crooks in jail, featuring a three-level Police Station loaded with accessory elements, a jail cell with exploding wall function, watchtower, garage and offices, helicopter, police pursuit car and police motorbike, plus the crooks’ truck with rotating, extendable cherry picker. Includes seven minifigures plus a police dog figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60142, 'Money Transporter', 138, 'Catch the crook before she gets away with the safe!', 'Be part of the action with the LEGO® City police as the officer stops the crook from getting away with the safes, featuring a Money Transporter with an opening trapdoor on the roof, lock and opening door on the back, plus two safes, a hand truck, crowbar and other accessory elements. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60143, 'Auto Transport Heist', 403, 'Stop the crooks from stealing their car again!', 'Be part of the action with the LEGO® City police as they haul the crook’s vehicle to impound, featuring an Auto Transporter with an adjustable, two-level rack and lowering ramps, police car and crooks’ motorbike with a sidecar, plus an adjustable barrier with lamppost. Includes four minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60145, 'Buggy', 81, 'Start your engine and race through the dunes!', 'Get behind the wheel and take on the desert with the super-fast LEGO® City Buggy. This tough vehicle features an opening roll cage over the seat, huge chunky tires and a big engine at the back. Includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60146, 'Stunt Truck', 91, 'Strap in and jump some ramps!', 'Get behind the wheel of the LEGO® City Stunt Truck and prepare to make some big air jumps, featuring a truck with a big rear wing and big knobby tires, plus a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60148, 'ATV Race Team', 239, 'Gear up for the big race!', 'Get ready to race with the LEGO® City ATV Race Team. This set features two ATVs, a pickup truck, trailer hitch, pickup bed with adjustable ramp and a detachable trailer with adjustable ramp, plus helmets, fuel barrel and a spare tire. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60150, 'Pizza Van', 249, 'Order a pizza to go!', 'Make and serve some pizza for your customers with the LEGO® City Pizza Van, featuring a van with opening sides and kitchen space in the back, a scooter and a buildable table with parasol. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60153, 'People pack – Fun at the beach', 169, 'Pack your city with a bunch of new people!', 'Grow your LEGO® City population with this people pack, featuring a wide range of minifigures and endless possibilities for activities, with windsurfing and kayaking, volleyball net with ball, trees with hammock and an ice cream stand. Includes 15 minifigures plus dog, fish, dolphin and lobster figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60154, 'Bus Station', 337, 'Hop on, there’s so much to see with the LEGO® City bus!', 'Join the other passengers for a quick and easy ride on the LEGO® City Bus. This cool model features opening front and side doors, a bike rack on the front, seats for minifigure riders, luggage storage space and room for a wheelchair inside, as well as a bus stop with a bike stand, trash can, waiting area and ramp, plus a newsstand with newspapers, fruit and drinks for sale. Includes 6 minifigures and a dog figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60155, 'LEGO® City Advent Calendar', 248, 'Celebrate 24 fun days with the LEGO® City Advent Calendar!', 'Celebrate the holidays with LEGO® City flair, featuring 24 different surprises, one for each day of the season, including Santa’s sleigh, a gingerbread house, Christmas tree, plane, snowman, coast guard helicopter and much more. Includes several different builds and 6 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60156, 'Jungle Buggy', 53, 'Explore the depths of the jungle and find something amazing!', 'Go exploring in the wilds of the LEGO® City jungle with the Jungle Buggy featuring a minifigure cockpit and space in the back for machete and binoculars elements, plus a buildable statue with hidden diamond element, moving leaf and a red spider figure. Includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60157, 'Jungle Starter Set', 88, 'Cruise into the jungle and make a big discovery!', 'Discover what lurks on the banks of the river in the LEGO® City jungle with the Jungle Starter Set, featuring a boat with space for gear and 3 minifigures, a tree with hidden treasure, camera and a working magnifying glass. Includes 3 minifigures, plus snake, frog and crocodile figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60158, 'Jungle Cargo Helicopter', 201, 'Fly into the jungle and explore the hidden temple!', 'Head deep into the LEGO® City jungle with the Jungle Explorer Helicopter, featuring an opening minifigure cockpit, spinning rotors and working winch, an ATV with space for a minifigure, a treasure box and a temple with moving leaf revealing a gold-colored chalice. Includes 2 minifigures, plus a spider figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60159, 'Jungle Halftrack Mission', 378, 'Defend the mission and dodge a surprise in the jungle!', 'Explore what lies within the LEGO® City jungle on a Jungle Halftrack Mission, featuring a truck with tracks on the back wheels, storage space for the chain and tool elements, plus an ATV with removable crate, a buildable campfire and a buildable temple with diamond element and moveable stone that releases a spider. Includes 2 minifigures, plus panther and spider figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60160, 'Jungle Mobile Lab', 426, 'Watch your step while you explore new things in the jungle!', 'Discover exciting things in the depths of the LEGO® City jungle with the Jungle Mobile Lab, featuring a truck with opening sides and roof, a waterfall build with a crocodile and temple with a moving leaf that hides a treasure, plus a buildable Venus flytrap plant with closing ‘mouth’ and a kayak. Includes 4 minifigures plus crocodile and spider figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60161, 'Jungle Exploration Site', 813, 'Discover the secrets of the jungle with the LEGO® City explorers!', 'Uncover amazing things at the Jungle Exploration Site, featuring a plane wreck with opening cockpit, amphibious helicopter with minifigure cockpit, spinning rotors and winch, heavy observation truck with minifigure cab, folding crane arm, observation room and space for the included motorbike on the back, plus an amphibious vehicle with minifigure cab, and cave and temple build. Includes 7 minifigures, plus leopard, crocodile, snake, frog and 2 spider figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60162, 'Jungle Air Drop Helicopter', 1250, 'Haul in fresh supplies at the exploration site!', 'Keep your camp well-supplied in the LEGO® City jungle with the Jungle Air Drop Helicopter, featuring 2 spinning rotors, a clamp system to carry the pallet platform or truck, work tower with rotating crane, riverboat that holds 2 pallets or motorbikes, a temple, collapsible bridge, movable statue, buildable Venus flytrap and a 4x4 truck with winch. Includes 7 minifigures, plus tiger, crocodile and 2 spider figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60163, 'Coast Guard Starter Set', 76, 'Rescue the surfer and be a coast guard hero!', 'Join the crew of the LEGO® City coast guard as they protect the beach with the Coast Guard Starter Set, featuring a beach tower with stairs and viewing platform, beach buggy with opening roll cage, room for 2 minifigures and space for the 2-minifigure surfboard on the roof, binoculars, 2 walkie-talkies and a small surfboard. Includes 3 minifigures and a shark figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60164, 'Sea Rescue Plane', 141, 'Fly in and save the stranded sailor before he floats away!', 'Be part of the brave crew of the LEGO® City coast guard in the Sea Rescue Plane, featuring spinning propellers, an opening cockpit, lowering back ramp and space for the included rescue water scooter, plus a rescue raft and rescue light. Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60165, '4 x 4 Response Unit', 347, 'Race to the rescue on land and sea!', 'Join the rough and ready crew of the LEGO® City coast guard and their 4x4 Response Unit, featuring a 4x4 truck with opening minifigure cab, opening rear compartment with space for tools and gear, and a detachable trailer for the included rescue craft with room for 2 minifigures, drop-down engines and spinning propellers, radio antennas, toolbox and life preservers. There’s also a diver’s dinghy with dive gear, engine and fire elements. Includes 3 minifigures, plus an octopus figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60166, 'Heavy-duty Rescue Helicopter', 415, 'Perform a daring helicopter rescue before the shark gets too close!', 'Be a part of the fearless LEGO® City coast guard crew on the Heavy-duty Rescue Helicopter, featuring sliding doors on the sides, opening ramp in the back with space for the included water scooter, 2-minifigure cockpit and a rotating crane arm with lowering winch. This fun set also includes a lighthouse, shipwreck and a kayak with paddle, plus 4 minifigures and a shark figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60167, 'Coast Guard Head Quarters', 792, 'Sail the high seas and make a thrilling rescue!', 'Strap on your life vest as part of the LEGO® City crew at the Coast Guard Headquarters with 2 levels, office rooms and a moving radar dish. There’s also a ship with opening bridge and deck, moving radar dish and searchlight, medical area and a rescue craft with launch function, as well as a helicopter with helipad, speedboat and a buildable buoy. Includes 7 minifigures, plus shark and octopus figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60168, 'Sailboat Rescue', 195, 'Rescue the sailor off the rocks just in time!', 'Join the LEGO® City coast guard crew and make an exciting sailboat rescue, featuring a rescue craft with drop-down motors and spinning propellers, a sailboat with working rudder and mast that ‘breaks’, plus a rock island build. Includes 2 minifigures and a shark figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60169, 'Cargo Terminal', 740, 'Load up the truck and deliver the goods!', 'Join the crew keeping the citizens of LEGO® City supplied with goods from the Cargo Terminal, featuring a truck with trailer, forklift with moving blades, telehandler with an opening cockpit and telescopic arm, gatehouse with raising barrier and sliding window, and a pallet storage rack plus 4 pallets of items, including a lawnmower and water scooter, and other fun accessories. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60170, 'Off-Road Chase', 37, 'Catch the crook before he escapes with the loot!', 'Pick up your badge and join the LEGO® City Mountain Police officer on an Off-Road Chase to help stop the crook! This fun building toy set features a crook’s hideout with space for loot and greenery and a police motocross bike with off-road tires and kickstand. Includes 2 minifigures and a snake figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60171, 'Mountain Fugitives', 88, 'Arrest the crooks and recover the hidden loot!', 'Pick up your badge and join the LEGO® City Mountain Police officers to chase down the Mountain Fugitives! This exciting construction toy set features a tree hideout with space for loot, moving greenery and a beehive, plus a police ATV with off-road tires, bubble light, radio and chain. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60172, 'Dirt Road Pursuit', 297, 'Race after the crook and avoid the mountain rockslide!', 'Pick up your badge and join the LEGO® City Mountain Police officers on the Dirt Road Pursuit! This thrilling and fun toy set features a police 4x4 with minifigure cab and net shooter, police motocross bike, crook’s 4x4 with loot space in the back and a rockslide element with boulder release function. Includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60173, 'Mountain Arrest', 303, 'Fly in and surprise the crooks at their hideout!', 'Pick up your badge and join the LEGO® City Mountain Police officers as they make a Mountain Arrest! This amazing children\'s toy set features a 2-level hideout with opening door, bathtub, beehive and post with crane and chain, a police helicopter with opening cab, double spinning rotors, opening door on the back, net shooter, winch with string and hook, plus a crook\'s escape buggy with space for loot. Includes 4 minifigures and a bear figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60174, 'Mountain Police Headquarters', 663, 'Stop the crooks from breaking their partner out of jail!', 'Pick up your badge and make an arresting visit to the LEGO® City Mountain Police Headquarters! This exciting set features a 2-level police headquarters with a net shooter on the roof, jail cell with breakout wall/door and a cave under the jail cell with a mountain lion pounce function. This cool toy for kids also includes a helipad with ladder, police helicopter with spinning rotors, crook helicopter with spinning rotors and chain with hook, police 4x4 and motocross bike. Includes 7 minifigures and a mountain lion figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60175, 'Mountain River Heist', 387, 'Keep the crooks from escaping with the gold bars!', 'Pick up your badge and join the LEGO® City Mountain Police officers as they investigate the Mountain River Heist! This entertaining toy for boys and girls features a police seaplane with spinning propeller, opening minifigure cockpit and aimable net shooter, armored truck with space for a pallet, a small amphibious vehicle with chain and hook, plus a falling tree with beehive. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60176, 'Wild River Escape', 126, 'Speed after the crook on an exciting river chase!', 'Pick up your badge and join the LEGO® City Mountain Police officers as they stop a Wild River Escape! This popular kids toy features a police speedboat with big outboard engine and bubble lights, a raft with big pontoons, a paddle and space for an opening box. Includes 2 minifigures and a skunk figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60177, 'Airshow Jet', 87, 'Wow the crowds in the sleek Airshow Jet!', 'Get ready to put on an amazing show with the LEGO® City Airshow Jet, featuring an opening cockpit, cool decorations and landing gear. This fun building toy includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60178, 'Speed Record Car', 78, 'Climb in the cockpit and set a new speed record!', 'Take the wheel and wait for the green light with the powerful LEGO® City Speed Record Car! This fast vehicle construction toy features an opening cockpit, iconic flame elements and a large rear wing. Includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60179, 'Ambulance Helicopter', 190, 'Transport the mountain snowboarder to the hospital!', 'Join the LEGO® City rescue team and fly the Ambulance Helicopter! This fun toy features spinning rotors, hatch on the back, landing gear and room for a stretcher inside, plus snowboard and radio elements, and 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60180, 'Monster Truck', 192, 'Jump the fire and give the crowd a thrilling show!', 'Become a legend and do the most gravity-defying stunts in the LEGO® City Monster Truck set, featuring a colorful monster truck with massive wheels, air scoop and working suspension, plus a buildable ramp and 2 fire containers with flame elements. This cool children\'s toy includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60181, 'Forest Tractor', 174, 'Load the freshly cut logs with the awesome Forest Tractor!', 'Work in nature with the LEGO® City Forest Tractor, featuring a moving arm with opening claw and massive wheels, plus a small log stand, 2 chains, 2 buildable logs, small pine tree, chainsaw and a shovel. This cool toy for kids includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60182, 'Pickup & Caravan', 344, 'Load up the Pickup & Caravan, it’s time for a vacation!', 'Head out into nature with the family in the LEGO® City Pickup & Caravan, featuring a big caravan with opening side, door, removable front roof to access the bedroom, removable furniture and a separate support leg to stand alone, plus a pickup truck with removable cab roof and bed with caravan hitch. This fun toy for boys and girls includes 3 minifigures and a crab figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60183, 'Heavy Cargo Transport', 310, 'Haul in the helicopter to handle the heavy lifting!', 'Head to the worksite outside the city limits with the LEGO® City Heavy Cargo Transport, featuring a heavy truck with opening cab, toolbox and bull bars, a detachable extended trailer, plus a helicopter with spinning rotors, opening cockpit and a chain. This popular kids toy includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60184, 'Mining Team', 82, 'Blow up the rock pile and discover gold!', 'Grab your hard hat and head out with the LEGO® City Mining Team to dig for gold! This fun building toy features a rock pile with space for golden nugget elements and breakaway elements, as well as a dumper with tipping bed and space for a minifigure, and a research station. Includes 4 minifigures and a glow-in-the-dark spider figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60185, 'Mining Power Splitter', 127, 'Break up the rocks and discover the treasure inside!', 'Grab your hard hat and head out with the LEGO® City Mining Power Splitter to dig for gold! This fun construction toy features a power splitter with functioning jackhammer, raising arm and rotating cab, as well as a rock pile with breakaway elements and space for a golden nugget element. Includes a minifigure and a glow-in-the-dark spider figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60186, 'Mining Heavy Driller', 294, 'Drive in the heavy driller and start digging the cave!', 'Grab your hard hat and head out with the LEGO® City Mining Heavy Driller to make new discoveries! This fun toy features a functioning heavy driller with minifigure cab, shovel loader with tipping bed, plus a mine cave with breakaway golden nugget elements and a mobile lab. Includes 3 minifigures and a glow-in-the-dark spider figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (60188, 'Mining Experts Site', 883, 'Head to the LEGO® City mine and dig up some gold!', 'Grab your hard hat and head out to the LEGO® City Mining Experts Site to make new discoveries! This thrilling children\'s toy features a large grinder/crusher with minifigure cab and raising arm, a front loader with raising shovel and a dump truck with tilting bed. It also includes a large mine system with golden nugget elements, explode function, hidden golden nugget element and a chute and track system with rotating chute and 2 mine carts, plus a mobile lab. Includes 6 minifigures plus bear and glow-in-the-dark spider figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70313, 'Moltor’s Lava Smasher', 187, 'Smash Aaron Fox out of the way and capture the Book of Chaos!', 'The monstrous—but comical—Lava Smasher is racing against NEXO KNIGHT Aaron Fox to retrieve the Book of Chaos. Show off daring aerial moves on Aaron Fox\'s hovershield, dart the knight in and out of the movable rock fists and dodge the catapult\'s rocks. There are plenty of thrilling scenarios to play out in this action-packed play set. Includes 2 minifigures: Moltor and Aaron Fox.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70317, 'The Fortrex', 1140, 'Roll into action with the NEXO KNIGHTS™ 2-in-1 battle castle!', 'Fold out the 2-in-1 Fortrex\'s walls to switch into the detailed headquarters play set, featuring a round table, training area, prison, kitchen and more. Includes 7 minifigures: Clay Moorington, Aaron Fox, Axl, Chef Eclair, Ash Attacker and 2 Scurriers.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70321, 'General Magmar\'s Siege Machine of Doom', 516, 'Tower over the enemy with the monstrous Siege Machine of Doom!', 'Lift the back of General Magmar\'s 2-in-1 Siege Machine of Doom, featuring 2 platforms and giant wheels with spikes, to switch the vehicle into siege mode. Fire the dual catapults and disc shooter to knock Clay Moorington off his Hover Horse. Use the swords to play out battles on the ground as General Magmar and Flama take on Clay with his Claymore sword for the Book of Destruction. Comes with 3 scannable shields and 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70322, 'Axl\'s Tower Carrier', 670, 'Protect the spell book from Burnzie in Axl\'s Tower Carrier!', 'Stage a battle between the highly posable Burnzie and Axl\'s Tower Carrier. Rotate the turret to target Burnzie and fire the dual spring-loaded shooters and disc shooter, then detach the turret to fold out the Tower Carrier\'s catapult, and access the storage vault with the Book of Fear and the Axl Bot in the control room. Also includes 4 scannable shields and 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70336, 'Ultimate Axl', 69, 'Knock out enemies with Ultimate Axl\'s gigantic fists!', 'Ultimate LEGO® NEXO KNIGHTS™ sets are futuristic action minifigures with ultimate battle gear. Twist the ultra armor function on Ultimate Axl\'s back to move his gigantic fists, or attack with the magnetizer club. Then twirl enemies away with the spinning top with blades, or heroically jump into battle with an axe. This set features 3 scannable shields for NEXO Powers that provide unique battle skills in the digital game, and includes an Ultimate Axl minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70337, 'Ultimate Lance', 75, 'Soar into battle with Ultimate Lance and his jet wings!', 'Ultimate LEGO® NEXO KNIGHTS™ sets are futuristic action minifigures with epic battle gear. Take hold of the jousting lance and attach the jet boosters to Ultimate Lance\'s wings to play out flying battle scenes. This set features 3 scannable shields for NEXO Powers that provide unique battle skills in the digital game, and includes an Ultimate Lance minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70338, 'Ultimate General Magmar', 64, 'Fire up Ultimate General Magmar to defeat the opponents!', 'Ultimate LEGO® NEXO KNIGHTS™ sets feature awesome minifigures with futuristic battle gear. Attach the fists for extra battle power, or insert the circular saw blades or whirlwind blades into the ultra armor and turn the handle to make them rotate. This set features 3 scannable shields for NEXO Powers that provide unique battle skills in the digital game, and includes an Ultimate General Magmar minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70339, 'Ultimate Flama', 67, 'Hammer the enemy into defeat with Ultimate Flama!', 'Ultimate LEGO® NEXO KNIGHTS™ sets feature awesome action minifigures with epic battle gear. Turn the wheel to swing the gigantic hammer up and down, then use the slime cannon stud shooter and spinning ice disc in battle against the knights. This set features 3 scannable shields for NEXO Powers that provide unique battle skills in the digital game, and includes an Ultimate Flama minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70347, 'King\'s Guard Artillery', 98, 'Stop the Stone stomper with the King’s Guard battle vehicle!', 'Protect the kingdom of Knighton with the King’s Guard Artillery battle vehicle, featuring a LEGO® NEXO KNIGHTS™ minifigure cockpit, six-stud shooter and rear-wheel-activated extending swords at the front. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70348, 'Lance\'s Twin Jouster', 216, 'Hunt the Rogul with Lance’s four-in-one Twin Jouster!', 'Protect Knighton from the Stone monster with the 4-in-1 Twin Jouster, featuring flip-out wings with four flick missiles, two minifigure cockpits, dual lances, detachable Wing Jet Pack and the Jouster Bike. Includes three minifigures and one scannable shield.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70349, 'Ruina\'s Lock & Roller', 208, 'Rescue the queen from Ruina’s Lock & Roller!', 'Help Aaron rescue the queen from the wicked Ruina and her Lock & Roller, featuring translucent-blue claws and a minifigure cockpit, plus a detachable rear prison carriage and Forbidden Power pole to activate the opening door function. Includes two scannable shields and three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70350, 'The Three Brothers', 266, 'Charge Axl into battle against the three fearsome brothers!', 'Play out endless LEGO® NEXO KNIGHTS™ battle scenes as Axl takes on the three ancient Stone monsters to stop them terrorizing Knighton, featuring a rolling monster vehicle with a giant face and chomping jaws, and a rear firing catapult. Includes two scannable shields and three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70352, 'Jestro\'s Headquarters', 840, 'Help the heroic knights rescue Ava from Jestro’s head-shaped HQ!', 'Stage a daring rescue mission and release Ava from Jestro’s Headquarters, featuring a giant face with hidden weapons, detachable Hatattacka with flick missiles, Mobile Stone Keep trailer with adjustable crane and cage with movable bars, and an ejecting Stone boat function. This feature-packed LEGO® NEXO KNIGHTS™ set also comes with Macy’s Underminer vehicle featuring a spinning drill, plus a Stone Wheeler vehicle with cannons to ramp up the rescue mission action. Includes five scannable shields and six minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70354, 'Axl\'s Rumble Maker', 393, 'Keep trouble at bay with Axl’s 3-in-1 Rumble Maker!', 'Drive the Rogul out of Knighton with the 3-in-1 Rumble Maker, featuring dual rotating drill weapons, flip-out wings, detachable tank with caterpillar tracks, axe holder, 2 minifigure cockpits and 2 stud shooters. Includes 3 minifigures and 3 scannable shields.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70355, 'Aaron\'s Rock Climber', 598, 'Run rings around the Krakenbeast with Aaron’s 3-in-1 Rock Climber!', 'Summon your courage for a beastly LEGO® NEXO KNIGHTS™ encounter and drive the futuristic 3-in-1 Rock Climber with detachable crossbow and mini-flyer after Lord Krakenskull on the buildable Krakenbeast monster with posable limbs and tail weapon. Includes 3 scannable shields, 3 minifigures, buildable Krakenbeast, plus Bouldron and Brickster figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70357, 'Knighton Castle', 1426, 'Stand your ground and save the realm with the 2-in-1 Knighton Castle!', 'Explore the awesome 2-in-1 Knighton Castle and defend the king! Unclasp the main gates and fold out the walls to roll out Robin’s vehicle with 2 stud shooters and Merlok 2.0 in his Mechlok robotic suit with wizard’s hat. Engage the enemy and avoid capture in the rolling stone prison. This feature-packed LEGO® NEXO KNIGHTS™ play set also features a tower formed by the detachable Rumble Rocket transporter, living quarters with 2 bedrooms, dining room, armory and a command center for endless hours of siege role-play fun. Includes 6 scannable shields and 8 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70358, 'Aaron\'s Stone Destroyer', 251, 'Protect Robot Hoodlum from The Bedrock Monster!', 'Rescue Robot Hoodlum from the buildable Bedrock Monster, featuring Aaron’s Stone Destroyer motorcycle with dual flick missiles and spinning stone slicers, and a forest hideout scene with buildable tree, branch elements and a catapult. Incudes two scannable shields and two minifigures, plus a buildable Bedrock Monster figure..
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70359, 'Lance vs. lightning', 257, 'Charge Lance into battle against the gargoyles!', 'Ride Lance into the village of Ghoulia and battle Grimroc the giant gargoyle! Prepare the buildable robot horse for some jousting action, and charge against the buildable Grimroc figure with its lightning tridents. The gothic village scene has lightning strike elements, a cobweb and a catapult that can fire lightning ball elements at Lance. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70361, 'Macy\'s Bot Drop Dragon', 153, 'Engage the Stone stomper with Macy’s Bot Drop Dragon!', 'Pit the flying Stone stomper against Macy and the buildable Bot Drop Dragon, featuring 2 wings with mounted stud shooters, minifigure cockpit, movable tail and Macy Bot release function. The Stone stomper’s shield can be used as a hoverboard to role-play an aerial dog fight scene. Includes one scannable shield and 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70362, 'Battle Suit Clay', 79, 'Suit up with Clay and turn the Stone monsters to dust!', 'Upgrade your fighting skills with the LEGO® NEXO KNIGHTS™ Battle Suit Clay play set, featuring a buildable battle suit with posable limbs, minifigure cockpit, super-sized sword, giant fist and a Combo NEXO Power shield. Includes five scannable shields for NEXO Powers that provide unique battle skills in the digital game, plus a new-for-spring-2017 Clay minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70363, 'Battle Suit Macy', 66, 'Unleash mighty Macy and send the Stone monsters running!', 'Turn Macy into the toughest knight in the realm with this LEGO® NEXO KNIGHTS™ Battle Suit play set, featuring a buildable battle suit with posable limbs, minifigure cockpit, super-sized mace, giant fist and a Combo NEXO Power shield. Includes five scannable shields for NEXO Powers that provide unique battle skills in the digital game and a new-for-spring-2017 Macy minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70364, 'Battle Suit Aaron', 80, 'Grab a battle suit and help Aaron defend Knighton!', 'Become a bigger hero with the LEGO® NEXO KNIGHTS™ Battle Suit Aaron play set, featuring a buildable battle suit with posable limbs, minifigure cockpit, Blazer Bow with spring-loaded shooters, giant fist and a Combo NEXO POWER shield. Includes five scannable shields for NEXO POWERS that provide unique battle skills in the digital game and a new-for-spring-2017 Aaron minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70365, 'Battle Suit Axl', 88, 'Watch Axl become unstoppable on the battlefield!', 'Give Axl a mechanized advantage with the LEGO® NEXO KNIGHTS™ Battle Suit Axl play set, featuring a buildable battle suit with posable limbs, minifigure cockpit, super-sized buildable axe, giant fist and a Combo NEXO POWER shield. Includes five scannable shields for NEXO Powers that provide unique battle skills in the digital game and a new-for-spring-2017 Axl minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70366, 'Battle Suit Lance', 83, 'Send Lance speeding after the Stone monsters!', 'Race ahead of the rest of the knights with the LEGO® NEXO KNIGHTS™ Battle Suit Lance play set, featuring a buildable battle suit with rolling feet, posable limbs, minifigure cockpit, super-sized lance, giant fist and a Combo NEXO Power shield. Includes five scannable shields for NEXO Powers that provide unique battle skills in the digital game and a new-for-spring-2017 Lance minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70372, 'Combo NEXO Powers Wave 1', 10, 'Collect and combine the NEXO Powers to defeat Monstrox!', 'Open the bag to reveal the five ‘mystery’ NEXO Powers, then create your own way of defeating the enemy by combining three NEXO Powers into one. Place the NEXO Powers in the included Combo NEXO Power shield, then scan into the free LEGO® NEXO KNIGHTS™ MERLOK 2.0 app and bring your creation to life in the digital game.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70592, 'Salvage M.E.C.', 439, 'Match the Salvage M.E.C. vs. the Skulkin mech in a bounty-hunting duel!', 'Stage a mech battle between bounty-hunting Ronin—assisted by Nya—against Skulkin warriors. Ronin\'s highly posable mech features a golden bow with a spring-loaded shooter, a net-stud shooter, a rifle, and a compartment to store stolen treasure or ammunition. The posable Skulkin mech is wielding 2 silver dark blades and there are loads of other minifigure weapons, including Krazi\'s Double-Bladed Skulkin Axe, to dial up the conflict. Detach the skateboard or flyer from Ronin\'s Salvage M.E.C. to help him escape. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70601, 'Sky Shark', 221, 'Take on Flintlocke’s Sky Shark with Ninja Lloyd!', 'Zoom into battle against Flintlocke\'s Sky Shark with Lloyd using the convertible drone/jetpack. The Sky Shark jet features a dynamite-dropping function, fold-out blades, 6 detachable guns and a hidden sword, plus lots of pirate details. Defeat the sky pirate and then free the ‘trapped Kai\' element from the special Djinn blade. Includes 2 minifigures: Lloyd and Flintlocke.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70603, 'Raid Zeppelin', 294, 'Fly high with Zane to battle Doubloon’s mighty Raid Zeppelin!', 'Stage an aerial conflict between Doubloon\'s Raid Zeppelin airship and Zane\'s flyer. The Zeppelin is armed with a firing front cannon, 2 stud shooters and has a trapdoor function to drop barrels of dynamite (and captured Ninja warriors!). Retaliate by firing the flyer\'s elemental ice stud shooters and battle for the special Djinn Blade with ‘trapped Jay\' element. Includes 3 minifigures: Zane, Doubloon and Clancee.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70605, 'Misfortune’s Keep', 754, 'Launch a surprise attack on the sky pirates’ awesome HQ!', 'Stage a sky pirates vs. Ninja battle with Misfortune\'s Keep, featuring rotating engines for launch and flight modes, fold-out cannons and disc shooters, plus a pirate jet and launchpad. Ninja Lloyd has a booster jet featuring a winch to lower Jay into battle for the golden Djinn Blade with ‘trapped Wu\' element. Includes 6 minifigures: Jay, Lloyd, Kai, Bucko, Nadakhan and Flintlocke, plus Monkey Wretch.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70606, 'Spinjitzu Training', 109, 'Practice your Spinjitzu skills with Kai and Zane!', 'Join the ninja heroes at the dojo with this action-packed THE LEGO® NINJAGO® MOVIE™ Spinjitzu Training set, featuring a dojo wall with a scroll and 2 detachable staffs, weapon rack with 2 detachable katanas, combat training station, Garmadon combat dummy, plus 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70607, 'NINJAGO® City Chase', 233, 'Stop a crime in the NINJAGO® City street market!', 'Team up with Lloyd Garmadon, Nya and Officer Toque to prevent Shark Army Thug robbing a street food stall vendor in NINJAGO® City Chase. This exciting THE LEGO® NINJAGO MOVIE™ set features a 3-wheel police tuc-tuc vehicle, street food stall with assorted food elements, plus 2 lampposts with a connecting chain of festive NINJAGO lanterns. The set also includes 5 minifigures with various weapons and accessories to add to the fun role-play possibilities.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70608, 'Master Falls', 312, 'Battle against evil Jungle Garmadon on the jungle bridge!', 'Team up with Wu and Kai to take on Jungle Garmadon in this awesome THE LEGO® NINJAGO® MOVIE™ Master Falls set. The jungle bridge features an opening cage and a hidden cave with a skeleton inside holding a secret map. Also includes 3 minifigures with assorted weapons—including Wu’s staff and 4-armed Jungle Garmadon’s 4 swords—to bolster the role-play action.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70609, 'Manta Ray Bomber', 341, 'Protect NINJAGO® City from flying Manta Ray Bomber attack!', 'Help Cole save Shen-Li in this cool THE LEGO® NINJAGO® MOVIE™ set, featuring the Manta Ray Bomber with 2 spring-loaded shooters, 2 bomb elements and a detachable boat. Includes 4 minifigures with assorted weapons and accessories to ramp up the role-play action possibilities.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70610, 'Flying Jelly Sub', 341, 'Take on the tentacular Flying Jelly Sub with Jay!', 'Join ninja Jay in battle against the shark army and protect Takuma’s boat from Flying Jelly Sub attacks, in this action-packed THE LEGO® NINJAGO® MOVIE™ set. The sub features an opening minifigure cockpit, rotating legs, 2 flick missiles and swinging ‘toxic’ tentacles. Also includes a boat, plus 4 minifigures with assorted weapons to add to the battle role-play options.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70611, 'Water Strider', 494, 'Smash the shark army out of the water with the Water Strider!', 'Launch into battle against the shark army and pretend to walk on water and climb walls with this awesome THE LEGO® NINJAGO® MOVIE™ mech. The Water Strider features a 360-degree rotating minifigure cockpit, 6-stud rapid shooter and 4 posable legs and feet to create powerful battle poses. The set also includes 4 minifigures with assorted weapons to add to the ninja vs. shark army role-play battle options.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70612, 'Green Ninja Mech Dragon', 544, 'Take on Garmadon with the Green Ninja Mech Dragon!', 'Outwit The Green Ninja’s evil father Garmadon with this mighty THE LEGO® NINJAGO® MOVIE™ mech. The Green Ninja Mech Dragon features articulated snapping jaws, a fully posable body, wheel-activated swooshing tail, 2 leg-mounted stud shooters and 2 hidden pop-out thrusters. This set includes 4 minifigures with assorted weapons—including The Green Ninja’s sword and Garmadon’s laser-style pointer—to offer even more role-play battle possibilities.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70613, 'Garma Mecha Man', 747, 'Defend NINJAGO® City against Garma Mecha Man!', 'Help Lloyd protect civilian Pat from attack by Garma Mecha Man with this awesome THE LEGO® NINJAGO® MOVIE™ set. This huge and highly posable mech features an opening minifigure cockpit for Garmadon, spring-loaded shark blaster, ammo belt and a fish tank. Includes 4 minifigures with assorted weapons—including Garmadon’s laser-style pointer and Lloyd’s tasseled sword—to bolster the battle role-play possibilities.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70614, 'Lightning Jet', 876, 'Speed to the rescue with Jay’s Lightning Jet!', 'Save Ed and Edna from the shark army’s crab with Jay’s Lightning Jet in this thrilling THE LEGO® NINJAGO® MOVIE™ set. The jet has a handle for easy pick-up-and-play and maximum swooshability, plus an opening minifigure cockpit, spring-loaded shooter and trigger-activated rotating electro-disc. The crab features posable legs, a snapping pincer and 6-stud rapid shooter, and the set also includes 6 minifigures with assorted weapons to dial up the role-play conflict.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70615, 'Fire Mech', 944, 'Put the heat on the shark army with Kai’s Fire Mech!', 'Get set for sizzling battle action with this huge and highly posable THE LEGO® NINJAGO® MOVIE™ mech. The Fire Mech features an opening minifigure cockpit, 2 shoulder disc shooters and 2 arms with non-shooting fire blasters. Includes 6 minifigures with assorted weapons—including Kai’s katanas and Zane’s bow and arrow—to offer even more thrilling role-play possibilities.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70616, 'Ice Tank', 914, 'Take on the shark army with Zane’s Ice Tank!', 'Help Zane save Patty Keys and Torben from the shark soldiers with this action-packed THE LEGO® NINJAGO® MOVIE™ Ice Tank set. This cool vehicle features an opening minifigure cockpit, big tracks, ice cannon with 6-stud rapid shooter, and a rotating ice container. The set also includes 5 minifigures with assorted weapons—including Zane’s bow and arrow and Shark Army Thug’s fish spike dagger—to add to the exciting role-play possibilities.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70617, 'Temple of The Ultimate Ultimate Weapon', 1403, 'Evade the traps inside the Temple!', 'Join a ninja mission to infiltrate THE LEGO® NINJAGO® MOVIE™ Temple of The Ultimate Ultimate Weapon. The temple features a secret entrance, trapdoor function, rock-dropping and dynamite-dropping functions, blade-shooting and chopping-sword traps, dungeon, a hanging cage to capture a minifigure inside, and a pull-out section with poles for minifigures to leap between to reach the treasure chest. This set includes 7 minifigures with assorted weapons and 2 buildable temple guardian figures for endless action role-play fun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70618, 'Destiny\'s Bounty', 2295, 'Join the ninja aboard Wu’s flying ship!', 'Construct Wu’s huge ninja training base, Destiny’s Bounty. This highly detailed THE LEGO® NINJAGO® MOVIE™ model consists of 3 modular levels and features a double-headed dragon figurehead, decorated sails, wind-up-and-release anchors, dojo area for ninja training, a bathroom and Wu’s bedroom in the hull. This amazing model also includes hidden weapons including the ultimate weapon— the laser-style pointer, plus 7 minifigures with assorted weapons to bolster the exciting role-play possibilities.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70620, 'NINJAGO® City', 4867, 'Live the life of a ninja in NINJAGO® City!', 'Enjoy endless role-play fun in NINJAGO® City, a hugely-detailed 3-level model connected by a sliding elevator. Level 1 features a traditional fish market, house, a bridge over a stream, and a fishing boat. The second level has a modern fashion store, comic book store, crab restaurant with ‘crab-grilling’ function and cash-dispensing ATM. The vertical city is topped off with Lloyd Garmadon and Misako’s apartment, a rooftop sushi bar with sushi conveyor belt, and a radio tower. This action-packed THE LEGO® NINJAGO MOVIE™ set also includes 16 minifigures and Sweep the maintenance robot.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70621, 'The Vermillion Attack', 83, 'Battle the Vermillion to win the Fast Forward Time Blade!', 'Stage a swamp battle between Kai and Vermillion warriors Rivett and Slackjaw to win the Forward Time Blade. This LEGO® NINJAGO® set features a Vermillion egg with an explode function that releases three red snake elements from inside, plus cool minifigure weapons to dial up the role-play conflict. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70623, 'Destiny\'s Shadow', 360, 'Glide across and above the swamp with Destiny\'s Shadow!', 'Fight the Vermillion for control of the Pause Time Blade with Lloyd and Cole aboard Destiny’s Shadow. This convertible boat/flyer features flip-out wings for flight mode, two stud shooters, plus two detachable canoes and two oars. Dial up the ninja vs. Vermillion conflict with Vermin’s V-shaped hoverboard and Vermillion axe. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70624, 'Vermillion Invader', 313, 'Watch out for the mighty egg-launching Vermillion Invader!', 'Help Zane escape with the Forward Time Blade under attack from Commander Raggmunk and Slackjaw’s Vermillion Invader. The Invader has two minifigure cockpits, a rubber track and a spring-loaded dual egg catapult to knock down the included barrier—and any minifigure trying to hide behind it. Commander Raggmunk and Slackjaw are armed with Vermillion swords and an axe and Zane has a katana to add to the role-play battle action. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70628, 'Lloyd - Spinjitzu Master', 48, 'Achieve Spinjitzu greatness with the Green Ninja!', 'Learn all the skills of Spinjitzu with THE LEGO® NINJAGO® MOVIE™ Lloyd – Spinjitzu Master set, featuring a Spinjitzu spinner with buildable LEGO brick handle, spinner element with minifigure capsule and a rip cord. Learn different minifigure-spinning, rolling and jumping techniques and even tougher skills using the included weapon rack as an obstacle. Compete against your friends and use your environment to create countless fun Spinjitzu challenges. Includes a Lloyd minifigure with 2 shurikens to hold in the spinner.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70629, 'Piranha Attack', 217, 'Stop a Piranha Attack with Kai and Misako!', 'Play out an action-packed Piranha Mech pursuit of a rickshaw through NINJAGO® City with THE LEGO® NINJAGO MOVIE™ Piranha Attack set. The Piranha Mech features opening jaws with a minifigure cockpit inside, plus 2 flick missiles. This fun toy also includes 4 minifigures with assorted weapons to dial up the chase action.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70631, 'Garmadon\'s Volcano Lair', 521, 'Get all fired up at Garmadon’s Volcano Lair!', 'Join Zane’s mission to infiltrate evil Garmadon’s Volcano Lair and take on the shark army, with this exciting THE LEGO® NINJAGO® MOVIE™ set. The base includes a minifigure-launch function at the tip of the volcano, Garmadon’s throne room, computer lab with a mini piranha mech prototype, construction zone with an exploding wall function and rotating crane to lift the included shark figure, plus a drone launch pad. This building toy also includes 5 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70632, 'Quake Mech', 1202, 'Turn sound into a weapon with Cole’s Quake Mech!', 'Fire ‘soundwaves’ from Cole’s Quake Mech to save TV reporter Fred Finley from the shark army, with this all-action THE LEGO® NINJAGO® MOVIE™ set. The highly posable, uni-wheel Quake Mech features an opening minifigure cockpit, fold-up shoulder ‘loudspeakers\' with 8 hidden ‘soundwave\'-shooting flick missiles, fully posable arms with gripping fists and a big wheel with stabilizer. This cool toy for kids also includes 5 minifigures with assorted weapons to intensify the role-play battles.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70633, 'Kai - Spinjitzu Master', 61, 'Master Spinjitzu with the Red Ninja!', 'Take your Spinjitzu skills to the next level with the LEGO® NINJAGO® Kai – Spinjitzu Master set, featuring a Spinjitzu spinner with buildable LEGO brick handle, spinner element with minifigure capsule, and a rip cord. Learn different minifigure-spinning, rolling and jumping techniques and tougher skills using the included weapon rack as an obstacle. Compete against your friends and use your environment to create countless fun Spinjitzu challenges. This fun toy includes a Kai minifigure with 2 shurikens to hold in the spinner.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70634, 'Nya - Spinjitzu Master', 69, 'Build, rip and spin into action with Nya!', 'Be ninja and learn new Spinjitzu tricks with the LEGO® NINJAGO® Nya – Spinjitzu Master set, featuring a Spinjitzu spinner with buildable LEGO brick handle, spinner element with minifigure capsule, and a rip cord. Learn different minifigure-spinning, rolling and jumping techniques and tougher skills using the included weapon rack as an obstacle. Compete against your friends and use your environment to create countless fun Spinjitzu challenges. This cool toy for kids includes a Nya minifigure with 2 shurikens to hold in the spinner.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70635, 'Jay - Spinjitzu Master', 68, 'Create brilliant Spinjitzu tricks with the Blue Ninja!', 'Test your Spinjitzu skills to the max with the LEGO® NINJAGO® Jay – Spinjitzu Master set, featuring a Spinjitzu spinner with buildable LEGO brick handle, spinner element with minifigure capsule, and a rip cord. Learn different minifigure-spinning, rolling and jumping techniques and tougher skills using the included weapon rack as an obstacle. Compete against your friends and use your environment to create countless fun Spinjitzu challenges. This fun toy includes a Jay minifigure with 2 shurikens to hold in the spinner.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70636, 'Zane - Spinjitzu Master', 69, 'Create the coolest Spinjitzu tricks with the Ice Ninja!', 'Build, rip and spin into action with the LEGO® NINJAGO® Zane – Spinjitzu Master set, featuring a Spinjitzu spinner with buildable LEGO brick handle, spinner element with minifigure capsule, and a rip cord. Learn different minifigure-spinning, rolling and jumping techniques and tougher skills using the included weapon rack as an obstacle. Compete against your friends and use your environment to create countless fun Spinjitzu challenges. This cool toy for kids includes a Zane minifigure with 2 shurikens to hold in the spinner.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70637, 'Cole - Spinjitzu Master', 73, 'Master the art of Spinjitzu with the Black Ninja!', 'Spin to the max with the LEGO® NINJAGO® Cole – Spinjitzu Master set, featuring a Spinjitzu spinner with buildable LEGO brick handle, spinner element with minifigure capsule, and a rip cord. Learn different minifigure-spinning, rolling and jumping techniques and tougher skills using the included weapon rack as an obstacle. Compete against your friends and use your environment to create countless fun Spinjitzu challenges. This fun toy includes a Cole minifigure with 2 shurikens to hold in the spinner.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70638, 'Katana V11', 257, 'Pursue Luke Cunningham with Kai’s Katana V11!', 'Play out a high-speed chase on water and land with this action-packed LEGO® NINJAGO® set, featuring Kai’s Katana V11 boat, with speed and attack modes, foldout boosters and spring-loaded shooters. This cool toy for kids also includes Luke Cunningham\'s street bike, plus 2 minifigures with weapons to boost the role-play battle action.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70639, 'Street Race of Snake Jaguar', 308, 'Stage a high-speed bike showdown!', 'Match Zane’s bike against Mr. E’s Oni Bike and battle for the Oni Mask of Vengeance, with this exciting LEGO® NINJAGO® Street Race of Snake Jaguar set. Zane’s bike features 2 foldout gold-colored blades, 2 hidden stud shooters on a foldout detachable drone for ground-level or aerial attacks, while the Oni Bike is armed with chopping blades and 2 stud shooters. This cool toy for kids also includes a podium with Oni Mask of Vengeance and Demon Torso elements for the Mr. E minifigure to wear, plus 2 minifigures with weapons to intensify the role-play conflict.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70640, 'S.O.G. Headquarters', 530, 'Attack the Sons of Garmadon underground dojo in Spinjitzu style!', 'Crash into the S.O.G. Headquarters with the Lloyd Spinjitzu spinner and claim the Oni Mask of Hatred, with this action-packed LEGO® NINJAGO® set. The dojo features spinning weapons, movable sides and an Oni Bike to attack the spinner. Unleash the spinner to knock over rivals or the ATM and to smash through the dojo entrance to release the Oni Mask of Hatred element. This building toy also has 5 minifigures, including Zane as his undercover persona, Snake Jaguar.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70641, 'Ninja Nightcrawler', 552, 'Shoot on the go with Lloyd’s Ninja Nightcrawler!', 'Chase down Ultra Violet’s Stone Booster Bike in Lloyd’s Ninja Nightcrawler and battle for the Oni Mask of Hatred, with this all-action LEGO® NINJAGO® set. The Ninja Nightcrawler features an opening minifigure cockpit, speed and attack modes and 2 foldout, shoot-on-the-go, 6-stud rapid shooters. This fun toy also includes 3 minifigures with weapons to intensify the role-play conflict.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70642, 'Killow vs. Samurai X', 556, 'Get weaponized for a dynamic Killow vs. Samurai X duel!', 'Match Killow’s Oni Chopper against the Samurai X Mech in a battle for the Oni Mask of Deception, with this action-packed LEGO® NINJAGO® set. The Oni Chopper features a spinning front saw blade, flip-out blades and detachable skateboards for Killow, while the posable Samurai X Mech has a dual stud shooter, spinning blade and a detachable Samurai X blade. This cool toy for kids also includes 2 minifigures and a big figure with weapons to bolster the role-play battles.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70643, 'Temple of Resurrection', 765, 'Explore the mysterious Temple of Resurrection!', 'Help the ninja protect the Temple of Resurrection and prevent Lord Garmadon’s rebirth with this highly detailed LEGO® NINJAGO® set. The temple features an entrance gangway, opening walls, spider prison, revolving walls with hidden Oni masks and 2 trapdoor functions. Activate the roof\'s good-to-evil transformation function to reveal Lord Garmadon\'s resurrection chamber. This construction toy also includes 7 minifigures—and a ‘mysterious baby\' element—to role-play battle scenes between the ninja and the Sons of Garmadon.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70656, 'garmadon, Garmadon, GARMADON!', 830, 'Defend NINJAGO® City from Garmadon Shark Mech attack!', 'Help Lloyd to save Nomis and Nancy from Garmadon’s Shark Mech with this action-packed THE LEGO® NINJAGO® MOVIE™ garmadon, Garmadon, GARMADON! set. The mech features 2 opening cockpits, LEGO studs to stand the Garmadon minifigure on top of the shark\'s head, trigger-operated snapping jaws, posable legs and 2 shooting cannons. This cool toy for kids also includes a hot dog stand and 6 minifigures with assorted play-starting weapons and accessory elements.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70751, 'Temple of Airjitzu', 2028, 'Join the Ninja at the beautiful Temple of Airjitzu!', 'Enjoy the ultimate LEGO® NINJAGO™ building experience as you construct the majestic Temple of Airjitzu and surrounding village! The highly detailed Temple building has many delightful architectural features including Oriental–style decorated windows and sliding doors. The intricate wooden-frame-style walls of the nearby Blacksmiths and beautiful curved roofs of the Smugglers Market will also test your LEGO building skills. And with every Ninja included in one set for the first time, plus loads of other key characters, you can role-play all your favorite NINJAGO adventures. Take tea in the reception area of the Temple, practice your Ninja moves in the training room or join Wu in his study to read or paint. Discover the Ninja glider upstairs at the Blacksmith’s workshop, cross the bridge guarded by the stone dragons and seek out hidden treasure at the Smugglers’ Market. Then turn off the lights in your room to watch the Temple’s illuminated spinning shadow theater! Includes 12 minifigures with assorted weapons: Lloyd, Kai, Jay, Zane, Cole, Nya, Wu, Misako, Dareth, Postman, Jesper and Claire.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70900, 'The Joker™ Balloon Escape', 124, 'Help Batman™ stop The Joker™ escaping!', 'Stage a face-off between The Joker™ and Batman™ at the Gotham City Energy Facility in THE LEGO® BATMAN MOVIE: The Joker Balloon Escape set, featuring The Joker’s detachable balloon backpack and a power plant build. The power plant has a movable bomb element and silo with explode function, while Batman is armed with a grappling gun to intensify role-play battles. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70901, 'Mr. Freeze™ Ice Attack', 201, 'Protect the power plant from Mr. Freeze’s ice attack!', 'Help Batman™ defend the Gotham City Energy Facility from Mr. Freeze’s Exosuit assault and save the security guard from the ice prison in THE LEGO® BATMAN MOVIE: Mr. Freeze™ Ice Attack set. The set features Mr. Freeze’s posable Exosuit with room for a minifigure and a stud-shooting freeze gun, plus a detailed power plant build and an opening ice prison. Includes three minifigures and assorted play-inspiring weapons and accessory elements including Batman’s flamethrower.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70902, 'Catwoman™ Catcycle Chase', 139, 'Stop Catwoman™ escaping with the diamonds!', 'Help Batgirl™ and Robin™ thwart a jewel heist in THE LEGO® BATMAN MOVIE: Catwoman™ Catcycle Chase set, including the Catcycle and a buildable street scene with a jewelry store. Play-starting features include a lamppost with tipping function to knock over during the getaway pursuit, translucent diamond-style elements, plus Catwoman’s whip and Batgirl’s Batarangs. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70903, 'The Riddler™ Riddle Racer', 254, 'Battle with Batman™ against The Riddler™ and his allies!', 'Take on four Super-Villains at once in THE LEGO® BATMAN MOVIE: The Riddler™ Riddle Racer set, featuring the Riddle Racer vehicle with two hidden flip-up spring-loaded shooters. Team up with Batman™ to defeat The Riddler™, Kite Man™, Magpie™ and Calendar Man™. Also includes Kite Man’s detachable glider pack with posable wings, Batman’s Batarang, Magpie’s dynamite elements and other role-play-inspiring weapons and accessory elements. Includes five minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70904, 'Clayface™ Splat Attack', 448, 'Duel against the mighty Clayface™ with Batman™!', 'Team up with Batman™ to take on Clayface™ and free Mayor McCaskill from the clay prison in THE LEGO® BATMAN MOVIE: Clayface Splat Attack set. The highly posable, buildable Clayface figure features three interchangeable hands—two with a six-stud rapid shooter each and one with a clay hammer—while Batman is armed with a Batarang to dial up the role-play conflict. Includes two minifigures and a brick-built figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70905, 'The Batmobile', 581, 'Pursue Man-Bat™ and the Kabuki Twins™ in the Batmobile with three driving modes!', 'Race through Gotham City in pursuit of Man-Bat™ and the Kabuki Twins™ in the Batmobile. This set from THE LEGO® BATMAN MOVIE features the Batmobile with a dual cockpit for Batman™ and Robin™, two stud shooters and multidirectional wheels for three different modes—race mode, monster truck mode and parallel-parking mode. Man-Bat is equipped with a dynamite element and the Kabuki Twins each have claws to intensify the role-play battle action. Includes five minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70906, 'The Joker™ Notorious Lowrider', 433, 'Team up with Batgirl™ to stop The Joker’s Notorious Lowrider!', 'Join Batgirl’s pursuit of The Joker™ and Harley Quinn™ through the streets of Gotham City in this exciting set from THE LEGO® BATMAN MOVIE. The Joker’s Notorious Lowrider vehicle features bouncing suspension, handles for Harley to hang onto, an opening trunk with hidden double spring-loaded shooters and lots of comical features. Extra accessory elements such as Harley’s roller skates add to the role-play fun. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70907, 'Killer Croc™ Tail-Gator', 460, 'Speed after Killer Croc’s Tail-Gator on Batman’s Batski!', 'Stage a land-water pursuit of Killer Croc’s Tail-Gator at Gotham City harbor with this action-packed set from THE LEGO® BATMAN MOVIE. Help Batman™ prevent Killer Croc™, Zebra-Man™ and Tarantula™ from escaping in Croc’s huge Tail-Gator truck featuring big wheels with rubber tires, suspension and two crate bombs. Give chase on Batman’s Batski with two stud shooters. Includes three minifigures with assorted weapons and a big figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70908, 'The Scuttler', 775, 'Save the day with Batman™ and The Scuttler!', 'Ride The Scuttler with Batman™ to rescue hostages taken by The Joker™ at Commissioner Gordon’s retirement party, with this exciting set from THE LEGO® BATMAN MOVIE. The highly posable Scuttler features a net shooter, six stud shooters, extendable arms, an opening minifigure cockpit and hidden jetpack for Batman. Batman is also equipped with a Batarang to take on The Joker, Poison Ivy™ and her vine monster. Includes six minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70909, 'Batcave Break-in', 1047, 'Protect the Batcave from The Penguin’s invasion!', 'Defend against The Penguin’s Duckmobile invasion of the Batcave in THE LEGO® BATMAN MOVIE: Batcave Break-in set. The highly detailed Batcave features a rotating transformation chamber for Bruce Wayne™ to ‘transform’ into Batman™, rotating Batcomputer control center with multiscreen elements and elevating platform function, and a prison with an exploding escape wall function. The Batcave also has a rotating wardrobe with alternative Scu-Batsuit, Raging Batsuit or the Bat-Pack Batsuit minifigure bodies for Batman. Dial up the conflict by using the Batboat’s spring-loaded missiles against the Duckmobile’s dual stud shooters and flick missiles. Includes four minifigures plus two Hench-Penguin figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70910, 'Scarecrow™ Special Delivery', 204, 'Help Batman™ to stop Scarecrow™ delivering a special scare pizza!', 'Save Gotham City Energy Facility from a fear gas attack with this action-packed THE LEGO® BATMAN MOVIE: Scarecrow™ Special Delivery set, featuring Scarecrow’s pizza delivery bike with cart and a security booth. Pop out the sides of the bike’s cart by turning the sign on the roof to reveal the fear gas canister. Move the security booth’s boom barrier up and down or smash through it with the bike. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70911, 'The Penguin™ Arctic Roller', 305, 'Put the heat on The Penguin™ Arctic Roller with Batman™!', 'Join Batman’s pursuit of The Penguin in THE LEGO® BATMAN MOVIE: The Penguin™ Arctic Roller set. The Arctic Roller vehicle features a minifigure cockpit with removable roof, dual spring-loaded shooter and loads of quirky penguin details. Add an extra dimension to the chase by opening the trunk and placing The Penguin™ on his penguin mini escape pod. Includes two minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70912, 'Arkham Asylum', 1628, 'Break into Arkham Asylum with Batman™!', 'Bust into Arkham Asylum with Batman™ and banish The Joker™ and the other Super-Villains with the Phantom Zone Projector element. This highly detailed set from THE LEGO® BATMAN MOVIE features the massive Arkham Asylum model with many different areas—including Dr. Harleen Quinzel’s office, ward office, four cells, an ‘x-ray’ security scanner, canteen, visitors’ room and laundry room—plus a separate five-story lookout tower, police car and loads of play-inspiring accessories. With 12 minifigures—and plenty of Super-Villain characters among them—also included in the set, the role-play possibilities are endless.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70913, 'Scarecrow™ Fearful Face-off', 141, 'Power into the sky to stop Scarecrow’s fear gas attacks!', 'Team up with Batman™ to stop Scarecrow™ spreading fear in this action-packed THE LEGO® BATMAN MOVIE: Scarecrow™ Fearful Face-off set. The Gyro-Copter features 2 spinning rotors, an adjustable rudder and 2 bomb-drop functions to drop the included fear gas bomb elements. Attach Batman’s jetpack with Batwings and adjustable boosters, and arm him with the grappling gun to role-play an aerial battle. The set also features a power plant mini build with an explode function for added jeopardy, plus 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70914, 'Bane™ Toxic Truck Attack', 366, 'Protect Gotham City from Bane’s toxic attacks!', 'Stop Bane™ and Mutant Leader’s toxic attacks with Batman™ in this exciting THE LEGO® BATMAN MOVIE: Bane™ Toxic Truck Attack set, including Bane’s Toxic Truck, Batman’s Whirly-Bat flyer and a toxic waste mini-build with explode function. The 6-wheel truck features rear 4-wheel suspension and a mounted 6-stud rapid shooter and detachable toxic tank element. Includes 2 minifigures, a big figure and assorted play-inspiring weapons and accessory elements including Batman’s Batarang, Mutant Leader’s torch and Bane’s Venom backpack.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70915, 'Two-Face™ Double Demolition', 564, 'Don’t get on the wrong side of the Two-Face™ Excavator!', 'Stop the mighty Two-Face™ Excavator with Batman’s Batcycle in this thrilling THE LEGO® BATMAN MOVIE: Two-Face™ Double Demolition set. The Two-Face Excavator has a minifigure cabin, operational excavator arm and bucket, articulated design for smooth steering. It might look like a normal digger from one side, but check out the ‘bad side’ featuring spikes on the huge wheels and a 6-stud rapid shooter. The Batcycle features an opening minifigure cockpit, rotating double stud shooter and rotating flick missile shooter. The set includes 4 minifigures who are equipped with assorted weapons and accessories to inspire endless action-packed role-play scenarios.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70916, 'The Batwing', 1053, 'Patrol the sky above Gotham City in The Batwing!', 'Fly high above Gotham City in the Batwing and battle against Harley Quinn™ with Batman™ and Robin™ in this cool THE LEGO® BATMAN MOVIE: The Batwing set. The Batwing features an opening dual minifigure cockpit for Batman and Robin, rotating boosters, adjustable wings for flight and landing modes, 2 spring-loaded shooters, 2 disc shooters and an opening rear compartment with a car inside. Harley Quinn has a mobile cannon with a 6-stud rapid shooter. Includes 3 minifigures with weapons and accessory elements including Batman’s Batarang and Harley’s hammer.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70917, 'The Ultimate Batmobile', 1456, 'Divide the 4-in-1 Ultimate Batmobile and conquer the Super-Villains!', 'Team up with THE LEGO® BATMAN MOVIE characters Batman™, Batgirl™, Robin™ and Alfred Pennyworth™ (in Batsuit) to give the Super-Villains quadruple trouble with The Ultimate Batmobile! This amazing model divides into 4 separate vehicles: the Batmobile, Batwing, Bat-Tank and Batcycle. The Batmobile features foldout boosters and 4 stud shooters, while the Batwing has foldout wings and 2 spring-loaded shooters. The Batcycle has foldable wheels and the heavily-armored Bat-Tank boasts 2 hidden 6-stud rapid shooters. The set also includes the rotating Bat-Signal with a LEGO® light brick, Polka-Dot Man’s flying disc, plus 8 minifigures with assorted weapons and accessories to inspire endless role-play action.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70918, 'The Bat-Dune Buggy', 198, 'Bring down Captain Boomerang™ with Batman’s Bat-Dune Buggy!', 'Glide over bumps in the Gotham City streets and face off against Captain Boomerang™ with THE LEGO® BATMAN MOVIE: The Bat-Dune Buggy set. This cool buggy features a minifigure cockpit with an opening cage for Batman™, rear-wheel suspension and 2 stud shooters. This LEGO Batman toy includes 2 minifigures, each equipped with Batarangs and boomerangs to boost the role-play battle fun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70919, 'The Justice League™ Anniversary Party', 267, 'Party on with Superman™ and friends!', 'Recreate the hilarious scene from THE LEGO® BATMAN MOVIE where the Justice League™ throw a big party… but don’t invite Batman™! The Justice League Anniversary Party set features a wheel-operated, rotating dance floor, DJ booth with record decks, bunting and loads of translucent decorative elements. This LEGO Batman toy also features 4 minifigures, including Superman™, plus a Wonder Dog™ figure. (Note: Batman minifigure not included in this set.)
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70920, 'Egghead™ Mech Food Fight', 293, 'Join Batman™ in a comical food fight!', 'Help Batman™ fend off Egghead™ and Condiment King\'s food-firing attacks with THE LEGO® BATMAN MOVIE: Egghead Mech Food Fight set. The Egghead Mech features an opening egg-shaped minifigure cockpit, posable arms and legs, a fried egg disc shooter, spinning and grabbing whisk/claw and a canister containing chicken and egg elements. Condiment King is armed with ketchup and mustard stud shooters. This LEGO Batman toy includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70921, 'Harley Quinn™ Cannonball Attack', 425, 'Dodge Harley Quinn’s cannonball attacks!', 'Stage a face-off between Batgirl™ and Harley Quinn™ with THE LEGO® BATMAN MOVIE: Harley Quinn Cannonball Attack set, featuring a truck and 2 mini builds of Gotham City buildings. Harley Quinn’s truck features an elevating and rotating Harley Quinn minifigure-shooting cannon, opening doors, and an opening hood. The 2 mini builds are packed with play-starting features such as an ATM, dynamite element and a hinged ladder. This LEGO Batman™ toy includes 4 minifigures and a rat figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70922, 'The Joker™ Manor', 3444, 'Dare to enter The Joker™ Manor!', 'Help Batman™, Barbara Gordon, Alfred Pennyworth™ (in his classic Batsuit) and Nightwing™ regain control of the jokerized Wayne Manor with this massive THE LEGO® BATMAN MOVIE set. The Joker™ Manor is packed with iconic details from the movie and cool functions, including a rollercoaster encircling the whole building, a huge buildable The Joker head with trapdoor and slide, punching boxing gloves, a rocking ‘The Joker’ sign and rotating ‘big eye’ tower. The interior includes a cinema room with a romantic DVD element, kitchen with buildable microwave plus lobster and lemon-slice decorated tile elements, living room with a buildable grand piano, fireplace and bust, swimming pool room, and a music studio with guitar element and buildable mixing desk and loudspeakers. Build this magnificent manor and then recreate your favorite scenes from the movie with 10 included minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (70923, 'The Bat-Space Shuttle', 643, 'Launch a space mission from the Batcave!', 'Take off from the Batcave in The Bat-Space Shuttle with this fun-packed THE LEGO® BATMAN MOVIE set. The shuttle has a detachable triple-booster pack, 4 stud shooters and an opening rear compartment with a Bat-Moon Buggy for a minifigure to drive. The Batcave features a dock for the shuttle, Bat-Kayak with a rotating display stand, and a sliding costume rail with 3 detachable costume minifigures. This LEGO Batman™ toy also includes 6 minifigures with weapons to role-play, recreate and reimagine your favorite scenes from the smash-hit movie.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71018, 'Series 17', 7, 'Collect the LEGO® Minifigures, Series 17—A story in every bag!', 'Bring new and exciting play possibilities to existing LEGO® sets, with Series 17 of the LEGO Minifigures Collection, featuring the Hot Dog Vendor, Elf Maiden, Butterfly Girl, Circus Strongman, Veterinarian, Battle Dwarf, Dance Instructor, Gourmet Chef, Connoisseur, Corn Cob Guy, Roman Gladiator, Rocket Boy, Pro Surfer, Retro Space Hero and the Yuppie, plus a mystery character. Each minifigure comes in a sealed ‘mystery’ bag, together with one or more accessories, a display plate and a collector’s leaflet.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71019, 'THE LEGO® NINJAGO® MOVIE™', 8, 'Bring the NINJAGO® world to life with LEGO® Minifigures!', 'Bring exciting new play possibilities to LEGO® NINJAGO® sets with LEGO Minifigures—THE LEGO NINJAGO MOVIE™ series, featuring Kai Kendo, Spinjitzu Training Nya, Lloyd, Jay Walker, Cole, Zane, Lloyd Garmadon, Master Wu, Sushi Chef, N-POP Girl, GPL Tech, Shark Army Octopus, Shark Army Great White, Shark Army General #1, Shark Army Angler, Garmadon, Volcano Garmadon, Flashback Garmadon, Misako and Gong & Guitar Rocker. Each minifigure comes in a sealed ‘mystery’ bag, together with one or more accessories, plus a display plate and a collector’s leaflet.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71020, 'THE LEGO® BATMAN MOVIE Series 2', 8, 'Discover new heroes and villains in LEGO® Minifigures—THE LEGO BATMAN MOVIE Series 2.', 'Bring exciting new play possibilities to existing LEGO® sets with LEGO Minifigures. This new, awesome lineup of exclusive, Limited Edition collectible characters makes a perfect addition to first THE LEGO BATMAN MOVIE series. Enjoy all-new action-packed adventures with Swimsuit Batman™, Vacation Robin™, Vacation The Joker™, Disco Harley Quinn™, Vacation Alfred Pennyworth™, Vacation Batgirl™, Doctor Phosphorus™, Clock King™, Mermaid Batman™, Killer Moth™, Jor-El™, General Zod™, Apache Chief™, Bat-Merch Batgirl™, Hugo Strange™, Disco Alfred Pennyworth™, Black Canary™, Black Vulcan™, Wonder Twin Zan™ and Wonder Twin Jayna™. Each LEGO DC minifigure comes in a sealed ‘mystery’ bag, together with one or more accessory elements, plus a collector\'s leaflet and a new-for-January-2018 display plate with a printed Batman™ logo.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71021, 'Series 18: Party', 7, 'Get the party started with LEGO® Minifigures!', 'Bring exciting new play possibilities to existing LEGO® sets with the celebratory LEGO Minifigures Party series. This festive series of fun collectibles comes with an array of new-for-April-2018 accessories and costumes, and features a host of brightly dressed characters, all ready to party. The Party series lineup includes the Dragon Suit Guy, Firework Guy, Elephant Costume Girl, LEGO Brick Suit Guy, LEGO Brick Suit Girl, Cactus Girl, Party Clown, Cake Guy, Unicorn Guy, Flowerpot Girl, Birthday Party Girl, Birthday Party Boy, Spider Suit Boy, Cowboy Costume Guy, Race Car Guy, Cat Costume Girl and, last but not least, a rare replica of one of the first minifigures ever produced—the 1978 Police Officer. Each minifigure comes in a sealed ‘mystery\' bag, together with one or more accessory elements, plus a collector\'s leaflet and a unique display baseplate.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71040, 'The Disney Castle', 4080, 'Welcome to the magical Disney Castle!', 'Bring the magical world of Disney to your home with The Disney Castle. This highly detailed LEGO® model with over 4,000 pieces offers a rewarding build and play experience, and comes with an array of exciting Disney-themed features and functions. The intricately detailed facade and towers replicate the iconic Walt Disney World® Resort Cinderella Castle, and each accessible castle room includes special features inspired by some of Disney’s greatest animated feature films, providing endless play possibilities with the included minifigures: Mickey Mouse, Minnie Mouse, Donald Duck, Daisy Duck and Tinker Bell, or other characters from your collection.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71042, 'Silent Mary', 2294, 'Discover the secrets of the Silent Mary!', 'Bring the magic of Disney’s Pirates of the Caribbean to your home with this impressive replica of the Silent Mary ghost ship. This highly detailed LEGO® model with over 2,200 pieces features a hinged bow section, opening skeleton hull with decay and destruction detailing, movable rudder, collapsible main mast and two further masts, long bowsprit with crow’s nest and mast, tattered sails, detailed quarterdeck, plus a rowboat with two oars and an array of weapons and accessory elements. This model provides a rewarding build and play experience, and the integrated stand makes it suitable for display in the home or office. Also includes eight minifigures: Captain Jack Sparrow, Henry, Carina, Lieutenant Lesaro, Captain Salazar, Officer Magda, Officer Santos and the Silent Mary Masthead, plus two detachable ghost sharks.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71171, 'Starter Pack PLAYSTATION® 4', 267, 'With LEGO® Dimensions™, you\'re gonna need a bigger imagination!', 'The LEGO® DIMENSIONS™ Starter Pack has everything you need to set out on epic mash-up adventures filled with iconic worlds and unlikely allies as you\'ve never seen them before. Build Batman™, Wyldstyle™ and Gandalf™, then attach them to the special LEGO Toy Tags and place them on the LEGO Toy Pad with buildable LEGO Gateway to bring them to life in the game. Add the buildable 3-in-1 Batmobile™ for extra in-game fun, and rebuild it into The Batblaster or a Sonic Batray to boost its in-game abilities. There\'s a whole multiverse of puzzles to solve, plus challenges and enemies to face, and when you\'re ready for more, collect Level, Team and Fun Packs from fan-favorite brands featuring buildable characters and rebuildable gadgets. This Starter Pack includes buildable Batman, Wyldstyle and Gandalf minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71203, 'Portal® 2 Level Pack', 85, 'Puzzle through LEGO® DIMENSIONS™ Portal® 2 with Chell!', 'Take your LEGO® DIMENSIONS™ gameplay to the next level with this challenging Portal® 2 Level Pack. Build the game\'s iconic protagonist, Chell, and place her on the LEGO Toy Pad to bring her to life in an instantly recognizable Aperture Science Test Labs level filled with mind-bending puzzles, Thermal Discouragement Beams, Neurotoxins and GLaDOS, the antagonistic artificial life form. Add the 3-in-1 Companion Cube and Sentry Turret to boost your gameplay, and rebuild each into 2 alternative models for upgraded in-game abilities that might be just enough to help Chell escape the confines of her portal-filled world. Includes a buildable Chell minifigure with her portal gun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71217, 'Zane Fun Pack', 45, 'Perfect your Spinjitzu skills with LEGO® NINJAGO™ Zane, the Ninja of Ice!', 'Bolster your LEGO® DIMENSIONS™ gameplay with the buildable Zane Fun Pack. Place the Ninja of Ice on the LEGO Toy Pad to bring him to life in the game, then deploy his Spinjitzu skills and other special abilities to solve puzzles and defeat enemies in true Ninja style. Add the 3-in-1 NinjaCopter to boost your gameplay, and rebuild it into a Glaciator and Freeze Fighter for upgraded in-game abilities. Includes a buildable Zane minifigure with his 2 golden shurikens.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71218, 'LEGO® DIMENSIONS™ Gollum Fun Pack', 39, 'Keep watch over the multiverse from the shadows with Gollum™ from The Lord of the Rings™!', 'Supplement your LEGO® DIMENSIONS™ gameplay with the Gollum™ Fun Pack. Place Gollum on the LEGO Toy Pad and see him spring to life in the game, then activate his special abilities to crack puzzles and defeat hordes of in-game enemies. Use 3-in-1 Shelob the Great™ to boost your gameplay and rebuild her into the 8-Legged Stalker and Poison Slinger for upgraded in-game abilities. Includes a Gollum minifigure with a fish element.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71221, 'Wicked Witch™ Fun Pack', 38, 'Unleash magical powers with the Wicked Witch™ of the West from The Wizard of Oz™!', 'Add a touch of magic to your LEGO® DIMENSIONS™ gameplay with the buildable Wicked Witch™ Fun Pack. Place the infamous sorceress on the LEGO Toy Pad to bring her to life in the game, then activate her special abilities to solve puzzles and weave her magic over enemies. Use her 3-in-1 Winged Monkey™ to boost your gameplay, and rebuild it into a Battle Monkey and Commander Monkey for upgraded in-game abilities. Includes a buildable Wicked Witch minifigure with her broom.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71228, 'The Ghostbusters™ Level Pack', 115, 'Fight ghosts with the LEGO® DIMENSIONS™ The Ghostbusters™ Level Pack!', 'Spookify your LEGO® DIMENSIONS™ experience with The Ghostbusters™ Level Pack. Build misfit parapsychologist Peter Venkman, attach him to the LEGO® Toy Tag, place him on the LEGO® Toy Pad to bring him to life in the game, and then help him fight Gozer and save New York City with the rest of The Ghostbusters! Use his Laser Deflector, Suspend Ghosts and Hazard Protection abilities to solve puzzles and battle enemies, and boost your gameplay with rebuildable 3-in-1 Ecto-1 or Ghost Trap. This set includes a buildable Peter Venkman minifigure and his proton pack.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71229, 'DC Comics™ Team Pack', 92, 'Get devious with DC Comics\' The Joker™ & Harley Quinn™!', 'Enhance your LEGO® DIMENSIONS™ experience with the DC Comics™ Team Pack, featuring the demented duo of The Joker™ & Harley Quinn™. Simply attach the minifigures to their LEGO Toy Tags and place them on the LEGO Toy Pad to bring them to life in the game. Then use their special abilities to solve puzzles and battle enemies. Add The Joker\'s 3-in-1 Chopper and Harley\'s 3-in-1 Quinn-mobile to boost your gameplay, and then rebuild them into the Mischievous Missile Blaster and The Joker\'s Lock ‘n Laser Jet or the Quinn Ultra Racer and Missile Launcher for upgraded abilities in the game. This set includes buildable The Joker and Harley Quinn minifigures, each with a weapon.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71232, 'LEGO® DIMENSIONS™ Eris Fun Pack', 59, 'Team up with LEGO® Chima’s™ Eris to outsmart the competition!', 'Let creativity be your guide to a building and gaming adventure—journey through unexpected worlds and team up with unlikely allies on a quest to defeat the evil Lord Vortech. Join Chima’s™ tactical warrior in a crazy mash-up multiverse of your favorite characters! Build and place Eagle Princess Eris on the LEGO® Toy Pad to launch her into the game, then activate her special Super Strength, CHI, Target and Flying abilities to solve puzzles and defeat enemies. Send in the Eagle Interceptor to helpher on her quest and rebuild it into an Eagle Skyblazer and Eagle Swoop Diver for upgdraded powers in the game!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71234, 'Sensei Wu Fun Pack', 58, 'Become one with Spinjitzu Master Sensei Wu!', 'Bolster your LEGO® DIMENSIONS™ gameplay with the buildable Sensei Wu Fun Pack. Place the wise and powerful ninja on the LEGO® Toy Pad to bring him to life in the game, then deploy his Spinjitzu skills and other special abilities to solve puzzles and defeat enemies. Add the 3-in-1 Flying White Dragon to boost your gameplay, and rebuild it into a Golden Fire Dragon and Ultra Destruction Dragon for upgraded in-game abilities. The set includes a buildable Sensei Wu minifigure with his golden staff.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71235, 'Midway Arcade™ Level Pack', 96, 'Go retro with the LEGO® DIMENSIONS™ Midway Arcade™ Level Pack!', 'Power-up your LEGO® DIMENSIONS™ experience with the Midway Arcade™ Level Pack, featuring a buildable Gamer Kid minifigure. Attach him to his LEGO® Toy Tag and place him on the LEGO® Toy Pad to bring him to life in the game, helping him to put the rogue Midway Arcade characters back where they belong. Add Gamer Kid\'s 3-in-1 G-6155 Spy Hunter or Arcade Machine to boost your gameplay, and rebuild them into alternative models for upgraded in-game abilities. This set includes a buildable Gamer Kid minifigure with his coin and soda can.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71238, 'Cyberman™ Fun Pack', 40, 'Set out on time-traveling adventures with Cyberman™ from Doctor Who!', 'Upgrade your LEGO® DIMENSIONS™ gameplay experience with the buildable Cyberman™ Fun Pack. Place the drone-like humanoid on the LEGO® Toy Pad to bring him to life in the game, then activate his hi-tech abilities to solve puzzles and take on the enemies in true Doctor Who style. Add the 3-in-1 Dalek to boost your gameplay, and rebuild it into a Fire ‘n Ride Dalek and Silver Shooter Dalek for upgraded in-game abilities. This set includes a buildable Cyberman minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71240, 'Bane™ Fun Pack', 52, 'Dig your way through the multiverse as DC Comics™ villain, Bane™!', 'Broaden your LEGO® DIMENSIONS™ gameplay with the buildable Bane™ Fun Pack. Place the iconic villain on the LEGO® Toy Pad to bring him to life in the game, then activate his many super-human powers to solve puzzles and overcome villains. Add the 3-in-1 Drill Driver to boost your gameplay, and rebuild it into a Bane Dig ‘n Drill and the Bane Drill ‘n Blast for upgraded in-game abilities. This set includes a buildable Bane minifigure with his venom tank.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71242, 'Ghostbusters™ Story Pack', 259, 'Get spooky with Abby Yates and the Ghostbusters™!', 'Add more gameplay to your LEGO® DIMENSIONS™ experience with the Ghostbusters™ Story Pack, featuring Abby Yates. Simply attach the minifigure to her LEGO Toy Tag and place her on the LEGO Toy Pad to bring her to life in the game. Then use her special abilities to solve puzzles and battle enemies. Add the 3-in-1 Ecto-1 to boost your gameplay, rebuild it into the Ectozer and The PerfEcto for upgraded abilities in the game. This set includes a buildable Abby Yates minifigure with her Proton Blaster, a 3-in-1 vehicle, Zhu’s Chinese Restaurant gateway build, six new game levels, and an Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71245, 'Adventure Time™ Level Pack', 102, 'Help Finn battle foes through an Adventure Time™ level!', 'Enjoy more LEGO® DIMENSIONS™ gameplay with the Adventure Time™ Level Pack featuring Finn the Human. Simply attach the minifigure to his LEGO Toy Tag and place him on the LEGO Toy Pad to bring him to life in the game. Then use his special abilities to solve puzzles and battle enemies. Add the 3-in-1 Ancient War Elephant and Jakemobile to boost your gameplay, and then rebuild them into the Cosmic Squid and Psychic Submarine or Snail Dude Jake and Hover Jake for upgraded abilities in the game. This set includes a buildable Finn the Human minifigure and his sword, two rebuildable vehicles, a new game level, and an Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71246, 'Adventure Time™ Team Pack', 96, 'Explore the Land of Ooo with Jake and Lumpy Space Princess!', 'Enhance your LEGO® DIMENSIONS™ experience with the Adventure Time™ Team Pack, featuring Jake the Dog and Lumpy Space Princess. Simply attach the minifigures to their LEGO Toy Tags and place them on the LEGO Toy Pad to bring them to life in the game. Then use their special abilities to solve puzzles and battle enemies. Add the 3-in-1 Lumpy Car and BMO to boost your gameplay, and then rebuild them into the Lumpy Truck and Lumpy Land Whale or DOGMO and SNAKEMO for upgraded abilities in the game. This set includes buildable Jake the Dog and his torch, and Lumpy Space Princess and her mobile phone, two 3-in-1 vehicles, and an Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71247, 'Harry Potter™ Team Pack', 119, 'Bring the Wizarding World to life with Harry and Voldemort!', 'Enhance your LEGO® DIMENSIONS™ experience with the Harry Potter™ Team Pack, featuring Harry Potter and Lord Voldemort™. Simply attach the minifigures to their LEGO Toy Tags and place them on the LEGO Toy Pad to bring them to life in the game. Then use their special abilities to solve puzzles and battle enemies. Add the 3-in-1 Hogwarts™ Express and Enchanted Car to boost your gameplay, and then rebuild them into the Steam Warrior and Soaring Steam Plane or Shark Sub and Monstrous Mouth for upgraded abilities in the game. This set includes buildable Harry Potter and Lord Voldemort and their wands, two 3-in-1 vehicles, and an Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71248, 'Mission: Impossible™ Level Pack', 76, 'Hang by a thread with Ethan on a Mission: Impossible™ level!', 'Secret agent Ethan Hunt is being framed for the theft of highly classified materials from IMF and needs your help to find the true villain! Infiltrate your way through the American Embassy, CIA Headquarters and more in this thrilling game level. Build Ethan and use his Camera Spectacles for the perfect disguise, and wear the Magno Gloves to sneak your way up walls. When you need a quick escape, hop onto the IMF Scrambler or IMF Sport Car, and then rebuild the vehicles into the ShockCycle and IMF Covert Jet, and the IMF Tank and The IMF-Splorer to access a host of new super-spy abilities. Unlock the exclusive Mission: Impossible™ Adventure World and Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71251, 'A-Team™ Fun Pack', 73, 'Conquer the bad guys with action hero B.A. Baracus!', 'Enhance your LEGO® DIMENSIONS™ experience with the A-Team™ Fun Pack featuring B.A. Baracus. Simply attach the minifigure to his LEGO Toy Tag and place him on the LEGO Toy Pad to bring him to life in the game. Then use his special abilities to solve puzzles and battle enemies. Add the 3-in-1 B.A.’s Van to boost your gameplay, and then rebuild it into the Fool Smasher and The Pain Plane for upgraded abilities in the game. This set includes a buildable B.A. Baracus and his wrench, a 3-in-1 vehicle, and an Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71255, 'Teen Titans Go!™ Team Pack', 105, 'Fight off villains with Raven and Beast Boy in the Teen Titans Go!™ Team Pack!', 'Enjoy more LEGO® DIMENSIONS™ gameplay with the Teen Titans Go!™ Team Pack featuring Raven and Beast Boy! Simply attach the minifigures to their LEGO Toy Tags and place them on the LEGO Toy Pad to bring them to life in the game. Then use their special abilities to solve puzzles and battle enemies. Add the T-Car and Spellbook of Azarath to boost your gameplay, and then rebuild them into the Forklift and T-Plane or Raven Wings and Giant Hand for upgraded abilities in the game. This set includes buildable Raven and Beast Boy minifigures and their accessories, two 3-in-1 rebuildable vehicles, and an Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71264, 'THE LEGO® BATMAN MOVIE Story Pack', 156, 'Fight crime with Batgirl™ and Robin™ in THE LEGO® BATMAN MOVIE!', 'Fight crime with Batgirl™ and Robin™ in the streets of Gotham with the all-new THE LEGO® BATMAN MOVIE Story Pack! Build an all-new Bat-Computer gateway for your LEGO Toy Pad and then activate Batgirl’s and Robin’s special abilities to solve puzzles and battle enemies. Take flight with the Batwing to accelerate your gameplay, and then rebuild it into The Black Thunder and Bat-Tank for enhanced in-game powers. This set includes a Bat-Computer gateway build, buildable Batgirl and Robin minifigures, a 3-in-1 Batwing vehicle, six new game levels and THE LEGO BATMAN MOVIE Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71266, 'LEGO® City Fun Pack', 46, 'Help stop crime in the LEGO® DIMENSIONS™ multiverse with LEGO® City’s Fun Pack', 'Help save the LEGO® DIMENSIONS™ multiverse with Chase McCain from LEGO City! Simply attach the minifigure to his LEGO Toy Tag and place him on the LEGO Toy Pad to bring him to life in the game, and then activate his special abilities to solve puzzles and battle enemies. Add the Police Helicopter to boost your gameplay, and then rebuild it into the Police Hovercraft and Police Plane for upgraded in-game powers. This set includes a Chase McCain minifigure, 3-in-1 Police Helicopter vehicle, and a LEGO City Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71267, 'Goonies™ Level Pack', 118, 'Search for treasure while avoiding the Fratelli family in the Goonies™ Level Pack!', 'Enjoy more LEGO® DIMENSIONS™ gameplay with the Goonies™ Level Pack featuring Sloth. Simply attach the minifigure to his LEGO Toy Tag and place him on the LEGO Toy Pad to bring him to life in the game. Then use his special abilities to solve puzzles and battle enemies. Add the 3-in-1 One-Eyed Willy’s Pirate Ship and Skeleton Organ to boost your gameplay, and then rebuild them into the Fanged Fortune and Inferno Cannon or Skeleton Jukebox and Skele-Turkey for upgraded abilities in the game. This set includes a buildable Sloth minifigure, two 3-in-1 rebuildable vehicles, a new game level, and a Goonies Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71286, 'Knight Rider™ Fun Pack', 55, 'Carry on your crime-fighting adventure with Michael Knight and K.I.T.T.!', 'Help save the LEGO® DIMENSIONS™ multiverse with Michael Knight from the classic 80s TV series, Knight Rider™! Simply attach the minifigure to his LEGO Toy Tag and place him on the LEGO Toy Pad to bring him to life in the game, and then activate his special abilities to solve puzzles and battle enemies. Add K.I.T.T. to boost your gameplay, and then rebuild it into the K.I.T.T. Jet and Goliath Armored Semi for upgraded in-game powers. This set includes a Michael Knight minifigure, 3-in-1 K.I.T.T. vehicle, and a Knight Rider™ Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71287, 'Teen Titans Go!™ Fun Pack', 56, 'Get ready to save the day in the LEGO® DIMENSIONS™ multiverse with Starfire in the Teen Titans Go!™ Fun Pack!', 'Enhance you LEGO® DIMENSIONS™ experience with your very own Teen Titans Go!™ Fun Pack featuring Starfire! Simply attach the minifigure to her LEGO Toy Tag and place her on the LEGO Toy Pad to bring her to life in the game, and then activate her special abilities to solve puzzles and battle enemies. Add the Titan Robot and then rebuild it into the T-Rocket or Robot Retriever for even more fun! This set includes a Starfire minifigure, 3-in-1 vehicle, and the Teen Titans Go! Adventure World with a Battle Arena with an exclusive Teen Titans Go! episode!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71343, 'The Powerpuff Girls™ Fun Pack', 56, 'Save the world before bedtime in the LEGO® DIMENSIONS™ multiverse with Buttercup™, the toughest fighter!', 'Fight crime and come just in time in the LEGO® DIMENSIONS™ multiverse with Buttercup™, the toughest fighter! Simply attach the minifigure to her LEGO Toy Tag and place her on the LEGO Toy Pad to bring her to life in the game, and then activate her special abilities to solve puzzles and battle enemies. Add the Mega Blast Bot to crush your foes, and then rebuild it into the Ka-Pow Cannon and Slammin’ Guitar for extra-awesome combat abilities. This set includes a Buttercup minifigure, 3-in-1 Mega Blast Bot vehicle, and The Powerpuff Girls™ Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71344, 'Excalibur Batman™ Fun Pack', 57, 'Fight crime in the night with the bold and brave Excalibur Batman™!', 'Join Excalibur Batman™ from THE LEGO® BATMAN MOVIE in an epic quest to save the LEGO DIMENSIONS™ multiverse! Simply attach the minifigure to his LEGO Toy Tag and place him on the LEGO Toy Pad to bring him to life in the game, and then activate his special abilities to solve puzzles and battle enemies. Add the Bionic Steed and then rebuild it into the Bat-Raptor and Ultrabat to enhance your gameplay. This set includes an Excalibur Batman minifigure, 3-in-1 vehicle, and THE LEGO BATMAN MOVIE Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71346, 'The Powerpuff Girls™ Team Pack', 93, 'Sugar, spice and everything nice! Bring Townsville to life in the LEGO® DIMENSIONS™ multiverse with Blossom™ and Bubbles™!', 'Fight crime and battle the forces of evil in the LEGO® DIMENSIONS™ multiverse with Blossom™ and Bubbles™ from The Powerpuff Girls™! Simply attach the minifigures to their LEGO Toy Tags and place them on the LEGO Toy Pad to bring them to life in the game. Then use their special abilities to solve puzzles and battle enemies. Add the iconic PPG Smartphone and Octi to boost your gameplay, and then rebuild them into the Super Skunk or Sonic Squid and PPG Hotline and Powerpuff Mag-Net for upgraded abilities in the game. This set includes buildable Blossom and Bubbles minifigures, two 3-in-1 rebuildable vehicles, and an Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71348, 'Harry Potter™ Fun Pack', 64, 'Continue your wizarding adventures in LEGO® DIMENSIONS™ with your very own Harry Potter™ Fun Pack featuring Hermione Granger.', 'Enhance you LEGO® DIMENSIONS™ experience with your very own Harry Potter™ Fun Pack featuring Hermione Granger. Simply attach the minifigure to her LEGO Toy Tag and place her on the LEGO Toy Pad to bring her to life in the game, and then activate her special abilities to solve puzzles and battle enemies. Add Buckbeak and then rebuild him into the Giant Owl and Fierce Falcon to enhance your gameplay. This set includes a Hermione Granger minifigure, 3-in-1 vehicle, and the Harry Potter™ Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (71349, 'Beetlejuice™ Fun Pack', 56, 'It’s showtime! Bring Beetlejuice™ to life in the LEGO® DIMENSIONS™ multiverse for an eerie adventure!', 'Turn on the juice to see what shakes loose! Get ready for some spirited fun in the LEGO® DIMENSIONS™ multiverse with the Beetlejuice™ fun pack featuring Beetlejuice! Simply attach the minifigure to his LEGO Toy Tag and place him on the LEGO Toy Pad to bring him to life in the game, and then activate his special abilities to solve puzzles and battle enemies. Add the Saturn’s Sandworm for more ghostly powers, and then rebuild it into the Haunted Vacuum and Spooky Spider for additional combat abilities. This set includes a Beetlejuice minifigure, 3-in-1 Saturn’s Sandworm vehicle, and a Beetlejuice Adventure World with a Battle Arena.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (72001, 'Lance\'s Hover Jouster', 217, 'Wipe out the tech infection with Lance’s Hover Jouster!', 'Help Lance defeat Cezar and CyberByter Dennis with his Hover Jouster, featuring a minifigure cockpit with 2 transparent-red lances, 2 flick missiles, 2 movable deflectors, 2 shield holders plus 4 rotating wheels for speedy jousting action. This fun toy for kids includes 3 scannable shields, 2 minifigures and a CyberByter Dennis figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (72002, 'Twinfector', 191, 'Double the action with the 2-in-1 Twinfector!', 'Help Aaron fend off Fred and Pola in their powerful 2-in-1 Twinfector cycle with dual critter shooters. Divide the Twinfector to launch the 2 individual flyers and double the LEGO® NEXO KNIGHTS™ battle fun. This cool toy for kids includes 3 minifigures and 2 scannable shields.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (72003, 'Berserker Bomber', 369, 'Jet off with Macy for a Berserker Bomber battle!', 'Prepare for high-flying action with the Berserker Bomber, featuring a detachable winged eye, dual 6-stud tech infection shooters and movable wings, plus a detachable Vyro Suit for the MechaByter. Attach the jet pack to Macy and send Berserker flying back to Monstrox! This popular kids toy includes 2 minifigures, a MechaByter figure and 2 scannable shields.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (72004, 'Tech Wizard Showdown', 506, 'Suit up for a Tech Wizard Showdown with Clay’s 3-in-1 mech!', 'Pitch Monstrox against Merlok 2.0 and Clay in their highly posable mech, featuring a cockpit for Clay’s battle suit, buildable sword, 6-stud rapid shooter, Combo NEXO POWER shield and a detachable Merlok 2.0 hologram figure attached to a flyer with a sword and shield holder. The Monstrox hologram is on a critter base with 4 legs and 2 critter shooters. This cool toy for kids includes 2 minifigures, a CyberByter figure and 3 scannable shields.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (72005, 'Aaron\'s X-bow', 569, 'Drop in for a surprise attack with Aaron’s X-bow!', 'Launch an attack on VanByter No. 307 and the CyberByter with Aaron’s X-bow, featuring rotating blades, crossbow and dual flick missiles. Use the X-bow’s dropship function to release Robin’s Knight Raider featuring dual stud shooters, and then rescue him from the battlefield for a speedy escape. This fun toy for kids includes 3 minifigures, a CyberByter figure and 3 scannable shields.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (72006, 'Axl\'s Rolling Arsenal', 604, 'Deploy Axl\'s Rolling Arsenal for the biggest battles!', 'Get ready for a heavy-duty LEGO® NEXO KNIGHTS™ battle with Axl\'s Rolling Arsenal, featuring hidden flick missiles and opening drawbridge. Pitch the Jestroyer with its dual 6-stud rapid shooters against the Vyro Glyder. Lock up the critters in the Critter Trapper\'s storage chest and save Knighton from the tech infection. This popular kids toy includes 4 minifigures and 3 scannable shields.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75060, 'Slave I', 1996, 'Lift off for bounty-hunting adventures in the Slave I!', 'Track down fugitives with legendary bounty hunter, Boba Fett™ aboard the powerful Slave I! This exclusive LEGO® Star Wars™ model features a rotating cockpit and wings for flight and landing mode, plus dual shooters and hidden blasters to repel attackers. Reenact the capture of Han Solo™ in Star Wars™: Episode V The Empire Strikes Back and take off from Bespin with the carbonite-imprisoned Rebel hero in the cargo hold. Attach the stand to display this iconic ship in characteristic upright flight. Includes 4 minifigures with weapons: Boba Fett™, Bespin Guard™, Stormtrooper™ and Han Solo™.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75095, 'TIE Fighter™', 1685, 'Presenting the Ultimate Collector Series TIE Fighter – the iconic Imperial starfighter!', 'We proudly present the Ultimate Collector Series LEGO® Star Wars™ TIE Fighter™. As featured in many of the action-packed Star Wars™ battle scenes, including the decisive battle that led to the destruction of the first Death Star™, this large-scale LEGO-brick rendition of the classic Imperial starfighter has intricate detailing, as well as an opening top hatch and an exclusive TIE Fighter Pilot™ minifigure with a blaster pistol. And when you want to keep it safe from Rebel attack, mount the model on the display stand and keep yourself updated with all the key facts and figures on the included fact plaque. The Ultimate Collector Series TIE Fighter™ is the perfect addition to your Star Wars™ collection!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75099, 'Rey\'s Speeder™', 193, 'Speed into action on Rey\'s Speeder!™', 'Hover into action on Rey\'s Speeder™! This cool landspeeder has everything Rey needs for scouting the surface of a desert planet, including dual stud shooters, opening storage hatch and side-mounted bag, blaster, buzzsaw and electrobinoculars. There’s also a detachable sled with space for a minifigure when Rey must make a quick escape down the desert dunes! Recreate your own fantastic scenes from Star Wars™: The Force Awakens. Includes 2 minifigures: Rey and Unkar’s Thug with a crowbar.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75102, 'Poe\'s X-Wing Fighter™', 717, 'Go on daring missions with Poe\'s X-Wing Fighter!', 'Battle the forces of the First Order with Poe\'s X-Wing Fighter. This customized starfighter is packed with features, like the 4 spring-loaded shooters, 2 stud shooters, retractable landing gear, opening wings, opening cockpit with space for a minifigure and space behind for the BB-8 Astromech Droid. There\'s even a loader with weapon rack, extra missiles and ammunition, and a seat for a minifigure. So climb the access ladder, strap in and get ready to recreate your own great scenes from Star Wars: The Force Awakens! Includes 3 minifigures with assorted weapons and accessories: Poe Dameron, Resistance ground crew and a Resistance X-Wing Pilot, plus a BB-8 Astromech Droid.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75104, 'Kylo Ren’s Command Shuttle™', 1005, 'Enter the battle with Kylo Ren’s Command Shuttle™!', 'Enter the battle with Kylo Ren’s personal Command Shuttle™! This fantastic, highly detailed starship has loads of features, including opening front, rear and bottom storage bays; wing-mounted, spring-loaded shooters and detachable weapon racks. And when you’re ready for even more action, activate the amazing extending wing function! It’s time to hunt down the enemy and play out your own great scenes from Star Wars™: The Force Awakens! Includes 6 minifigures with assorted weapons and accessories: Kylo Ren, General Hux, First Order Officer, 2 First Order Crew and a First Order Stormtrooper Officer.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75107, 'Jango Fett™', 85, 'Battle the Jedi with posable Jango Fett!™', 'Battle the Jedi with Jango Fett™ as you’ve never seen him before! This amazing buildable LEGO® version of the galaxy’s greatest bounty hunter is built for intense play and has lots of great details, including fully posable limbs, a jetpack with flick missile shooting function, 2 buildable blaster pistols, holsters and detailed, metal-look armour. It’s time to arm up and go hunt some Jedi!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75109, 'Obi-Wan Kenobi™', 83, 'Use the Force to battle the Separatists with posable Obi-Wan Kenobi™!', 'Command the Clone Army against the Separatists with buildable Obi-Wan Kenobi™. With durable, fully posable limbs, special white Clone armour, fabric cape, buildable blue Lightsaber and a holster with extra Lightsaber handle, this LEGO® Jedi Master is ready for tough action play!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75111, 'Darth Vader™', 160, 'Feel the power of the dark side with posable Darth Vader™!', 'Feel the power of the dark side with Darth Vader™! This buildable LEGO® version of iconic Sith Lord Vader has all the details you’d expect, including fully posable limbs, black armoured suit, fabric cape and a buildable red Lightsaber. Harness the power of the dark side and prepare for intense action play!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75114, 'First Order Stormtrooper™', 81, 'Prepare for battle against the Resistance!', 'Set out on galactic battles with this buildable and highly posable First Order Stormtrooper figure. Featuring sleek armor, spring-loaded shooter, blaster pistol and holster attachments, you\'ll be walking tall with this durable and sturdy figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75116, 'Finn', 98, 'Practice your warrior skills with Finn!', 'Get ready for intense dueling action with this buildable and highly posable Finn figure, featuring a Lightsaber with wheel-activated arm-swinging battle function and a spring-loaded shooter with extra ammunition.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75117, 'Kylo Ren™', 86, 'Go on the hunt for Resistance forces with the fierce Kylo Ren!', 'Lead the First Order into battle with buildable and highly posable Kylo Ren. Featuring a real cloth cape and robe, Ren\'s special Lightsaber and wheel-activated arm-swinging battle function, epic Star Wars battles are never far away.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75118, 'Captain Phasma™', 82, 'Command the troops with Captain Phasma™!', 'Issue orders to the troops with buildable and highly posable Captain Phasma. Featuring a spring-loaded shooter with extra ammunition, holster, metallic-look armor and a special real cloth cape with red trim, this First Order commander is ready for combat.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75119, 'Sergeant Jyn Erso™', 104, 'Blast into battle with Rebel soldier Jyn Erso!', 'Help the Rebel Alliance take on the Empire with this buildable and highly posable Jyn Erso figure. Featuring a blaster rifle with spring-loaded shooter, wheel-operated arm-swinging battle function, and detachable back-mounted truncheons, this durable figure is just the thing for recreating intense battles from the movie, Star Wars: Rogue One.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75120, 'K-2SO™', 169, 'Go behind enemy lines with K-2SO!', 'Infiltrate the Empire with buildable and highly posable K-2SO. This former Imperial security droid features a single/double-arm-swinging battle function, tough-looking decorated head and armor elements, and is extra tall for an even more impressive figure. This durable droid is perfect for dangerous missions against the Empire.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75121, 'Imperial Death Trooper™', 106, 'Enforce Imperial rule with the Empire’s elite Death Trooper!', 'Defend the Empire’s elite with this buildable and highly posable Death Trooper figure. Featuring a blaster rifle with spring-loaded shooter, blaster pistol with holster and imposing decorated armor elements including a pauldron with attachable ammo pouches, this durable Death Trooper is ready for action.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75125, 'Resistance X-Wing Fighter™', 87, 'Blast off on miniature X-Wing Fighter adventures!', 'Embark on mini Star Wars adventures with this fun Resistance X-Wing Fighter microfighter collectible, featuring foldable wings and space to seat the included Resistance X-Wing Pilot minifigure with blaster pistol.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75126, 'First Order Snowspeeder™', 91, 'Speed across distant planets in the micro First Order Snowspeeder™!', 'Engage the enemy with this LEGO® Microfighters First Order Snowspeeder, featuring a rotating stud shooter with extra ammo and space to sit the included First Order Snowtrooper minifigure with blaster.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75128, 'TIE Advanced Prototype™', 93, 'Go on the hunt for microfighter rebels!', 'Enter action-packed battle with this TIE Advanced Prototype microfighter collectible, featuring folding wings, dual flick missiles and space to sit the included TIE Pilot minifigure with blaster pistol.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75131, 'Resistance Trooper Battle Pack', 112, 'Speed into battle against the First Order forces!', 'Journey to a far-off galaxy with the Resistance Trooper Battle Pack. This set features a speeder with space for 2 minifigures and a rotating stud shooter, plus 3 Resistance Troopers and a Resistance Officer, each with a stud blaster.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75132, 'First Order Battle Pack', 88, 'Blast the Resistance with the powerful turbolaser!', 'Play out epic Star Wars battle scenes with the First Order Battle Pack. This set features a rotating First Order turbolaser turret with stud shooter and opening hatches that reveal weapon storage and control center to direct the fire. The set also includes 4 minifigures: 2 First Order Stormtroopers, First Order Technician and a First Order Crew, each with a stud blaster.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75139, 'Battle on Takodana™', 409, 'Defeat Kylo Ren at the forest castle!', 'Battle Finn against evil enemy Kylo Ren at the forest castle entrance, featuring sliding doors, wheel-activated exploding wall and collapsing staircase, plus a falling tree function. Includes 5 minifigures: Finn, Maz Kanata, Kylo Ren and 2 First Order Stormtroopers.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75144, 'Snowspeeder™', 1703, 'Build the ultimate LEGO® Snowspeeder!', 'Collect a true Star Wars classic: the T-47 Snowspeeder. This LEGO® interpretation of the iconic airspeeder that fans will remember from Star Wars: Episode V The Empire Strikes Back has all the details you\'d expect, including opening airbrakes, rotating rear gun, and an opening cockpit with space for the included Rebel Snowspeeder Pilot and Rebel Snowspeeder Gunner minifigures. This model also comes with a display stand and fact plaque, so it can take pride of place in any LEGO Star Wars collection.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75147, 'StarScavenger™', 558, 'Join StarScavenger on dangerous salvage missions!', 'Join the Freemakers: Rowan, Kordi and Zander as they travel the stars in search of space junk. With modular wings, engines and blasters, StarScavenger can be rebuilt into various configurations, and features a foldout top section that reveals a mini scavenger vessel with salvage scoop with space for a minifigure and R0-GR (Roger), the siblings’ friendly Droid. This set includes 3 minifigures plus a Droid.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75148, 'Encounter on Jakku™', 530, 'Stop the thief at Unkar Plutt\'s market stall!', 'Recreate exciting scenes on desert-planet Jakku at Unkar Plutt’s market stall, where Resistance hero Rey is forced to ward off Teedo riding an armored Luggabeast as he tries to steal the BB-8 Astromech Droid. This cool multi-level market stall scene features tables, a safe and container with spare parts, hidden weapons, tarpaulin and various accessory elements. You can also fold the model out for easy play access. This set includes 3 minifigures plus a BB-8 Astromech Droid and a Luggabeast.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75154, 'TIE Striker™', 543, 'Join the battle against the rebels!', 'Play out iconic sky battles with the amazing TIE Striker. With large adjustable wings, minifigure cockpit with top and front access, an opening rear storage hold and dual spring-loaded shooters at the front, this amazing model is the perfect opponent for any rebel starfighter. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75155, 'Rebel U-Wing Fighter™', 659, 'Battle the Empire with the amazing Rebel U-Wing Fighter!', 'The amazing U-Wing Fighter has all the details you would expect from an authentic Star Wars model, including 4 big engines, an opening minifigure cockpit with transparent lower observation window, opening side doors with pull-out stud shooters, dual spring-loaded shooters at the front, rear storage hold and huge wings that sweep back to create an even bigger model. Includes 5 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75156, 'Krennic\'s Imperial Shuttle', 863, 'Transport Director Krennic in his armor-plated shuttle!', 'Krennic’s Imperial Shuttle is an intimidating Imperial starship. Featuring huge folding wings and opening front and side panels, this amazing model also has an opening minifigure cockpit, detailed hold with seating for 4 minifigures, a rear ramp with blaster storage, dual spring-loaded shooters and retractable landing skids. Recreate epic space battles from the epic movie, Star Wars: Rogue One, or create your own. Includes 5 minifigures plus a Droid.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75159, 'Death Star™', 4016, 'Win the battle for the Empire with the awesome Death Star!', 'Reenact amazing scenes from the Star Wars saga with the Empire’s ultimate planet-zapping weapon—the Death Star! With over 4,000 pieces, this fantastic model has a galaxy of intricate and authentic environments, including a superlaser control room, Imperial conference chamber, hangar bay with moving launch rack and Lord Vader’s TIE Advanced with space for Vader inside, Emperor Palpatine’s throne room, Droid maintenance room, detention block, trash compactor, tractor beam, cargo area, turbo laser with spring-loaded shooters and seats for the 2 Death Star Gunners, and 2 movable turbo laser towers. This fantastic set also includes 23 iconic minifigures and 2 Droids to ensure hours of Star Wars battle fun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75160, 'U-Wing™ Microfighter', 109, 'Enter miniature battle with the amazing U-Wing Microfighter!', 'Play out miniature LEGO® Star Wars adventures with this U-Wing Microfighter, featuring folding wings, two stud shooters and space to seat the included U-Wing Pilot with his blaster pistol.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75161, 'TIE Striker™ Microfighter', 88, 'Engage the Rebels with the tough TIE Striker Microfighter!', 'Join the battle with this TIE Striker Microfighter, featuring folding wings, two stud shooters and space to seat the included TIE Pilot with his blaster pistol.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75162, 'Y-Wing™ Microfighter', 90, 'Shoot for the stars with the Y-Wing Microfighter!', 'Start a mini-scale LEGO® Star Wars adventure with this fun Y-Wing Microfighter, featuring dual flick missiles, front and rear-facing blasters, big engines, white, gray and yellow color scheme, and space to seat the included Y-Wing Pilot with his blaster pistol.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75163, 'Krennic\'s Imperial Shuttle™ Microfighter', 78, 'Fly in style with Krennic’s miniature Imperial Shuttle!', 'Recreate mini Star Wars: Rogue One adventures with Krennic\'s Imperial Shuttle Microfighter, featuring folding wings, two stud shooters and space to seat the included Imperial Shuttle Pilot with his blaster pistol.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75164, 'Rebel Trooper Battle Pack', 120, 'Patrol and defend Rebel territory!', 'Expand your army with the Rebel Trooper Battle Pack. Featuring a speederbike with stud blaster storage clips and space for a minifigure, plus a trench section featuring a multidirectional laser cannon with stud shooter and extra ammo, this great set makes the perfect addition to any LEGO® Star Wars collection. Includes four minifigures each with a stud blaster.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75165, 'Imperial Trooper Battle Pack', 112, 'Track down those Rebels!', 'Boost your LEGO® Star Wars™ collection with the Imperial Trooper Battle Pack. This set features an Imperial walker with space on top for a minifigure, posable legs, two laser cannons and elevating stud shooters and a stud blaster storage clip, plus four minifigures each armed with a stud blaster.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75166, 'First Order Transport Speeder Battle Pack', 117, 'Send in reinforcements with the First Order Transport Speeder!', 'Expand your LEGO® Star Wars forces with the First Order Transport Speeder Battle Pack, featuring space for 2 minifigures, front and rear stud shooters, and detachable stud blasters, batons and new-for-June-2017 shield elements for the First Order Stormtroopers. This set includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75167, 'Bounty Hunter Speeder Bike™ Battle Pack', 125, 'Go bounty hunting with the super-fast speeder bike!', 'Get Dengar, Bossk, IG-88 and 4-LOM on the move with their own custom Bounty Hunter Speeder Bike. With striking blue elements, 2 stud shooters and space on the back for a backpack, this speeder bike battle pack will send your LEGO® Star Wars adventures into overdrive!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75168, 'Yoda\'s Jedi Starfighter™', 262, 'Journey to the stars aboard Yoda’s starship!', 'Add a classic ship to your LEGO® Star Wars collection with Yoda’s Jedi Starfighter. The diminutive Jedi Master’s craft of choice features folding wings, front-and-top-opening minifigure cockpit, space for R2-D2 behind, and two laser cannons and spring-loaded shooters. Includes a minifigure and R2-D2.!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75169, 'Duel on Naboo™', 208, 'Battle it out at the generator core!', 'Play out exciting Jedi vs. Sith duels as Qui-Gon Jinn and Obi-Wan Kenobi go head-to-head against evil Darth Maul at the Naboo power generator. This detailed set features push-activated opening laser doors, a minifigure catapult function in the generator core and an opening purification chamber with removable ‘plasma’ element. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75170, 'The Phantom', 269, 'Join the Rebel battle aboard The Phantom!', 'Outrun Admiral Thrawn with the Rebel starfighter, The Phantom, featuring retracting landing gear, an opening minifigure cockpit that detaches in an emergency, dual spring-loaded shooters, an opening rear compartment with included storage box containing detonator, and space beside the cockpit for Kanan’s friendly Astromech Droid, Chopper. Includes two minifigures and a droid.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75171, 'Battle on Scarif', 419, 'Uncover the Death Star plans at the beach bunker!', 'Play out epic scenes from the blockbuster movie, Star Wars: Rogue One, on a mission to recover the top-secret Death Star plans from the heavily fortified beach bunker on planet Scarif. This feature-filled set includes a hidden weapons stash, exploding floor panels, sliding bunker doors with locking function, control panel, opening orange crate and the top-secret plans to the Empire’s Death Star. This set also includes four minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75172, 'Y-Wing Starfighter™', 691, 'Launch daring raids with the iconic Y-Wing Starfighter!', 'Expand your Rebel fleet with the iconic Y-Wing Starfighter. The unmistakable workhorse of the Rebel Alliance has been faithfully reproduced with LEGO® bricks and features many play starters, including retractable landing gear, an opening minifigure cockpit, rotating guns, dual spring-loaded shooters, and gearwheel-operated bomb-drop function. This great model also comes with a weapons loader with turning crane and extra ammo for even more immersive play. Includes four minifigures and a droid figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75173, 'Luke\'s Landspeeder™', 149, 'Go in search of Ben Kenobi in Luke’s Landspeeder!', 'Recreate unforgettable scenes on desert-planet Tatooine, as young Luke and C-3PO go in search of mysterious hermit Ben Kenobi in his landspeeder. This iconic model features a two-minifigure open cockpit, three engines and an opening trunk to store his electrobinoculars. There’s also a Tusken Raider and womp rat to keep the action level high. Includes four minifigures plus a womp rat figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75174, 'Desert Skiff Escape', 277, 'Avoid the deadly Sarlacc pit!', 'Play out exciting duels above the sand dunes with this iconic set featuring Jabba the Hutt’s ‘hovering’ skiff with extendable plank, storage hold and movable rudders at the back. Help Han Solo fend off Boba Fett and the skiff guard before his friend walks the plank and falls into the mighty Sarlacc’s minifigure-devouring mouth.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75175, 'A-Wing Starfighter™', 358, 'Prepare the A-wing for action!', 'Launch into LEGO® Star Wars missions with the high-speed A-Wing Starfighter, featuring an opening minifigure cockpit, retractable landing gear, rotating laser cannons and dual spring-loaded shooters. There’s also a service cart loaded with tools, extra ammo and a detachable access ladder to load the A-Wing Pilot into position. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75176, 'Resistance Transport Pod™', 294, 'Jettison to safety in the Resistance Transport Pod!', 'Make a quick escape with Finn and Rose in the Resistance Transport Pod. This detailed LEGO® Star Wars version of the craft from Star Wars: Episode VIII features a 2-minifigure cockpit with removable canopy and detachable panels that reveal a rear storage compartment with space for the included BB-8 figure and a weapon store. There’s also a stud shooter at the side, aimed by turning the rear engine, plus dual spring-loaded shooters underneath. Includes 2 minifigures and a BB-8 figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75177, 'First Order Heavy Scout Walker™', 554, 'Stomp into battle with the First Order Heavy Scout Walker!', 'Send General Hux and his crew into battle in the armored First Order Heavy Scout Walker. This impressive LEGO® Star Wars version of the walker inspired by the blockbuster Star Wars Episode VIII movie features a 2-minifigure cockpit with opening top hatch, elevating spring-loaded shooters at both sides, elevating guns at the front, missile storage clips and hidden wheels that turn to make the legs ‘crawl’. This set also includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75178, 'Jakku Quadjumper™', 457, 'Escape Jakku in the powerful Quadjumper!', 'Create your own action-packed LEGO® Star Wars adventures with the Jakku Quadjumper, featuring an opening 2-minifigure cockpit, opening rear compartment with gunner station, 2 front stud shooters, detachable rear stud blaster and 4 big engines with an explode function to send them flying. Includes 4 minifigures and a BB-8 figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75179, 'Kylo Ren\'s TIE Fighter™', 630, 'Speed into action with Kylo Ren’s TIE Fighter!', 'Create your own LEGO® Star Wars: Episode VIII battle adventures with Kylo Ren’s TIE Fighter. This model features large wings, red exhaust detailing, an opening minifigure cockpit and trigger-activated spring-loaded shooters. The set also includes 3 minifigures and a BB-9E figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75180, 'Rathtar™ Escape', 836, 'Escape from Bala-Tik and the dreaded Rathtars!', 'Recreate epic scenes from Star Wars: The Force Awakens, as Han Solo and Chewbacca try to escape the clutches of Bala-Tik and his Guavian Security Soldiers aboard their freighter. Featuring a modular design for easy reconfiguration, the freighter sections contain authentic details like a lowering blast door, trapdoor and crawlspace in which to hide. Pull the correct fuse to release the 2 buildable Rathtar figures with posable tentacles and teeth, then rearrange the sections and play out another Rathtar escape! This great set includes 5 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75181, 'Y-Wing Starfighter™', 1966, 'Collect the ultimate long-range Rebel starfighter!', 'Own part of Star Wars history with the Y-Wing Starfighter. This LEGO® Star Wars Ultimate Collector Series model has an amazing level of detail, including an opening minifigure cockpit for the included Gold Leader minifigure, wheel-activated rotating ion cannons on top, retractable landing skids and space for the R2-BHD astromech droid. This fantastic Star Wars toy also comes with a tilting display stand and informational fact plaque, making it the perfect centerpiece for your collection.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75182, 'Republic Fighter Tank™', 305, 'Pack a punch with the Republic Fighter Tank!', 'Engage the Droid Army with this LEGO® Star Wars Republic Fighter Tank, featuring an opening top hatch with minifigure cockpit, 2 elevating guns with stud shooters, rear ammo store and hidden wheels for a hover look. This set also includes 2 minifigures and 2 droid figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75183, 'Darth Vader™ Transformation', 282, 'Bring Darth Vader to life at the medical bay!', 'Recreate Anakin’s transformation into evil Darth Vader with this LEGO® brick recreation of the medical bay scene from Star Wars: Revenge of the Sith. This detailed set features a table with space for Anakin that lowers and flips to reveal Vader, Emperor Palpatine’s greatest creation. You can also slide his iconic helmet into position and, like he did in the movie, pretend to use the power of the Force to send the buildable droid and Lightsaber rack flying! This multi-function set includes 3 minifigures and 2 buildable medical droid figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75184, 'LEGO® Star Wars™ Advent Calendar', 309, 'Launch into the holidays with the LEGO® Star Wars Advent Calendar!', 'Open a door of this super-fun advent calendar each day in December to discover a LEGO® Star Wars themed minifigure, starship, vehicle or other collectible. There’s even a foldout playmat featuring images from Jakku, Starkiller Base and deep space for epic Star Wars encounters. This holiday gift is perfect for rebels, Sith Lords, Scavengers and any other life form, and includes 7 minifigures and a BB-8 figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75185, 'Tracker I', 557, 'Search out the Freemakers with Tracker I!', 'Play out your own LEGO® Star Wars: The Freemaker Adventures encounters with this impressive tri-wing Tracker I model, featuring spring-loaded shooters on each wing and side hatches that reveal a weapon store, access ladder and a prison cell with space for a minifigure. Open the 3 windows of the minifigure cockpit and attach the M-OC Hunter Droid using the special shoulder armor element, before swiveling it into position for flight mode. This great set includes 3 minifigures plus a buildable probe droid figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75186, 'The Arrowhead', 775, 'Go head to head with the Empire aboard The Arrowhead!', 'Act out perilous LEGO® Star Wars: The Freemaker Adventures missions with The Arrowhead. This aggressive-looking starship features a lift-off cockpit canopy with space for 3 minifigures and R0-GR inside, a transparent opening dome revealing the ship’s removable crystal power source element, 2 spring-loaded shooters and an impressive flip-out battering ram. There’s also a service cart with tools and ammo as an extra play starter.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75187, 'BB-8™', 1106, 'Play with and display your own brick-built BB-8!', 'This faithfully reproduced LEGO® Star Wars incarnation of the diminutive BB-8 droid from the new Star Wars movie trilogy makes the perfect gift for any Star Wars or LEGO fan. Turn one wheel at the side to rotate the detailed head, and another to open the access hatch and extend the ‘welding torch’. This faithfully reproduced model also comes with a display stand, decorative fact plaque and small BB-8 figure, making it a great display piece for any bedroom or office.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75188, 'Resistance Bomber', 780, 'Set out on heroic raids with the Resistance Bomber!', 'Play out action-packed LEGO® Star Wars: Episode VIII missions with the Resistance Bomber. This feature-packed model includes a button-activated bomb release function, spring-loaded shooters, 2 opening rear gun turrets with space for a minifigure, elevating rear guns, a 2-minifigure front cockpit with detachable canopy and a removable top section for easy access. It can also stand on any even surface when not in use. This set includes 5 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75189, 'First Order Heavy Assault Walker™', 1376, 'Stride into battle with the First Order Heavy Assault Walker!', 'Add a fearsome walker to your LEGO® Star Wars First Order army with the Heavy Assault Walker. This awesome model, based on the walker from the blockbuster Star Wars: Episode VIII movie, features tough armor-plate detailing, posable legs, posable head with opening minifigure cockpit and spring-loaded shooters, an aimable rapid-fire stud shooter on top, and detachable canisters that can be released from the rear of the walker. There’s also a storage compartment at the side with extra stud ammo and an opening hold to the rear with space for a minifigure and extra missile ammo. This amazing set also includes 5 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75190, 'First Order Star Destroyer™', 1416, 'Command the fleet with the awesome First Order Star Destroyer!', 'Embark on galactic Star Wars: Episode VIII adventures with the First Order Star Destroyer. This huge model features armor-like panels on the outside, transparent-element engine detailing at the back and 8 side-facing stud shooters. Open out the top panels to reveal the detailed interior, featuring a working elevator leading to Snoke’s command center with a seat and mini hologram figure, bridge with seating for the crew, conference area with buildable medical droid and BB-9E droid, and a passageway leading to a detailed control room. There’s even a carry handle to take the play action into hyperspeed! This stellar set includes 5 minifigures and 2 droids.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75191, 'Jedi Starfighter™ With Hyperdrive', 825, 'Play at warp speed with Obi-Wan’s Jedi Starfighter With Hyperdrive!', 'Speed across the galaxy with Obi-Wan’s Jedi Starfighter With Hyperdrive. This detailed LEGO® brick recreation of the ship featured in Star Wars: Attack of the Clones includes an opening minifigure cockpit, space for the R4-P17 Astromech droid top section and 2 stud shooters, while the large hyperdrive features 2 spring-loaded shooters, big engines, and a grab handle for enhanced play and quick release of the docked model. This impressive set also includes 3 minifigures and an Astromech droid figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75192, 'Millennium Falcon™', 7541, 'Travel the LEGO® galaxy in the ultimate Millennium Falcon!', 'Welcome to the largest, most detailed LEGO® Star Wars Millennium Falcon model we’ve ever created—in fact, with 7,500 pieces it’s one of our biggest LEGO models, period! This amazing LEGO interpretation of Han Solo’s unforgettable Corellian freighter has all the details that Star Wars fans of any age could wish for, including intricate exterior detailing, upper and lower quad laser cannons, landing legs, lowering boarding ramp and a 4-minifigure cockpit with detachable canopy. Remove individual hull plates to reveal the highly detailed main hold, rear compartment and gunnery station. This amazing model also features interchangeable sensor dishes and crew, so you decide whether to play out classic LEGO Star Wars adventures with Han, Leia, Chewbacca and C-3PO, or enter the world of Episode VII and VIII with older Han, Rey, Finn and BB-8!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75193, 'Millennium Falcon™ Microfighter', 92, 'Play at micro lightspeed with the Millennium Falcon!', 'Zoom into action with the Millennium Falcon Microfighter. This LEGO® Star Wars toy features lots of authentic detailing, 2 stud shooters and space to seat the included Chewbacca minifigure with his bowcaster.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75194, 'First Order TIE Fighter™ Microfighter', 91, 'Take on the Resistance in a micro-scale TIE Fighter!', 'Recreate action-packed space battles with the First Order TIE Fighter Microfighter. This LEGO® Star Wars toy features 2 flick missiles, space to seat the included First Order TIE Pilot minifigure with his blaster pistol, and red detailing from the craft featured in the Star Wars: The Force Awakens movie.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75195, 'Ski Speeder™ vs. First Order Walker™ Microfighters', 216, 'Pit First Order against Resistance in a micro planetside battle!', 'Enter the world of Star Wars: The Last Jedi with this LEGO® Microfighters dual pack. Featuring a Resistance Ski Speeder and First Order Heavy Assault Walker, each model includes stud shooters, lots of authentic detailing and space on top for a minifigure. This LEGO Star Wars toy also includes a small trench build with stud shooter and extra ammo as an extra play starter, and with separate building instructions for each model, Star Wars fans will love building with friends and family. Includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75196, 'A-Wing™ vs. TIE Silencer™ Microfighters', 188, 'Intercept Kylo Ren in a deep space microfighter duel!', 'Play in a Star Wars: The Last Jedi galaxy with this LEGO® Star Wars Microfighters dual pack, featuring a Resistance A-wing and Kylo Ren’s TIE Silencer. Each model includes dual flick missiles, lots of authentic detailing and space on top for a minifigure. This LEGO Star Wars toy also includes a mini maintenance station build as a bonus play starter, and with separate building instructions for each model, Star Wars fans will love sharing their building experience with friends and family. Includes Kylo Ren and A-Wing Pilot minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75197, 'First Order Specialists Battle Pack', 108, 'Advance on the Resistance with the First Order Specialists Battle Pack!', 'Expand your forces with the First Order Specialists Battle Pack. This LEGO® Star Wars toy features a rotating and elevating laser cannon with spring-loaded shooter and gunner’s seat, plus 4 minifigures with a selection of weapons.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75198, 'Tatooine™ Battle Pack', 97, 'Keep the Jawas busy on desert planet Tatooine!', 'Play out LEGO® Star Wars adventures with the Tatooine Battle Pack. This fun set features 2 Jawa minifigures plus a service vehicle with stud shooters and an articulated crane for picking up the included astromech droid. This LEGO Star Wars toy also includes a Tusken Raider minifigure, to keep any desert commander busy!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75199, 'General Grievous\' Combat Speeder', 157, 'Chase down the Jedi with General Grievous’ Combat Speeder!', 'Set out on high-speed LEGO® Star Wars adventures against Jedi Master Mace Windu, with General Grievous’ Combat Speeder. Featuring spring-loaded shooters, sleek design and storage underneath for the General’s 4 Lightsabers, this fast speeder from the highly successful Star Wars: The Clone Wars animated TV series is the perfect way to immerse any Star Wars fan in Sith vs. Jedi dueling action. This LEGO Star Wars toy includes a Mace Windu minifigure and General Grievous figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75200, 'Ahch-To Island™ Training', 241, 'Learn the Jedi way at the Ahch-To Island mountainside hut!', 'Join Master Luke as he trains Rey at his mountainside dwelling. This LEGO® Star Wars toy features a hut with detailed interior, removable roof section for easy play, small bonfire build and rotating training function with an opening boulder with knockaway feature. With 2 minifigures and a Porg figure, this LEGO brick version of Luke\'s dwelling from Star Wars: The Last Jedi will immerse any Star Wars fan in a galaxy of Jedi adventures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75201, 'First Order AT-ST™', 370, 'Seize control of the First Order AT-ST!', 'Play out a daring LEGO® Star Wars mission to make off with the partially constructed First Order AT-ST walker. This exciting LEGO Star Wars toy features an under-construction walker with posable legs, a wheel at the back for rotating the turret, and dual spring-loaded shooters for intense action play. The set also includes a buildable hangar lift, so your Resistance fighter can enjoy recreating exciting scenes with Finn, Rose, BB-8 and Captain Phasma from the blockbuster Star Wars: The Last Jedi movie.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75202, 'Defense of Crait™', 746, 'Join the battle at the Resistance base!', 'This exciting Defense of Crait LEGO® Star Wars toy has everything a Resistance warrior needs to play out the epic final battle from Star Wars: The Last Jedi. The set features a highly detailed Resistance Ski Speeder with spring-loaded shooters, removable engine section, minifigure cockpit and a lowering stabilizer. There\'s also a command tower with stud shooter on top and assorted weapons and tool elements, as well as a foldout trench section with rotating laser cannon and spring-loaded shooter, plus a gun emplacement with a stud shooter. Includes 5 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75204, 'Sandspeeder™', 278, 'Speed into action with the Sandspeeder!', 'Expand your LEGO® Star Wars collection with the Sandspeeder. This variant of the iconic Snowspeeder features some fascinating details, including desert camouflage elements, opening minifigure cockpit and button-activated spring-loaded shooters. There\'s also a toppling moisture vaporator, which any budding Sandspeeder pilot will love to use for target practice. This LEGO Star Wars toy includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75205, 'Mos Eisley Cantina™', 376, 'Stop by at Tatooine’s Mos Eisley Cantina!', 'Recreate iconic Star Wars: A New Hope scenes at Tatooine’s most perilous tavern, Mos Eisley Cantina. This detailed model has a modular, open-out design for easy play. Slide the door and enter the bar to reveal the detailed interior, which includes a counter for serving refreshments and 2 seat-tipping functions for reenacting the unforgettable encounter between Han Solo and bounty hunter, Greedo. You also get a Ubrikkian 9000 pod with an opening minifigure cockpit and stud shooter on top. This LEGO Star Wars toy includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75206, 'Jedi™ and Clone Troopers™ Battle Pack', 102, 'Take on the Separatists with the Jedi and Clone Troopers!', 'Command your own LEGO® Star Wars Jedi & Clone Trooper squad with this fun battle pack, featuring 2 Lightsaber-wielding Jedi warriors, 2 Clone Troopers with stud blasters and a speeder with stud shooters and rotating wingtip guns.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75207, 'Imperial Patrol Battle Pack', 99, 'Patrol the Empire and enforce the rule of law!', 'Play out Imperial law-enforcing scenarios with this imposing LEGO® Star Wars Imperial Patrol Battle Pack. Featuring a speeder with stud shooters, an Emigration Officer, Recruitment Officer and 2 Imperial Patrol Troopers, this Star Wars toy has everything your budding Imperial officer needs to keep their Star Wars minifigure collection under control!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75208, 'Yoda\'s Hut', 229, 'Train with Luke at Yoda’s Dagobah hideout!', 'Reenact an iconic LEGO® Star Wars training scene at Yoda’s Hut on Dagobah. This feature-packed set includes Yoda’s swamp home with foldout training sections, from where Luke can balance boxes and stand on one arm to demonstrate his fledgling Jedi powers. There\'s also a Force jump function that can be attached to the front or back of the model. Jump Luke from the roof and swing from the ‘vine\' with Yoda on his back. Inside, there\'s a folding bed, fireplace, a selection of food and furnishing elements, plus a secret compartment under the floor. There’s even a window at the side so R2-D2 can peer in! This feature-laden Star Wars toy includes 2 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75209, 'Han Solo\'s Landspeeder™', 345, 'Escape to safety with Han Solo’s Landspeeder!', 'Recreate high-speed LEGO® Star Wars action scenes from the Han Solo movie with Han’s Landspeeder. Featuring an open 2-minifigure cockpit, opening hood with storage compartment, removable engine, rear storage compartment with secret cargo, hidden wheels for a hover effect and 2 spring-loaded shooters, this action-packed Star Wars toy also includes a Corellian Hound figure for Han and Qi\'ra to battle.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75210, 'Moloch\'s Landspeeder™', 464, 'Go on the hunt with Moloch!', 'Recreate action-filled scenes from the Han Solo movie with this LEGO® Star Wars Moloch’s Landspeeder set. The infamous gang leader’s vehicle features an open minifigure cockpit, storage hold at the rear and hidden wheels for a cool hover effect. This Star Wars toy also has a 6-stud rapid shooter for intense action play, and an opening cage to hold the 2 Corellian Hound figures to add an extra dimension of battling fun for any LEGO Star Wars fan!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75211, 'Imperial TIE Fighter™', 519, 'Evade the mighty Imperial TIE Fighter!', 'Engage the enemy with the LEGO® Star Wars Imperial TIE Fighter! This brick-built version of the Empire’s iconic attack craft has a highly detailed design, including sturdy wings, opening minifigure cockpit and access hatch, and 2 spring-loaded shooters. This great Star Wars toy also includes 4 minifigures, including Han Solo and his accomplice Tobias Beckett.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75212, 'Kessel Run Millennium Falcon™', 1413, 'Jump to lightspeed in the Millennium Falcon!', 'Travel with Han Solo, Chewbacca and their friends with the LEGO® Star Wars Kessel Run Millennium Falcon. This LEGO brick version of the iconic Corellian freighter from the Han Solo movie features a 2-minifigure cockpit with detachable canopy, 2 spring-loaded shooters, sensor dish, ramp, rotating top and bottom laser turrets with 2 gunner seats, plus a detachable escape craft. This amazing Star Wars toy also features opening hull plates for easy access to the detailed interior, which includes a cargo area with couch and Dejarik hologame table, bar, bunk, missile storage compartment, and a buildable hyperdrive with repair tools. Also includes 6 minifigures and a DD-BD droid.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75523, 'Scarif Stormtrooper™', 89, 'Patrol the Scarif coastline with the armored Stormtrooper!', 'Defend the Empire’s territory with this buildable and highly posable LEGO® Star Wars Scarif Stormtrooper figure. Featuring a double-barrel blaster rifle with spring-loaded shooter and stud shooter, plus decorated helmet and armor, this sturdy and durable figure is great for recreating unforgettable action scenes from the movie, Star Wars: Rogue One.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75524, 'Chirrut Îmwe™', 87, 'Jump into action with warrior monk Chirrut Îmwe!', 'Trust your senses with this buildable and highly posable LEGO® Star Wars Chirrut Îmwe figure. Featuring his folding bowcaster with spring-loaded shooter, textile tunic and decorated elements, this sturdy and durable figure is perfect for reenacting action-packed scenes from the blockbuster movie, Star Wars: Rogue One.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75525, 'Baze Malbus™', 148, 'Blast the enemy with tough Baze Malbus!', 'Join the battle against the Empire with skilled warrior Baze Malbus. Featuring red chest and shoulder armor, plus a heavy cannon with spring-loaded shooter, spare ammo and back-mounted ‘power’ canister, this sturdy and durable LEGO® Star Wars figure is great for recreating action-packed scenes from the blockbuster movie, Star Wars: Rogue One.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75526, 'Elite TIE Fighter Pilot™', 94, 'Fly into action with the Elite TIE Fighter Pilot!', 'Battle it out with this buildable and highly posable LEGO® Star Wars Elite TIE Fighter Pilot figure. Featuring a red-striped helmet, shoulder decoration, breathing system detailing, plus a blaster rifle with spring-loaded shooter, any Star Wars fan would love flying into battle with this tough character.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75528, 'Rey', 85, 'Feel the Force with Rey!', 'Launch a Lightsaber attack with buildable and highly posable Rey. With textile detailing, chest and arm decoration, blue Lightsaber, blaster pistol and a wheel-activated arm-swinging battle function, any young would-be Jedi will love to act out Lightsaber battles with this LEGO® Star Wars figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75529, 'Elite Praetorian Guard', 92, 'Protect the First Order with the Elite Praetorian Guard!', 'Defend the upper echelon of the First Order with this buildable and highly posable Elite Praetorian Guard figure. This imposing figure features red-armor detailing with textile skirt, unique helmet design, and chest and arm decoration. It also has a lever on the back to send the arms swinging, plus a double-handed bladed staff that splits in two for furious single-handed weapon combat. Fans of the First Order will love running into battle with this expert fighter.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75530, 'Chewbacca™', 179, 'Lead the charge with Chewbacca!', 'Add a big Wookiee to your LEGO® Star Wars collection with this buildable and highly posable Chewbacca figure. Standing over 11” (30cm) tall, Chewbacca features ‘fur’ decoration, a detailed head, removable ammo belt and bag, and a bowcaster weapon with spring-loaded shooter and extra ammo. Young Wookiee warriors will love playing out heroic battles against iconic enemy characters.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75531, 'Stormtrooper™ Commander', 100, 'Join the battle with the 2-in-1 Stormtrooper Commander!', 'Issue the orders with this buildable and highly posable LEGO® Star Wars Stormtrooper Commander figure. Featuring a back-mounted heavy blaster with spring-loaded shooter, plus a pauldron with detachable ammo pouches, this imposing figure can be modified into a regular Stormtrooper with blaster for double the Imperial fun!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75532, 'Scout Trooper™ & Speeder Bike™', 452, 'Set out on speeder bike missions with the Scout Trooper!', 'Take your Star Wars adventures to a new level with this LEGO® Star Wars Scout Trooper & Speeder Bike set. The buildable and highly posable figure features pouch and bag detailing, iconic helmet and a detachable leg-mounted blaster pistol. Featuring a vehicle for the first time ever, this set also includes a LEGO brick recreation of the speeder bike from Star Wars: Episode VI Return of the Jedi, featuring a spring-loaded shooter, handlebar and footrests to mount the Scout Trooper, movable flaps, detailed panels and a handle underneath for enhanced play that also doubles as a stand.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75533, 'Boba Fett™', 144, 'Join the hunt with Boba Fett!', 'Bring in the bounty with this buildable and highly posable LEGO® Star Wars Boba Fett figure. The battle-scarred armor decoration with textile cape and helmet with lowering antenna/aiming device add a real feel of authenticity to this popular character from the Star Wars universe. Boba Fett is also armed with a blaster rifle with spring-loaded shooter and jet pack with integrated flick missile—the perfect accessories for tracking down bounties!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75534, 'Darth Vader™', 168, 'Join Darth Vader and battle to victory!', 'Rule with a plastic fist with this buildable and highly posable Darth Vader figure. This impressive figure features detailed armor and chest decoration, textile tunic and cape, and a detachable Lightsaber. Imperial leaders will love swinging his arm in battle using the wheel on his back, and lifting Lord Vader\'s helmet to reveal the scarred face of fallen Jedi warrior, Anakin Skywalker.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75535, 'Han Solo™', 101, 'Battle the bad guys with Han Solo!', 'Play out exciting adventures with this highly posable LEGO® Star Wars Han Solo buildable figure. This impressive galactic smuggler from the Han Solo movie features a large blaster weapon with spring-loaded shooter and hip-mounted, detachable blaster pistol. Star Wars fans of any age will love playing with this young LEGO Han Solo buildable toy.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75536, 'Range Trooper™', 101, 'Stomp into action with the Range Trooper!', 'Take on any adversary with this highly posable LEGO® Star Wars Range Trooper buildable figure. This powerful character from the blockbuster Han Solo movie features tough armor and ‘magnetic boot’ detailing, furry shoulder cloak and tunic, as well as a blaster weapon with spring-loaded shooter. Star Wars fans will love battling with this cool LEGO buildable figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75537, 'Darth Maul™', 104, 'Own a true Sith Lord with Darth Maul!', 'Bolster your LEGO® Star Wars collection with this highly posable Darth Maul buildable figure. This super agile character from the Star Wars universe features a highly detailed head, textile tunic and a double-bladed Lightsaber with wheel-operated arm-swinging battle function. Would-be Sith Lords will jump at the chance of entering battle with this amazing character!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75821, 'Piggy Car Escape', 74, 'Chase the piggy with lightning-fast Chuck and rescue the eggs!', 'Pitch speedy bird Chuck against the Piggy Car. Chase the car to try and take back the eggs, but watch out for its ice cream shooter in this fun set, based on The Angry BirdsTM Movie. Includes 2 figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75822, 'Piggy Plane Attack', 168, 'Launch a flying attack and rescue the eggs from the Piggy Plane!', 'Pilot Pig has taken off from Bird Island with 4 eggs in his plane and is making his escape. Shoot Red into the sky using the catapult and on to the Piggy Plane. Battle with the piggy and take control of the plane, and land it safely without damaging the eggs! Includes 2 figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75823, 'Bird Island Egg Heist', 277, 'Catapult into action and take back the eggs from the Piggy Trike!', 'Use the staircase catapult to launch Red into the air and race after the piggy, who is speeding off in the Piggy Trike with the eggs. Help him take the eggs out of the trike\'s box in this hilarious set, which also features Matilda\'s House to help Red relax, and a spinning Billy the Sign, based on The Angry BirdsTM Movie. Includes 3 figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75827, 'Firehouse Headquarters', 4634, 'Get ready to bust some ghosts at the Firehouse Headquarters!', 'Recreate iconic Ghostbusters™ scenes with the 2-storey Firehouse Headquarters, featuring laboratory, living quarters, containment unit and much more. Capture the ghosts with the proton packs and restore order, or solve other supernatural cases! Includes 9 minifigures: Peter Venkman, Raymond Stantz, Egon Spengler, Winston Zeddemore, Janine Melnitz, Dana Barrett, Louis Tully, Library Ghost and Zombie Driver.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75828, 'Ecto-1 & 2', 556, 'Speed after Mayhem with the LEGO® Ghostbusters™ Ecto-1 & 2 vehicles!', 'Speed after the demon ghost Mayhem with the Ecto-1 car and Ecto-2 motorbike. Lift the detachable roof off the Ecto-1 to fit the 4 Ghostbusters™ heroes inside, and place their gear in the rear storage area. Act out paranormal detection with the PKE Meter, place Kevin on the Ecto-2 motorbike or role-play other action-packed scenes from the 2016 Ghostbusters™ movie. Includes 5 minifigures and a Mayhem figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75871, 'Ford Mustang GT', 185, 'Break records in this American dream car!', 'Power across the desert with this buildable, minifigure-scale LEGO® Speed Champions version of the American muscle car famous for its V8 engine—the Ford Mustang GT. Play out different race-day scenarios with this set that features interchangeable wheel trims, a wrench and a timing-board element. Includes a Ford racing driver minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75872, 'Audi R18 e-tron quattro', 166, 'Refuel and race for victory!', 'Fuel racing dreams with this LEGO® Speed Champions version of one of the most successful track cars of all time. This buildable, minifigure-scale version of the Audi R18 e-tron quattro comes with interchangeable wheel trims, wrench and a fuel pump element. Includes an Audi racing driver minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75877, 'Mercedes-AMG GT3', 196, 'Customize the awesome AMG GT3 to race!', 'Show your skills as both an engineer and driver with this buildable LEGO® Speed Champions version of the Mercedes-AMG GT3. Customizable for race or road-driving modes, it features wheels with rubber tires, yellow rims and black trims, a removable front splitter, adjustable and removable rear wing, removable windshield and authentic racing colors and race-graphics stickers. Includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75878, 'Bugatti Chiron', 181, 'Build and drive the ultimate hyper car!', 'Gear up for quad-turbocharged action with this buildable LEGO® Speed Champions version of one of the world’s most exclusive hyper cars—the Bugatti Chiron. This vehicle features wheels with rubber tires, a removable windshield plus iconic and realistic details. Test your driving skills with the three included marker cones. Includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75879, 'Scuderia Ferrari SF16-H', 184, 'Speed into race action with the awesome Scuderia Ferrari SF16-H!', 'Power to victory with this buildable LEGO® Speed Champions version of the Scuderia Ferrari SF16-H race car, featuring wheels with rubber tires and two interchangeable race numbers so you can pretend to be different Scuderia Ferrari drivers. The set also includes a pit wall with start-finish-line, pit monitor element and checkered flag with waving function, plus wrench and walkie-talkie elements to maximize the role-play fun. Includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75880, 'McLaren 720S', 161, 'Design, build and race an incredible McLaren supercar!', 'Become a supercar designer and racing driver with the buildable LEGO® Speed Champions version of the McLaren 720S plus design studio. This buildable car features loads of authentic details and comes with a design desk and play-starting elements, including an original design sketch and printed 3D miniature version of the McLaren 720S. Also includes one minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75881, '2016 Ford GT & 1966 Ford GT40', 366, 'Race your friends to win a 24-hour race!', 'Get set for a historic race with LEGO® Speed Champions versions of the stunning 2016 Ford GT and 1966 Ford GT40 endurance cars. Each car features space for a racing driver minifigure, wheels with rubber tires, removable windshields and iconic details. With a race marshal minifigure plus a victory podium with a gold-colored trophy and checkered flag element, there’s everything needed to role-play a modern vs. classic 24-hour race. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75883, 'MERCEDES AMG PETRONAS Formula One™ Team', 941, 'Play every role of a top motor racing team on race day!', 'Role-play an entire race day with the MERCEDES AMG PETRONAS Formula One™ Team with this richly detailed LEGO® Speed Champions set, featuring 2 buildable Mercedes F1 W07 Hybrid cars. Packed with play-starting features and functions, it includes a fully equipped pit garage with car jack function, and a pit wall with monitor, checkered flag and translucent start-finish light-style elements. Dial up the big-race atmosphere with the TV camera rig with an adjustable camera arm, plus a grandstand with big screen and rotate function to reveal the winner’s podium. Includes eight minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75884, '1968 Ford Mustang Fastback', 183, 'Build, display and race the 1968 Ford Mustang Fastback!', 'Create a buildable LEGO® Speed Champions version of a classic car—the 1968 Ford Mustang Fastback. Ideal for display or racing, it features a minifigure cockpit, removable windshield, wheels with rubber tires and gold-colored rims, and authentic design details. This construction toy includes a minifigure and buildable ‘timing\' board to play out race scenarios.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75885, 'Ford Fiesta M-Sport WRC', 203, 'Drive the Fiesta M-Sport WRC to victory!', 'Display and race a buildable LEGO® Speed Champions version of the Fiesta M-Sport WRC, featuring a minifigure cockpit, removable windshield, 2 interchangeable hoods—including one with spotlight-style elements to play out low-light/nighttime racing scenarios, and authentic design details. This cool toy for kids includes a minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75886, 'Ferrari 488 GT3 “Scuderia Corsa”', 179, 'Team up with Ferrari “Scuderia Corsa” and triumph!', 'Create a buildable LEGO® Speed Champions version of the car that won the 2016 IMSA SportsCar series—the Ferrari 488 GT3 “Scuderia Corsa”, featuring a minifigure cockpit, removable windshield and authentic design details. This construction toy includes a minifigure and trophy to play out race scenarios.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75887, 'Porsche 919 Hybrid', 163, 'Race to win a 24-hour race with the Porsche 919 Hybrid!', 'Create a buildable LEGO® Speed Champions version of the Porsche 919 Hybrid endurance car, featuring a minifigure cockpit, removable windshield and authentic design details. This cool toy for kids includes a minifigure, plus a start/finish post and a laptop element to play out race scenarios.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75888, 'Porsche 911 RSR and 911 Turbo 3.0', 391, 'Stage a historic Porsche race!', 'Prepare for a modern vs. classic race with LEGO® Speed Champions versions of the awesome Porsche 911 RSR and 911 Turbo 3.0 cars, featuring minifigure cockpits, removable windshields and authentic design details. This building toy includes 3 minifigures, a lap counter, pit wall with a race-position board, and checkered flag elements to play out race scenarios.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75889, 'Ferrari Ultimate Garage', 841, 'Build, display and race iconic Ferrari race cars!', 'Create the Ferrari Ultimate Garage with a workshop/museum, attachable racetrack section and LEGO® Speed Champions versions of the classic Ferrari 250 GTO, 488 GTE and historic 312 T4 cars. Build the cars in the workshop, featuring an adjustable car ramp, vintage-style fuel pump and a tool rack, display a car in the museum, and race around the curbs and under the arch on the racetrack section. This construction toy includes 7 minifigures for endless role-play options.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75926, 'Pteranodon Chase', 126, 'Chase the Pteranodon and rescue it from danger!', 'Stage a fast-action pursuit scene inspired by Jurassic World™ and help Owen and the tracker save the Pteranodon. This exciting LEGO® dinosaur toy play set features a high-speed offroader with a net shooter, tranquilizer gun, 2 minifigures and a Pteranodon figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75927, 'Stygimoloch Breakout', 222, 'Stage a security breach with a dinosaur lab breakout!', 'Break out the Stygimoloch dinosaur with this action-packed play set inspired by Jurassic World™, featuring a laboratory with observation deck and a tilting workbench with breaking window function, connected to a dinosaur enclosure pen with 2 floodlights and a lifting gate. This fun toy for boys and girls includes 2 minifigures and a Stygimoloch figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75928, 'Blue\'s Helicopter Pursuit', 397, 'Rescue Blue the Velociraptor from Wheatley and the pilot!', 'Unite Owen with the faithful Velociraptor in this thrilling Blue’s Helicopter Rescue set, inspired by Jurassic World™. Wheatley has trapped Blue in a cage and attached it to his helicopter, featuring rotating blades, 6-stud shooter and dual searchlights. Set off in the quad bike with trailer and fire the crossbow, rescue the dinosaur and retrieve the dinosaur eggs. This cool toy for kids includes 3 minifigures and a Velociraptor figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75929, 'Carnotaurus Gyrosphere Escape', 577, 'Escape from the rampaging Carnotaurus!', 'Flee the flying lava rocks and a deadly dinosaur on Isla Nublar, with this dramatic Carnotaurus Gyrosphere Escape play set inspired by Jurassic World™. Help Owen, Claire and Franklin make their escape in the Gyrosphere or truck, featuring a 2-seater cab with sunroof, stud shooter, mobile control center and Gyrosphere trailer with launch function. The overgrown Gyrosphere station has an exploding lava rocks function, Gyrosphere launcher and a dinosaur nest. This fun toy includes 3 minifigures and 2 dinosaur figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75930, 'Indoraptor Rampage at Lockwood Estate', 1019, 'Rescue Maisie from the Indoraptor at Lockwood Estate!', 'Play out an epic dinosaur battle in this detailed set inspired by Jurassic World™. Help Owen, Claire and Blue rescue Maisie from the hybrid dinosaur inside the 3-level building, featuring configurable walls, a museum, laboratory, office, bedroom, removable windows, collapsing roof function and a large buildable triceratops skull. This toy for girls and boys includes 6 minifigures and 2 dinosaur figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75931, 'Dilophosaurus Outpost Attack', 289, 'Defend the outpost from the terrifying Dilophosaurus!', 'Brace the hunters for a fierce Dilophosaurus Outpost Attack in this fun play set inspired by Jurassic World™. Step down from the lookout tower and crane, featuring exploding gate and wall functions, crate and baby Dilophosaurus, and use the tranquilizer gun to stop the Dilophosaurus breaking through the fences. This dinosaur set includes 3 minifigures and 2 dinosaur figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75932, 'Jurassic Park Velociraptor Chase', 360, 'Play a game of hide and seek with the Velociraptor!', 'Recreate a classic scene from the original Jurassic Park movie with this fun LEGO® set that celebrates the 25th anniversary of the original blockbuster movie. Open the kitchen cabinet to hide Lex and Tim Murphy from the prowling Velociraptor, use the locking door function to keep the dinosaur out of the computer control room, then push it through the breakable window to continue the chase. This dinosaur set includes 4 minifigures and a Velociraptor figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (75933, 'T. rex Transport', 609, 'Help Zia round up the T. rex and save the day!', 'Track the Tyrannosaurus Rex in this big-action play set scene inspired by Jurassic World™ and return it to the transporter, featuring a single-seater truck, detachable container with opening and lockable side panels, and a mobile laboratory unit. This T. rex toy includes 3 minifigures and 2 dinosaur figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76025, 'Green Lantern vs. Sinestro', 174, 'Zoom into orbit and recover Green Lantern’s lantern!', 'Sinestro has stolen Green Lantern’s lantern and whisked it away to his home planet of Korugar. Launch a recovery mission with Green Lantern, in his ultra-fast construct spaceship and super-jumping Space Batman™! But evil Sinestro has built a cage around the lantern and is guarding it with his staff. Fire the 2 powerful stud shooters and turn the rear control to activate 2 devastating spring-loaded shooters. Spring into action with Space Batman™ on the Super Jumper to topple Sinestro and explode the cage. With victory assured, leap out of the cockpit and reclaim the lantern! Includes 3 minifigures with accessories: Green Lantern, Space Batman™ and Sinestro.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76029, 'Iron Man vs. Ultron', 92, 'Take down the Ultron jet with super-jumping Iron Man!', 'Team up with Iron Man MK45 to take on the Ultron army in an ultimate battle! Defend against aerial attacks from the Ultron vehicle piloted by the Ultron Sentry Officer. Take cover as Ultron Sentries leap from the back of the vehicle and fire their stud shooters. Then activate Iron Man’s Super Jumper to topple the Ultron Sentry Officer and bring the vehicle crashing to the ground! Includes 4 minifigures with assorted weapons and accessories: Ultron Sentry Officer, 2 Ultron Sentries and Iron Man MK45.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76044, 'Clash of the Heroes', 91, 'Get set for a Batman™ v Superman™ rooftop duel!', 'Armored Batman™ has glow-in-the-dark eyes and is firing his bazooka. Knock down the barrier with Superman\'s Super Jumper and explode the Bat-Signal. But beware—Armored Batman could launch from the rooftop at any moment! Who will win the Clash of the Heroes? Only you can decide!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76045, 'Kryptonite Interception', 306, 'Intercept the Kryptonite with the armored Batmobile!', 'Use Batman\'s Batmobile—featuring big wheels and opening doors—to battle for the Kryptonite. Fire the stud shooters and evade the forklift\'s flick missiles. Face off against LexCorp henchman\'s stud-shooting bazooka with Batman\'s silver Batarang and explode the Kryptonite cargo from the spring-loaded forklift. Includes 3 minifigures: Batman™ and 2 LexCorp henchmen.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76052, 'Batman™ Classic TV Series – Batcave', 2526, 'Drive the villains out from Batman\'s Batcave!', 'Help Batman™ and Robin™ to drive the villain intruders from the Batcave, featuring a Bat Lab with Batcomputer, plus the Batmobile with stud shooters, Batcopter with flick missiles and the Batcycle. This special model, based on the classic 1960s TV show, also has a Wayne Manor section with an exterior wall to climb on and Bruce Wayne’s study featuring the iconic Batphone and a false bookcase that slides open to reveal the secret entrance to the Batcave. Before spiraling down the Batpoles into the Batcave, change identity from Bruce Wayne™ and Dick Grayson™ into Batman and Robin (separate minifigures included). Includes 9 minifigures: Batman, Robin, Bruce Wayne, Dick Grayson, Alfred Pennyworth™, The Joker™, Catwoman™, The Riddler™ and The Penguin™.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76054, 'Batman™: Scarecrow™ Harvest of Fear', 563, 'Help Batman™ rescue the farmer from Scarecrow™ and Killer Moth™!', 'Stop Scarecrow™ and Killer Moth™ spreading fear on the outskirts of Gotham City with Gas Mask Batman\'s Batcopter, featuring an opening minifigure cockpit, 4 pop-out stud shooters and a 6-blade spinning rotor. Team up with Blue Beetle™ in aerial battle to protect the tractor-driving farmer. Evade the harvester\'s rotating cutters and detachable fear gas stud shooter, and prevent the villains capturing the farmer in its fear gas tank. Includes 5 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76055, 'Batman™: Killer Croc™ Sewer Smash', 759, 'Bite back against Killer Croc™ with the Bat-Tank!', 'Roll the Bat-Tank into action and fire the 6-stud shooter against Killer Croc\'s Battle Chomper. Drop bombs from the tank or deploy the ram weapon to crush Batman\'s enemies. Maneuver the motorbike out of reach of the Battle Chomper\'s movable tail and chomping teeth, and dodge the vehicle\'s flying boomerangs. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76056, 'Batman™: Rescue from Ra\'s al Ghul™', 257, 'Break out Robin™ from Ra\'s al Ghul\'s secret headquarters!', 'Smash through the gates of Ra\'s al Ghul\'s headquarters in Desert Batman\'s Buggy. Fire the Buggy\'s stud shooters and play out sword battle scenes against the villains, then create an explosion effect by pushing the cell door\'s lever to release Robin™ in this detailed set, featuring a winding staircase, Lazarus Pit catapult and a lever-operated swinging axe trap. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76060, 'Doctor Strange\'s Sanctum Sanctorum', 358, 'Banish the portal beast from Doctor Strange’s Sanctum Sanctorum!', 'Stage a mysterious battle at Doctor Strange’s Sanctum Sanctorum, featuring a portal beast with moving tentacles, eyes and teeth. Use the levitating function levers to hover the Super Heroes around the house. Attach the cape of levitation to Doctor Strange and fly him towards the portal beast to use the mystical artifacts in battle. Trap a minifigure in the tentacles and stage a heroic rescue. Includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76067, 'Tanker Truck Takedown', 330, 'Jump to the rescue and control the blaze with the Avengers and Spider-Man!', 'Launch Captain America and Hawkeye against Spider-Man and Vision at the airport. Create an explosion effect by twisting the truck’s wheel cog to pop up the flames. Use the Super Jumper to launch Spider-Man at the burning truck and put out the fire, push the wind sock to trigger the exploding barrel function, and jump Hawkeye over the flame elements on his motorbike. Combine this set with 76051 Super Hero Airport Battle for an even bigger clash. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76068, 'Mighty Micros: Superman™ vs. Bizarro™', 93, 'Stage a Kryptonite clash with Superman™ and Bizarro™!', 'Pit Superman™ against Bizarro™ in this fun Mighty Micros set. Each vehicle is the perfect size for these short-legged minifigures and features a seat on top and big fists that are perfect for fast-paced battling fun. Each character also comes with its own Kryptonite accessory element.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76069, 'Mighty Micros: Batman™ vs. Killer Moth™', 83, 'Fly Batman™ into battle against Killer Moth™!', 'Place Batman™ inside the cockpit of the Batcopter and stage an aerial battle between the two Mighty Micros vehicles. Spin the Batcopter’s blades and chase Killer Moth™ in his bug-shaped vehicle, featuring insect eyes, wings and a tail. Throw the Batarang against the Super-Villain, then play out a battle on the ground using Killer Moth’s cocoon gun. Includes two minifigures with mini legs.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76070, 'Mighty Micros: Wonder Woman™ vs. Doomsday™', 85, 'Dive into battle against Doomsday™ with Wonder Woman™!', 'Stage a face-off between Wonder Woman™ and Doomsday™ in this fun Mighty Micros play set. Dodge Doomsday’s club by driving—or flying—Wonder Woman’s Invisible Jet, then retaliate with her sword. Includes two minifigures with mini legs.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76071, 'Mighty Micros: Spider-Man vs. Scorpion', 79, 'Begin a battle of the bugs with Spider-Man and Scorpion!', 'Role-play a daring duel between Spider-Man and his venomous enemy Scorpion. Scorpion’s Mighty Micros car features movable pincers and tail with sting, while Spider-Man’s blue and red buggy features exhaust pipes. The super villain also has a mini-scorpion to match Spider-Man’s mini-spider. Includes two minifigures with mini legs.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76072, 'Mighty Micros: Iron Man vs. Thanos', 94, 'Thrust Iron Man into battle against evil Thanos!', 'Play out a fun Mighty Micros battle between two powerful rivals. Iron Man’s car features rear rocket thrusters for fast-play action and includes a wrench to dismantle his enemy’s car. Thanos’ Mighty Micros car features five Infinity gem elements and movable front fingers that resemble the Infinity Gauntlet. Includes two minifigures with mini legs.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76073, 'Mighty Micros: Wolverine vs. Magneto', 85, 'Take a swipe at Magneto with the mighty Wolverine!', 'Stage a mutant-powered battle between Wolverine and Magneto. Wolverine has long claws and a Mighty Micros jet featuring extendable wings to help him escape being pulled in by Magneto’s magnet-shaped car and magnetic powers. Includes 2 minifigures with mini legs.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76075, 'Wonder Woman™ Warrior Battle', 286, 'Help Wonder Woman™ defeat the villainous Ares™!', 'Take off into an epic LEGO® DC Super Heroes battle against the buildable Ares™ figure with his horned helmet, giant sword and shield. Use Wonder Woman’s superhuman powers and iconic sword and shield to tackle the mythical deity, then team up with pilot Steve Trevor™ in his fighter plane with flick missiles. Includes 2 minifigures plus buildable Ares™ figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76076, 'Captain America Jet Pursuit', 160, 'Retrieve Captain America\'s shield from evil Super-Adaptoid!', 'Ms. Marvel is on a mission to help retrieve Captain America’s shield from Super-Adaptoid, who is shooting back with his Power Blasts. Use her super-extending arms to attach her to the jet, which features movable wings for flying and attack modes, a minifigure cockpit with space for a shield, and dual disc shooters. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76077, 'Iron Man: Detroit Steel Strikes', 377, 'Send in Iron Man to rescue Agent Coulson from Detroit Steel!', 'Help Iron Man rescue Agent Coulson from Justin Hammer in his highly posable Detroit Steel weaponized mech with minifigure cockpit, arm-mounted chainsaw and 6-stud shooter. Agent Coulson’s classic car features foldable wheels for high-flying role-play adventures. Includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76078, 'Hulk vs. Red Hulk', 375, 'Get ready for a clash of the Hulks!', 'Pitch Team Hulk against Team Red Hulk in this sturdy LEGO® Marvel Super Heroes set. Fit the characters onto their tough vehicles and crash them into each other to send the big figures flying into battle. For even more fun battle action, fire the vehicle-mounted twin stud shooters and 6-stud shooter. Includes 2 minifigures and 2 big figures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76079, 'Ravager Attack', 197, 'Team up with Mantis and Rocket and fight back against Taserface!', 'Stage a forest face-off between Taserface in his M-ship, featuring four stud shooters and a minifigure cockpit, and Rocket and Mantis, who are hiding in the forest setting featuring a buildable tree with branch elements. Help the two Guardians of the Galaxy build the six-stud shooter, then fire at the approaching M-ship and work as a team to fend off the Ravagers. Includes three minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76080, 'Ayesha\'s Revenge', 323, 'Team up to take on Ayesha and save the galaxy!', 'Stage a cosmic battle with this action-packed Guardians of the Galaxy set featuring Ayesha’s Golden Drone spaceship with two stud shooters, and Yondu’s Laser Drill spaceship with a spring-loaded missile, sliding minifigure cockpit and opening side panels. Includes three minifigures and a Groot figure in Ravager costume.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76082, 'ATM Heist Battle', 185, 'Foil the masked robbers’ bank raid!', 'Help Spider-Man to stop the masked robbers burglarizing the bank in this action-packed LEGO® Marvel Super Heroes ATM Heist Battle set. The bank opens out for easy play and features an exploding window function, a removable ATM and an ATM with an explode function to send LEGO cash elements flying everywhere. The 2 robbers are equipped with a stud-shooting ATM Buster and a gun with hybrid-tech chain to drag the removable ATM away, plus a getaway bike. Attach and fire Spider-Man’s Power Blast weapons to take down the villains. Includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76083, 'Beware the Vulture', 375, 'Intercept The Shocker and take down the Vulture!', 'Team up with Spider-Man and Iron Man to catch up with The Shocker’s Van and tackle the Vulture’s attacks in this thrilling LEGO® Marvel Super Heroes Beware the Vulture set. The Shocker’s Van opens up for easy play and includes a mounted, adjustable 6-stud rapid shooter, a buildable rifle and buildable tech egg, while Vulture’s wings have 2 detachable stud shooters. Includes 4 minifigures with assorted weapons and accessory elements such as Spider-Man’s firing Power Blasts.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76084, 'The Ultimate Battle for Asgard', 400, 'Fight for the future of Asgard!', 'Fly the Commodore spaceship and team up with Thor, Bruce Banner and Valkyrie to take on Hela, her Berserkers and the Fenris wolf in this exciting LEGO® Marvel Super Heroes The Ultimate Battle for Asgard set. The Commodore has 2 dual stud shooters and a minifigure-drop function, while the buildable Fenris wolf figure features posable joints for different battle poses. Includes 6 minifigures with assorted weapons such as Thor and Hela’s firing Power Blasts to intensify the role-play action.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76085, 'Battle of Atlantis', 197, 'Protect the precious Mother Box from the evil Parademon™!', 'Team up with Aquaman™ and the Atlantean guards to stop the super-jumping Parademon™ stealing the Mother Box in this all-action LEGO® DC Comics Super Heroes Battle of Atlantis set. The underwater Atlantis scene features a grand arch to knock over with the Parademon’s Super Jumper. Also includes the Mother Box and 4 minifigures with assorted weapons to add to the role-play battle fun.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76086, 'Knightcrawler Tunnel Attack', 622, 'Fight for the Mother Box with Batman’s Knightcrawler!', 'Drive and crawl with Batman’s all-terrain vehicle and reclaim the Mother Box from the evil Parademons, in this exciting LEGO® DC Comics Super Heroes Knightcrawler Tunnel Attack set. The Knightcrawler features 4 posable limbs, each with 2-wheel tracks, plus dual 6-stud rapid shooters and an opening cockpit for Batman™. Includes 4 minifigures with weapons—including Batman’s Batarang, The Flash’s 2 Power Blasts and the Parademons’ handheld stud shooters—to ramp up the role-play battle action.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76087, 'Flying Fox: Batmobile Airlift Attack', 955, 'Unleash the Batmobile from The Flying Fox!', 'Team up with the Justice League against Steppenwolf™ and the Parademons to claim the precious Mother Box, in this exciting LEGO® DC Comics Super Heroes Flying Fox: Batmobile Airlift Attack set. The Flying Fox features a 2-minifigure cockpit with a lift-off canopy, 2 spring-loaded shooters, 2 stud shooters and space inside for the Batmobile with an opening cockpit, 3 stud shooters and adjustable wings. Includes 6 minifigures with weapons—including Cyborg’s attachable stud-shooting arm—plus a Steppenwolf big figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76088, 'Thor vs. Hulk: Arena Clash', 492, 'Battle for freedom in the arena with Hulk and Thor!', 'Role-play an arena duel between Thor and Hulk and then team up with these two old friends to topple Grandmaster. This awesome LEGO® Marvel Super Heroes Thor vs. Hulk: Arena Clash set features an arena with a sliding gate, secret weapons rack, 2 toppling pillars, smash-function wall and an opening prison cell. Use Thor’s super jumper to knock Grandmaster off his throne and Loki off his seat. Includes 4 minifigures plus a Hulk big figure with assorted weapons and accessories to intensify the action play.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76089, 'Mighty Micros: Scarlet Spider vs. Sandman', 89, 'Jet into a fun-packed Scarlet Spider vs. Sandman clash!', 'Stage a LEGO® Marvel Super Heroes Mighty Micros duel between Scarlet Spider\'s Spider Jet and his super villain enemy Sandman’s Sand Loader. Scarlet Spider is equipped with a spade element and Sandman has a sand mallet to add to the role-play battle fun. This cool superhero toy for kids includes 2 minifigures with mini legs.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76090, 'Mighty Micros: Star-Lord vs. Nebula', 86, 'Help Star-Lord grab the stolen mixtape from Nebula!', 'Join Star-Lord in a LEGO® Marvel Super Heroes Mighty Micros pursuit of villain Nebula. Match Star-Lord’s Milano vehicle against Nebula’s Necrocraft, which features vehicle-bashing reinforced side armor. Star-Lord has a reversible 2-faced head and is equipped with a space blaster to help him retrieve his stolen mixtape element from Nebula. This popular superhero toy for kids includes 2 minifigures with mini legs.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76091, 'Mighty Micros: Thor vs. Loki', 79, 'Match Thor against Loki in an epic Mighty Micros clash!', 'Stage a sibling showdown with this fun LEGO® Marvel Super Heroes Mighty Micros: Thor vs. Loki set, featuring Thor’s Mighty Micros car with adjustable wing elements and Loki’s Mighty Micros car with Viking horn elements. Loki is equipped with a scepter and Thor has his iconic Mjölnir hammer to add to the role-play action. This fun superhero toy for kids includes 2 minifigures with mini legs.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76096, 'Superman™ & Krypto™ Team-Up', 199, 'Help Superman™ bust out of the Kryptonite prison!', 'Join Krypto™ the Superdog’s bid to release Superman™ with this LEGO® DC Super Heroes Superman & Krypto Team-Up set, featuring Lobo’s Space Hog bike, a Kryptonite prison, buildable red Energy Infuser and assorted translucent-green Power Burst elements to customize your builds and minifigures. Fire the Space Hog bike\'s stud shooters and use its bomb-dropping function to activate the prison\'s explode function. This cool superhero toy for kids includes 2 minifigures and a Krypto the Superdog figure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76097, 'Lex Luthor™ Mech Takedown', 406, 'Power up for battle against the Lex Luthor™ Mech!', 'Team up with the Justice League heroes to grab the Energy Infuser back from Cheetah™, with this LEGO® DC Super Heroes Lex Luthor™ Mech Takedown set. The mech features an opening minifigure cockpit/escape pod, adjustable 6-stud rapid shooter and attachment points for 3 collectible Energy Infusers. This superhero toy for boys and girls also includes Batman\'s Bat-Glider with 2 stud shooters, the buildable green Energy Infuser, 5 minifigures, plus assorted translucent-orange Power Burst elements to customize your builds and minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76098, 'Speed Force Freeze Pursuit', 271, 'Pursue Reverse Flash™ and grab the Energy Infuser!', 'Dash with The Flash™ to catch Reverse Flash™ and match the awesome CyborgCopter against Killer Frost’s Ice Car, with this LEGO® DC Super Heroes Speed Force Freeze Pursuit set. The CyborgCopter has a net shooter and detachable weapons that double as minifigure weapons, while the Ice Car features an adjustable bulldozer blade and 2 stud shooters. This superhero toy for kids includes the buildable blue Energy Infuser, 4 minifigures and assorted translucent-ice-blue Power Burst elements to customize your builds and minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76099, 'Rhino Face-Off by the Mine', 229, 'Battle Killmonger for the precious vibranium with Black Panther!', 'Team up with Black Panther and Okoye in a Rhino Face-Off by the Mine against masked super villain Killmonger. This LEGO® Marvel Super Heroes set features a posable rhino figure with stud shooters and a rail track with moving mining cart. Tip the mining cart or activate the rail track\'s explode function to knock over the cart and spill the vibranium. This exciting set includes 3 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76100, 'Royal Talon Fighter Attack', 358, 'Capture Killmonger with Nakia’s awesome Royal Talon Fighter!', 'Help Black Panther and Nakia win the ultimate battle against super villain Killmonger and Ulysses Klaue, with this awesome LEGO® Marvel Super Heroes Royal Talon Fighter Attack set. The Royal Talon Fighter features an opening minifigure cockpit, 2 stud shooters and a rear prison compartment to trap a minifigure. The set also includes 4 minifigures with weapons to intensify the role-play conflict.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76101, 'Outrider Dropship Attack', 124, 'Defend Wakanda from attack with the Avengers!', 'Join Captain America and Black Widow’s battle to repel the Outriders and save Wakanda with this action-packed LEGO® Marvel Super Heroes 76101 Outrider Dropship Attack set!
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76102, 'Thor\'s Weapon Quest', 223, 'Find Thor’s ultimate weapon!', 'Join Thor, Rocket and Groot on a thrilling Avengers mission with LEGO® Marvel Super Heroes 76102 Thor’s Weapon Quest. This super hero toy features an Escape Pod with an opening cockpit for 3 minifigures and 2 stud shooters, plus a space station with a cosmic power source, weapon and features, the Infinity Stone element and stand, 3 minifigures and 10 Power Burst elements.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76103, 'Corvus Glaive Thresher Attack', 416, 'Repel Corvus Glaive’s thresher attack on the Wakandan wall!', 'Stage an awesome battle at the Wakandan wall with Vision, Shuri and Black Panther against Corvus Glaive and an Outrider with this LEGO® Marvel Super Heroes 76103 Corvus Glaive Thresher Attack set. The wall features a lever-operated opening gate, tower with rotating, dual stud-shooting turrets, hidden disc shooter, Wakandan lab with flip function and the Infinity Stone element. The bad guys are attacking with a Thresher launcher—hit the right spot on the wall with the Thresher to activate the lab’s flip function. This super hero toy also includes 5 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76104, 'The Hulkbuster Smash-Up', 375, 'Bash the ball-shooting gun turret with the Hulkbuster!', 'Overpower Proxima Midnight and the Outrider with Bruce Banner’s Hulkbuster in this LEGO® Marvel Super Heroes 76104 The Hulkbuster Smash-Up set. The posable Hulkbuster features an opening minifigure cockpit and bashing arm function. This action-packed set also includes a ball-shooting gun turret with an opening rear compartment containing the Infinity Stone element, Falcon\'s buildable wings with a detachable Redwing drone element and 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76105, 'The Hulkbuster: Ultron Edition', 1363, 'Create and show off the mighty Hulkbuster!', 'Build and display this superhero toy—a highly detailed LEGO® brick version of the Hulkbuster mech, featuring a rotating torso, posable fingers, arms, legs and feet, and glow-in-the-dark elements. Choose from 2 interchangeable left arms, including a jackhammer arm with punching function, and activate the LEGO light brick in the chest. This LEGO Marvel Super Heroes The Hulkbuster: Ultron Edition set also includes a display platform with alternate attachment points for posable robotic construction arms and a desk, plus a new-for-March-2018 Iron Man Mark 43 minifigure.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76107, 'Thanos: Ultimate Battle', 674, 'Battle Thanos for the Infinity Gauntlet with the Avengers!', 'Fly into conflict on an uncharted planet aboard The Guardians’ Ship with Iron Man, Star-Lord and Gamora in this LEGO® Marvel Super Heroes 76107 Thanos: Ultimate Battle set. The Guardians’ Ship features an opening cockpit for 2 minifigures seated on the space scooter, stud shooters, plus an opening rear compartment with capacity for 2 minifigures and the Infinity Gauntlet and stand. The Infinity Gauntlet, which has attachment points for the included Infinity Stone and other collectable Infinity Stone elements, can be attached to the Thanos big figure. This exciting set features 3 minifigures with assorted weapons and 10 Power Burst elements.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (76108, 'Sanctum Sanctorum Showdown', 1004, 'Stop Cull Obsidian and Ebony Maw stealing the Infinity Stone!', 'Stage a LEGO® Marvel Super Heroes 76108 Sanctum Sanctorum Showdown between Iron Spider-Man, Iron Man and Doctor Strange and the super villains. This all-action set features a foldable, 3-level New York City building including Doctor Strange’s Sanctum Sanctorum, with an exploding wall function and hidden Infinity Stone element, plus a pizzeria and Peter Parker\'s apartment, both with exploding window functions. The rooftop has a minifigure-launch function and a water tower with minifigure-winch function for Iron Spider-Man. This superhero toy also includes a detachable street corner scene, plus 4 minifigures and a big figure with weapons and 20 Power Burst elements.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (853516, 'LEGO® NEXO KNIGHTS™ Monsters Army-Building Set', 30, 'Grow Jestro\'s army with these hot-headed Lava monsters!', 'Join the ranks of Jestro\'s legion of evil minions with this LEGO® NEXO KNIGHTS™ Monsters Army-Building Set. Help him find the magic books scattered across the kingdom of Knighton and the power will be all yours! Makes a great gift for fans of NEXO KNIGHTS play sets. Includes 4 minifigures.
INSERT INTO `lego_set` (`prod_id`, `set_name`, `piece_count`, `prod_desc`, `prod_long_desc`, `age_id`, `difficulty_id`, `theme_id`) VALUES (853638, 'THE LEGO® BATMAN MOVIE Batman™ Minifigure Collector Frame', 61, 'Display THE LEGO® BATMAN MOVIE minifigures!', 'Show off up to 20 THE LEGO® BATMAN MOVIE minifigures in this stylish black and yellow collector frame. Hang the frame on the wall, stand it on a table, shelf or mantelpiece, or lay it down flat—the choice is yours. Makes a great gift for fans of THE LEGO BATMAN MOVIE.
